const RestaurantMenu: React.FC<{ 
  restaurant: Restaurant, 
  onClose: () => void, 
  onCheckout: (cart: CartItem[]) => void 
}> = ({ restaurant, onClose, onCheckout }) => {
  const [cart, setCart] = useState<CartItem[]>([]);

  const addToCart = (item: MenuItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { id: item.id, name: item.name, price: item.price, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.map(i => i.id === id ? { ...i, quantity: Math.max(0, i.quantity - 1) } : i).filter(i => i.quantity > 0));
  };

  const total = cart.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);

  return (
    <div className="fixed inset-0 bg-white z-[1100] flex flex-col animate-in slide-in-from-left duration-300">
       <div className="bg-slate-900 p-8 pt-14 text-white flex justify-between items-center shadow-xl">
          <button onClick={onClose} className="p-3 bg-white/10 rounded-2xl"><ArrowRight className="h-6 w-6" /></button>
          <div className="text-right">
             <h3 className="text-2xl font-black">{restaurant.name}</h3>
             <p className="text-xs font-bold text-emerald-400">{restaurant.category}</p>
          </div>
       </div>

       <div className="flex-1 overflow-y-auto p-6 space-y-4 no-scrollbar bg-slate-50">
          <h4 className="text-lg font-black text-slate-800 mb-6 text-right px-2">قائمة الطعام المتاحة</h4>
          {restaurant.menu?.map(item => (
            <div key={item.id} className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100 flex justify-between items-center">
               <div className="flex items-center gap-4">
                  <div className="flex items-center gap-3 bg-slate-50 p-2 rounded-2xl">
                     <button onClick={() => addToCart(item)} className="p-2 bg-emerald-500 text-white rounded-xl active:scale-75 transition-all"><Plus className="h-4 w-4" /></button>
                     <span className="font-black text-lg w-6 text-center">{cart.find(i => i.id === item.id)?.quantity || 0}</span>
                     <button onClick={() => removeFromCart(item.id)} className="p-2 bg-rose-50 text-rose-500 rounded-xl active:scale-75 transition-all"><Trash className="h-4 w-4" /></button>
                  </div>
                  <div className="text-left">
                     <p className="font-black text-emerald-600">{item.price} ج.م</p>
                  </div>
               </div>
               <div className="text-right">
                  <p className="font-black text-slate-800 text-lg">{item.name}</p>
                  <p className="text-[10px] font-bold text-slate-400">{item.description || 'من أشهر أطباق أشمون المميزة'}</p>
               </div>
            </div>
          ))}
       </div>

       {cart.length > 0 && (
         <div className="p-8 bg-white border-t border-slate-100 animate-in slide-in-from-bottom pb-12">
            <div className="flex justify-between items-center mb-6">
               <p className="text-2xl font-black text-slate-900">{total} <span className="text-xs opacity-40">ج.م</span></p>
               <p className="text-xs font-black text-slate-400 uppercase tracking-widest">إجمالي الطلب</p>
            </div>
            <button onClick={() => onCheckout(cart)} className="w-full bg-[#10b981] text-white py-7 rounded-[2.5rem] font-black text-lg shadow-2xl flex items-center justify-center gap-4 active:scale-95 transition-all">
               <ShoppingBag className="h-6 w-6" /> اطلب الآن عبر وصـــلــهــا
            </button>
         </div>
       )}
    </div>
  );
};

