                       <div className="text-right"><p className="text-[11px] font-black opacity-60 uppercase mb-2 tracking-widest">مشوار نشط الآن</p><h3 className="text-2xl font-black tracking-tight leading-none">الكابتن في طريقه إليك</h3></div>
