const RestaurantMenu: React.FC<{ 
  restaurant: Restaurant, 
  onClose: () => void, 
  onCheckout: (cart: CartItem[]) => void 
}> = ({ restaurant, onClose, onCheckout }) => {
  const [cart, setCart] = useState<CartItem[]>([]);

  const addToCart = (item: MenuItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { id: item.id, name: item.name, price: item.price, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.map(i => i.id === id ? { ...i, quantity: Math.max(0, i.quantity - 1) } : i).filter(i => i.quantity > 0));
  };

  const total = cart.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);

  return (
    <div className="fixed inset-0 bg-white z-[1100] flex flex-col animate-in slide-in-from-left duration-300">
       {/* هيدر المطعم */}
       <div className="bg-slate-900 p-8 pt-14 text-white flex justify-between items-center shadow-xl relative overflow-hidden">
          <div className="absolute top-0 right-0 w-full h-full opacity-20 pointer-events-none">
             {restaurant.photoURL && <img src={restaurant.photoURL} className="w-full h-full object-cover blur-lg scale-110" />}
          </div>
          <button onClick={onClose} className="p-3 bg-white/10 rounded-2xl relative z-10 hover:bg-white/20 transition-all">
             <ArrowRight className="h-6 w-6" />
          </button>
          <div className="text-right relative z-10">
             <h3 className="text-2xl font-black">{restaurant.name}</h3>
             <p className="text-xs font-bold text-emerald-400">{restaurant.category}</p>
          </div>
       </div>

       {/* قائمة الطعام */}
       <div className="flex-1 overflow-y-auto p-6 space-y-6 no-scrollbar bg-slate-50">
          <div className="px-2">
             <h4 className="text-lg font-black text-slate-800 mb-2 text-right">قائمة الطعام المتاحة</h4>
             <p className="text-[10px] font-bold text-slate-400 text-right uppercase tracking-widest">اختر وجباتك المفضلة</p>
          </div>

          {restaurant.menu && restaurant.menu.length > 0 ? (
            restaurant.menu.map(item => (
              <div key={item.id} className="bg-white p-5 rounded-[2.5rem] shadow-sm border border-slate-100 flex justify-between items-center group hover:shadow-md transition-all">
                 <div className="flex items-center gap-4">
                    <div className="flex items-center gap-2 bg-slate-50 p-2 rounded-2xl">
                       <button onClick={() => addToCart(item)} className="p-2.5 bg-emerald-500 text-white rounded-xl active:scale-75 transition-all shadow-lg shadow-emerald-500/20"><Plus className="h-4 w-4" /></button>
                       <span className="font-black text-lg w-6 text-center">{cart.find(i => i.id === item.id)?.quantity || 0}</span>
                       <button onClick={() => removeFromCart(item.id)} className="p-2.5 bg-rose-50 text-rose-500 rounded-xl active:scale-75 transition-all"><Trash className="h-4 w-4" /></button>
                    </div>
                    <div className="text-left">
                       <p className="font-black text-emerald-600 text-lg">{item.price} <span className="text-[10px]">ج.م</span></p>
                    </div>
                 </div>
                 <div className="flex items-center gap-5 flex-row-reverse text-right">
                    <div className="w-20 h-20 bg-slate-50 rounded-[1.8rem] overflow-hidden shadow-inner border border-slate-100 shrink-0">
                       {item.photoURL ? <img src={item.photoURL} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" /> : <UtensilsCrossed className="p-6 text-slate-200" />}
                    </div>
                    <div>
                       <p className="font-black text-slate-800 text-lg leading-tight">{item.name}</p>
                       <p className="text-[10px] font-bold text-slate-400 mt-1">{item.description || 'من أشهر أطباق أشمون المميزة'}</p>
                    </div>
                 </div>
              </div>
            ))
          ) : (
            <div className="py-20 text-center text-slate-300 font-bold">عذراً، المنيو غير متوفر حالياً</div>
          )}
       </div>

       {/* السلة والطلب */}
       {cart.length > 0 && (
         <div className="p-8 bg-white border-t border-slate-100 animate-in slide-in-from-bottom pb-12 shadow-[0_-20px_40px_rgba(0,0,0,0.05)]">
            <div className="flex justify-between items-center mb-6">
               <div className="text-left">
                  <p className="text-2xl font-black text-slate-900">{total} <span className="text-xs opacity-40">ج.م</span></p>
                  <p className="text-[9px] font-bold text-emerald-600 tracking-tighter">+ تكلفة التوصيل تضاف عند التنفيذ</p>
               </div>
               <p className="text-xs font-black text-slate-400 uppercase tracking-widest">إجمالي السلة</p>
            </div>
            <button onClick={() => onCheckout(cart)} className="w-full bg-[#10b981] text-white py-7 rounded-[2.5rem] font-black text-lg shadow-2xl flex items-center justify-center gap-4 active:scale-95 transition-all">
               <ShoppingBag className="h-6 w-6" /> تأكيد الطلب من {restaurant.name}
            </button>
         </div>
       )}
    </div>
  );
};

