import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate, Link } from "react-router-dom";

// Types
import type { User } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Icons
import { LogOut, RefreshCcw, WifiOff, Loader2, Bell, MessageCircle } from 'lucide-react';

// Services
import { auth, db } from '../services/firebase';
import { onAuthStateChanged, signOut } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { doc, getDoc, collection, query, where, onSnapshot } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Pages
import Login from './Login';
import CustomerDashboard from './CustomerDashboard';
import CourierDashboard from './CourierDashboard';
import OperatorDashboard from './OperatorDashboard';
import SuperAdminDashboard from './SuperAdminDashboard';
import NotificationsView from './NotificationsView';
import SupportView from './SupportView';

const APP_LOGO_ICON = "https://img.icons8.com/fluency-systems-filled/512/FFFFFF/bicycle.png";

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [connectionError, setConnectionError] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [showSupport, setShowSupport] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);

  useEffect(() => {
    const unsubscribeAuth = onAuthStateChanged(auth, async (fbUser) => {
      try {
        if (fbUser) {
          const userSnap = await getDoc(doc(db, "users", fbUser.uid));
          if (userSnap.exists()) {
            setUser(stripFirestore(userSnap.data()) as User);
          } else {
            setUser(null);
          }
        } else {
          setUser(null);
        }
      } catch (error) {
        console.error("Auth error:", error);
        if (!navigator.onLine) setConnectionError(true);
      } finally {
        setLoading(false);
      }
    });
    return () => unsubscribeAuth();
  }, []);

  useEffect(() => {
    if (!user) return;
    const q = query(collection(db, "notifications"), where("userId", "in", [user.id, "ALL", user.role]));
    const unsubNotifs = onSnapshot(q, (snap) => {
      const unread = snap.docs.filter(d => !d.data().read).length;
      setUnreadCount(unread);
    });
    return () => unsubNotifs();
  }, [user]);

  if (loading) return (
    <div className="min-h-screen bg-[#10b981] flex flex-col items-center justify-center p-6 text-center">
      <div className="bg-white/20 p-12 rounded-[5rem] backdrop-blur-3xl mb-12 border border-white/30 shadow-2xl animate-pulse">
         <img src={APP_LOGO_ICON} alt="Loading..." className="h-32 w-32 object-contain" />
      </div>
      <h2 className="text-white font-black text-5xl tracking-tighter mb-4">وصـــلــهــا</h2>
      <div className="flex items-center gap-3 bg-black/10 px-8 py-3 rounded-full backdrop-blur-md border border-white/10">
        <Loader2 className="h-5 w-5 text-white animate-spin" />
        <p className="text-white/80 font-bold text-[10px] uppercase tracking-widest">تحميل البيانات...</p>
      </div>
    </div>
  );

  if (connectionError) return (
    <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-10 text-center">
       <WifiOff className="h-20 w-20 text-rose-500 mb-6" />
       <h2 className="text-2xl font-black text-slate-800 mb-2">عذراً، لا يوجد اتصال</h2>
       <button onClick={() => window.location.reload()} className="bg-[#10b981] text-white px-10 py-5 rounded-[2rem] font-black shadow-xl flex items-center gap-3"><RefreshCcw className="h-5 w-5" /> إعادة المحاولة</button>
    </div>
  );

  if (!user) return <Login onLogin={(u) => setUser(stripFirestore(u))} />;

  const DashboardContent = () => {
    if (showNotifications) return <NotificationsView user={user} onBack={() => setShowNotifications(false)} />;
    if (showSupport) return <SupportView user={user} onBack={() => setShowSupport(false)} />;

    switch (user.role) {
      case 'ADMIN': return <SuperAdminDashboard user={user} />;
      case 'OPERATOR': return <OperatorDashboard user={user} />;
      case 'DRIVER': return <CourierDashboard user={user} />;
      case 'CUSTOMER': return <CustomerDashboard user={user} />;
      default: return <div className="p-20 text-center font-black">الدور الوظيفي غير مفعّل</div>;
    }
  };

  return (
    <HashRouter>
      <div className="app-container">
        <header className="bg-white/95 backdrop-blur-md border-b border-slate-100 sticky top-0 z-[60] px-5 h-24 md:h-28 flex items-center shadow-sm">
          <div className="max-w-7xl mx-auto w-full flex items-center justify-between">
            <Link to="/" onClick={() => { setShowNotifications(false); setShowSupport(false); }} className="flex items-center gap-5">
              <div className="bg-[#10b981] p-3.5 rounded-[1.8rem] shadow-xl border-4 border-emerald-50">
                <img src={APP_LOGO_ICON} alt="Logo" className="h-8 w-8 md:h-11 md:w-11" />
              </div>
              <div className="flex flex-col">
                <h1 className="font-black text-xl md:text-3xl text-slate-800 tracking-tighter leading-none mb-1">وصـــلــهــا</h1>
                <span className="text-[8px] md:text-[10px] font-black text-slate-300 uppercase tracking-widest">محافظة المنوفية</span>
              </div>
            </Link>
            <div className="flex items-center gap-2 md:gap-4">
              <button onClick={() => setShowSupport(true)} className="p-4 bg-slate-50 text-slate-400 rounded-2xl border border-slate-100 transition-all active:scale-90 hover:text-emerald-600">
                <MessageCircle className="h-6 w-6" />
              </button>
              <button onClick={() => setShowNotifications(true)} className={`p-4 bg-slate-50 text-slate-400 rounded-2xl relative border border-slate-100 transition-all active:scale-90 hover:text-emerald-600`}>
                <Bell className="h-6 w-6" />
                {unreadCount > 0 && (
                  <span className="absolute -top-1 -right-1 bg-rose-500 text-white w-6 h-6 rounded-full text-[10px] flex items-center justify-center border-2 border-white font-black animate-bounce">{unreadCount}</span>
                )}
              </button>
              <button onClick={() => signOut(auth)} className="p-4 bg-rose-50 text-rose-500 rounded-2xl border border-rose-100 transition-all active:scale-90 hover:bg-rose-100">
                <LogOut className="h-6 w-6 rotate-180" />
              </button>
            </div>
          </div>
        </header>
        <main className="main-content">
          <Routes>
            <Route path="/" element={<DashboardContent />} />
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </main>
      </div>
    </HashRouter>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import type { User, Order, Village, Restaurant, MenuItem } from '../types';
import { OrderStatus, UserStatus } from '../types';
import { District, MENOFIA_DATA } from '../config/constants';
import { stripFirestore } from '../utils';
import { DEFAULT_PRICING, ASHMOUN_VILLAGES as STATIC_VILLAGES } from '../config/constants';
import { db } from '../services/firebase';
import { 
  collection, query, doc, onSnapshot, orderBy, 
  setDoc, addDoc, deleteDoc, updateDoc, limit, getDoc, where
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { 
  User as UserIcon, DollarSign, Bike, Search, Car, 
  ShieldCheck, Megaphone, Trash2, Save, Loader2, MessageCircle, 
  Calculator, TrendingUp, ChevronRight, MapPin, 
  LayoutDashboard, Users2, Plus, X, Building2, UtensilsCrossed,
  Image as ImageIcon, PlusCircle, ChevronDown, Camera
} from 'lucide-react';
import ChatView from '../components/ChatView';

const RestaurantEditor: React.FC = () => {
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [loading, setLoading] = useState(false);

  // New Restaurant State
  const [restData, setRestData] = useState({ name: '', category: 'مشويات', address: 'أشمون', lat: 30.298, lng: 30.975, photoURL: '' });
  const [newItem, setNewItem] = useState({ name: '', price: 0, description: '', photoURL: '' });

  const restFileRef = useRef<HTMLInputElement>(null);
  const itemFileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    return onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });
  }, []);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'REST' | 'ITEM') => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64 = reader.result as string;
      if (type === 'REST') setRestData(prev => ({ ...prev, photoURL: base64 }));
      else setNewItem(prev => ({ ...prev, photoURL: base64 }));
    };
    reader.readAsDataURL(file);
  };

  const handleSaveRestaurant = async () => {
    if (!restData.name) return;
    setLoading(true);
    try {
      const rid = `rest_${Date.now()}`;
      await setDoc(doc(db, "restaurants", rid), { ...restData, id: rid, menu: [], isOpen: true });
      setIsAdding(false);
      setRestData({ name: '', category: 'مشويات', address: 'أشمون', lat: 30.298, lng: 30.975, photoURL: '' });
    } catch (e) { alert('خطأ'); } finally { setLoading(false); }
  };

  const handleAddItem = async (rid: string) => {
    if (!newItem.name || newItem.price <= 0) return;
    const rest = restaurants.find(r => r.id === rid);
    if (!rest) return;

    try {
      const updatedMenu = [...(rest.menu || []), { ...newItem, id: `item_${Date.now()}` }];
      await updateDoc(doc(db, "restaurants", rid), { menu: updatedMenu });
      setNewItem({ name: '', price: 0, description: '', photoURL: '' });
    } catch (e) { alert('خطأ'); }
  };

  const deleteItem = async (rid: string, itemId: string) => {
    const rest = restaurants.find(r => r.id === rid);
    if (!rest) return;
    const updatedMenu = rest.menu.filter(i => i.id !== itemId);
    await updateDoc(doc(db, "restaurants", rid), { menu: updatedMenu });
  };

  return (
    <div className="space-y-10 animate-in slide-in-from-top">
      <div className="bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] border border-slate-100 dark:border-slate-800 shadow-sm">
        <div className="flex justify-between items-center mb-8">
           <button onClick={() => setIsAdding(!isAdding)} className="bg-emerald-600 text-white px-8 py-4 rounded-2xl font-black text-xs flex items-center gap-3 shadow-xl active:scale-95 transition-all">
              {isAdding ? <X className="h-4 w-4" /> : <PlusCircle className="h-4 w-4" />}
              {isAdding ? 'إلغاء' : 'إضافة مطعم جديد'}
           </button>
           <h3 className="text-2xl font-black flex items-center gap-4 text-slate-800 dark:text-white">إدارة المطاعم <UtensilsCrossed className="text-emerald-500" /></h3>
        </div>

        {isAdding && (
          <div className="bg-slate-50 dark:bg-slate-950 p-8 rounded-[2.5rem] mb-10 space-y-6 border-2 border-emerald-500/20">
            <div className="flex flex-col items-center mb-6">
               <div onClick={() => restFileRef.current?.click()} className="w-32 h-32 bg-white dark:bg-slate-800 rounded-[2rem] border-4 border-dashed border-emerald-200 flex items-center justify-center cursor-pointer overflow-hidden relative group">
                  {restData.photoURL ? (
                    <img src={restData.photoURL} className="w-full h-full object-cover" />
                  ) : (
                    <div className="text-center">
                       <Camera className="h-8 w-8 mx-auto text-emerald-300" />
                       <p className="text-[8px] font-black text-emerald-400 mt-2">صورة المطعم</p>
                    </div>
                  )}
               </div>
