             <div key={rest.id} className="bg-slate-50 dark:bg-slate-950 p-8 rounded-[3rem] border border-slate-100 dark:border-slate-800 transition-all">
                <div className="flex justify-between items-start mb-6">
                   <button onClick={() => deleteDoc(doc(db, "restaurants", rest.id))} className="bg-rose-50 p-3 rounded-xl text-rose-500 transition-colors hover:bg-rose-500 hover:text-white">
                      <Trash2 className="h-5 w-5" />
                   </button>
                   <div className="text-right flex items-center gap-4 flex-row-reverse">
                      <div className="w-14 h-14 bg-white dark:bg-slate-800 rounded-2xl overflow-hidden shadow-sm border border-slate-200">
