const RestaurantEditor: React.FC = () => {
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [loading, setLoading] = useState(false);

  // New Restaurant State
  const [restData, setRestData] = useState({ name: '', category: 'مشويات', address: 'أشمون', lat: 30.298, lng: 30.975, photoURL: '' });
  const [newItem, setNewItem] = useState({ name: '', price: 0, description: '', photoURL: '' });

  const restFileRef = useRef<HTMLInputElement>(null);
  const itemFileRef = useRef<HTMLInputElement>(null);
  const [activeRestForMenu, setActiveRestForMenu] = useState<string | null>(null);

  useEffect(() => {
    return onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });
  }, []);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'REST' | 'ITEM') => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64 = reader.result as string;
      if (type === 'REST') setRestData(prev => ({ ...prev, photoURL: base64 }));
      else setNewItem(prev => ({ ...prev, photoURL: base64 }));
    };
    reader.readAsDataURL(file);
  };

  const handleSaveRestaurant = async () => {
    if (!restData.name) return;
    setLoading(true);
    try {
      const rid = `rest_${Date.now()}`;
      await setDoc(doc(db, "restaurants", rid), { ...restData, id: rid, menu: [], isOpen: true });
      setIsAdding(false);
      setRestData({ name: '', category: 'مشويات', address: 'أشمون', lat: 30.298, lng: 30.975, photoURL: '' });
    } catch (e) { alert('خطأ'); } finally { setLoading(false); }
  };

  const handleAddItem = async (rid: string) => {
    if (!newItem.name || newItem.price <= 0) return;
    const rest = restaurants.find(r => r.id === rid);
    if (!rest) return;

    try {
      const updatedMenu = [...(rest.menu || []), { ...newItem, id: `item_${Date.now()}` }];
      await updateDoc(doc(db, "restaurants", rid), { menu: updatedMenu });
      setNewItem({ name: '', price: 0, description: '', photoURL: '' });
      setActiveRestForMenu(null);
    } catch (e) { alert('خطأ'); }
  };

  const deleteItem = async (rid: string, itemId: string) => {
    const rest = restaurants.find(r => r.id === rid);
    if (!rest) return;
    const updatedMenu = rest.menu.filter(i => i.id !== itemId);
    await updateDoc(doc(db, "restaurants", rid), { menu: updatedMenu });
  };

  return (
    <div className="space-y-10 animate-in slide-in-from-top">
      <div className="bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] border border-slate-100 dark:border-slate-800 shadow-sm">
        <div className="flex justify-between items-center mb-8">
           <button onClick={() => setIsAdding(!isAdding)} className="bg-emerald-600 text-white px-8 py-4 rounded-2xl font-black text-xs flex items-center gap-3 shadow-xl active:scale-95 transition-all">
              {isAdding ? <X className="h-4 w-4" /> : <PlusCircle className="h-4 w-4" />}
              {isAdding ? 'إلغاء' : 'إضافة مطعم جديد'}
           </button>
           <h3 className="text-2xl font-black flex items-center gap-4 text-slate-800 dark:text-white">إدارة المطاعم <UtensilsCrossed className="text-emerald-500" /></h3>
        </div>

        {isAdding && (
          <div className="bg-slate-50 dark:bg-slate-950 p-8 rounded-[2.5rem] mb-10 space-y-6 border-2 border-emerald-500/20">
            <div className="flex flex-col items-center mb-6">
               <div onClick={() => restFileRef.current?.click()} className="w-32 h-32 bg-white dark:bg-slate-800 rounded-[2rem] border-4 border-dashed border-emerald-200 flex items-center justify-center cursor-pointer overflow-hidden relative group">
                  {restData.photoURL ? (
                    <img src={restData.photoURL} className="w-full h-full object-cover" />
                  ) : (
                    <div className="text-center">
                       <Camera className="h-8 w-8 mx-auto text-emerald-300" />
                       <p className="text-[8px] font-black text-emerald-400 mt-2">صورة المطعم</p>
                    </div>
                  )}
                  <div className="absolute inset-0 bg-emerald-500/20 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                     <Plus className="text-white" />
                  </div>
               </div>
               <input type="file" ref={restFileRef} className="hidden" accept="image/*" onChange={(e) => handleImageUpload(e, 'REST')} />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
               <input value={restData.name} onChange={e => setRestData({...restData, name: e.target.value})} className="bg-white dark:bg-slate-800 p-5 rounded-2xl font-black text-sm outline-none border-2 border-transparent focus:border-emerald-500" placeholder="اسم المطعم" />
               <input value={restData.category} onChange={e => setRestData({...restData, category: e.target.value})} className="bg-white dark:bg-slate-800 p-5 rounded-2xl font-black text-sm outline-none" placeholder="التصنيف (بيتزا، مشويات، إلخ)" />
               <input value={restData.address} onChange={e => setRestData({...restData, address: e.target.value})} className="bg-white dark:bg-slate-800 p-5 rounded-2xl font-black text-sm outline-none" placeholder="العنوان في أشمون" />
               <button onClick={handleSaveRestaurant} disabled={loading} className="bg-slate-950 text-white rounded-2xl font-black shadow-lg py-5">
                  {loading ? <Loader2 className="animate-spin mx-auto h-5 w-5" /> : 'حفظ المطعم في أشمون'}
               </button>
            </div>
          </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
           {restaurants.map(rest => (
             <div key={rest.id} className="bg-slate-50 dark:bg-slate-950 p-8 rounded-[3rem] border border-slate-100 dark:border-slate-800 transition-all">
                <div className="flex justify-between items-start mb-6">
                   <button onClick={() => deleteDoc(doc(db, "restaurants", rest.id))} className="bg-rose-50 p-3 rounded-xl text-rose-500 transition-colors hover:bg-rose-500 hover:text-white">
                      <Trash2 className="h-5 w-5" />
                   </button>
                   <div className="text-right flex items-center gap-4 flex-row-reverse">
                      <div className="w-14 h-14 bg-white dark:bg-slate-800 rounded-2xl overflow-hidden shadow-sm border border-slate-200">
                         {rest.photoURL ? <img src={rest.photoURL} className="w-full h-full object-cover" /> : <Building2 className="p-3 text-slate-200" />}
                      </div>
                      <div>
                        <h4 className="text-xl font-black text-slate-800 dark:text-white">{rest.name}</h4>
                        <p className="text-xs font-bold text-emerald-600">{rest.category}</p>
                      </div>
                   </div>
                </div>

                <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-inner space-y-4">
                   <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">أصناف المنيو</h5>
                   <div className="space-y-3">
                      {rest.menu?.map(item => (
                        <div key={item.id} className="flex justify-between items-center p-4 bg-slate-50 dark:bg-slate-950 rounded-2xl border border-transparent hover:border-emerald-100 transition-all">
                           <button onClick={() => deleteItem(rest.id, item.id)} className="text-rose-300 hover:text-rose-500"><X className="h-4 w-4" /></button>
                           <div className="flex items-center gap-3 text-right flex-row-reverse">
                              <div className="w-12 h-12 rounded-xl bg-white overflow-hidden shadow-sm shrink-0 border border-slate-100">
                                 {item.photoURL ? <img src={item.photoURL} className="w-full h-full object-cover" /> : <UtensilsCrossed className="p-3 text-slate-100" />}
                              </div>
                              <p className="font-bold text-sm text-slate-700 dark:text-white">{item.name} - <span className="text-emerald-600">{item.price} ج.م</span></p>
                           </div>
                        </div>
                      ))}
                   </div>

                   <div className="pt-4 border-t border-slate-100 dark:border-slate-800 space-y-4">
                      <div className="flex gap-4 items-center flex-row-reverse">
                         <div 
                           onClick={() => {
                             setActiveRestForMenu(rest.id);
                             itemFileRef.current?.click();
                           }} 
                           className="w-16 h-16 bg-slate-50 dark:bg-slate-800 rounded-2xl border-2 border-dashed border-emerald-200 flex items-center justify-center cursor-pointer overflow-hidden relative shrink-0"
                         >
                            {activeRestForMenu === rest.id && newItem.photoURL ? (
                              <img src={newItem.photoURL} className="w-full h-full object-cover" />
                            ) : (
                              <Camera className="h-5 w-5 text-emerald-200" />
                            )}
                         </div>
                         <div className="flex-1 space-y-2">
                           <input 
                             value={activeRestForMenu === rest.id ? newItem.name : ''} 
                             onChange={e => {
                               setActiveRestForMenu(rest.id);
                               setNewItem({...newItem, name: e.target.value});
                             }} 
                             placeholder="اسم الوجبة" 
                             className="w-full bg-slate-50 dark:bg-slate-800 p-4 rounded-xl text-xs font-black outline-none border border-transparent focus:border-emerald-500" 
                           />
                           <div className="flex gap-2">
                              <input 
                                type="number" 
                                value={activeRestForMenu === rest.id ? (newItem.price || '') : ''} 
                                onChange={e => {
                                  setActiveRestForMenu(rest.id);
                                  setNewItem({...newItem, price: Number(e.target.value)});
                                }} 
                                placeholder="السعر" 
                                className="flex-1 bg-slate-50 dark:bg-slate-800 p-4 rounded-xl text-xs font-black outline-none" 
                              />
                              <button 
                                onClick={() => handleAddItem(rest.id)} 
                                className="bg-emerald-600 text-white px-6 rounded-xl font-black text-xs active:scale-95"
                              >
                                إضافة
                              </button>
                           </div>
                         </div>
                      </div>
                      <input 
                        type="file" 
                        ref={itemFileRef} 
                        className="hidden" 
                        accept="image/*" 
                        onChange={(e) => handleImageUpload(e, 'ITEM')} 
                      />
                   </div>
                </div>
             </div>
           ))}
        </div>
      </div>
    </div>
  );
};

