const RestaurantEditor: React.FC = () => {
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [loading, setLoading] = useState(false);

  // New Restaurant Form
  const [restName, setRestName] = useState('');
  const [restCat, setRestCat] = useState('مشويات');
  const [restPhoto, setRestPhoto] = useState('');

  // Menu Item Form
  const [newItemName, setNewItemName] = useState('');
  const [newItemPrice, setNewItemPrice] = useState<number>(0);
  const [newItemPhoto, setNewItemPhoto] = useState('');
  const [activeRestId, setActiveRestId] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const itemFileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    return onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });
  }, []);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'REST' | 'ITEM') => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => {
      if (type === 'REST') setRestPhoto(reader.result as string);
      else setNewItemPhoto(reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  const saveRestaurant = async () => {
    if (!restName) return;
    setLoading(true);
    try {
      const id = `rest_${Date.now()}`;
      await setDoc(doc(db, "restaurants", id), {
        id, name: restName, category: restCat, photoURL: restPhoto,
        menu: [], isOpen: true, address: 'أشمون', lat: 30.298, lng: 30.975
      });
      setIsAdding(false);
      setRestName(''); setRestPhoto('');
    } catch (e) { alert('خطأ في الحفظ'); } finally { setLoading(false); }
  };

  const addMenuItem = async (restId: string) => {
    if (!newItemName || newItemPrice <= 0) return;
    const rest = restaurants.find(r => r.id === restId);
    if (!rest) return;

    const newItem: MenuItem = {
      id: `item_${Date.now()}`,
      name: newItemName,
      price: newItemPrice,
      photoURL: newItemPhoto
    };

    try {
      const updatedMenu = [...(rest.menu || []), newItem];
      await updateDoc(doc(db, "restaurants", restId), { menu: updatedMenu });
      setNewItemName(''); setNewItemPrice(0); setNewItemPhoto('');
    } catch (e) { alert('خطأ في الإضافة'); }
  };

  const deleteMenuItem = async (restId: string, itemId: string) => {
    const rest = restaurants.find(r => r.id === restId);
    if (!rest) return;
    const updatedMenu = rest.menu.filter(i => i.id !== itemId);
    await updateDoc(doc(db, "restaurants", restId), { menu: updatedMenu });
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-top">
      <div className="bg-white dark:bg-slate-900 p-8 rounded-[3.5rem] border border-slate-100 dark:border-slate-800 shadow-sm">
        <div className="flex justify-between items-center mb-8">
           <button onClick={() => setIsAdding(!isAdding)} className="bg-emerald-600 text-white px-6 py-3 rounded-2xl font-black text-xs flex items-center gap-2 shadow-lg active:scale-95 transition-all">
              {isAdding ? <X className="h-4 w-4" /> : <PlusCircle className="h-4 w-4" />}
              {isAdding ? 'إلغاء' : 'إضافة مطعم جديد'}
           </button>
           <h3 className="text-xl font-black dark:text-white flex items-center gap-3">إدارة المطاعم <UtensilsCrossed className="text-emerald-500" /></h3>
        </div>

        {isAdding && (
          <div className="bg-slate-50 dark:bg-slate-950 p-6 rounded-[2.5rem] mb-8 space-y-6 border-2 border-emerald-500/20">
            <div className="flex flex-col items-center">
               <div onClick={() => fileInputRef.current?.click()} className="w-32 h-32 bg-white dark:bg-slate-800 rounded-3xl border-4 border-dashed border-emerald-200 flex items-center justify-center cursor-pointer overflow-hidden group">
                  {restPhoto ? (
                    <img src={restPhoto} className="w-full h-full object-cover" alt="Preview" />
                  ) : (
                    <Camera className="h-8 w-8 text-emerald-300 group-hover:scale-110 transition-transform" />
                  )}
               </div>
               <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => handleImageUpload(e, 'REST')} />
               <p className="text-[10px] font-black text-slate-400 mt-2 uppercase">صورة غلاف المطعم</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
               <input value={restName} onChange={e => setRestName(e.target.value)} placeholder="اسم المطعم" className="bg-white dark:bg-slate-800 p-5 rounded-2xl font-black text-sm outline-none" />
               <input value={restCat} onChange={e => setRestCat(e.target.value)} placeholder="التصنيف (مثلاً: بيتزا، مشويات)" className="bg-white dark:bg-slate-800 p-5 rounded-2xl font-black text-sm outline-none" />
            </div>
            <button onClick={saveRestaurant} disabled={loading} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black shadow-xl active:scale-95 transition-all flex items-center justify-center gap-2">
               {loading ? <Loader2 className="h-5 w-5 animate-spin" /> : 'حفظ المطعم في أشمون'}
            </button>
          </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
           {restaurants.map(rest => (
             <div key={rest.id} className="bg-slate-50 dark:bg-slate-950 p-6 rounded-[3rem] border border-slate-100 dark:border-slate-800">
                <div className="flex justify-between items-start mb-6">
                   <button onClick={() => deleteDoc(doc(db, "restaurants", rest.id))} className="bg-rose-50 p-2 rounded-xl text-rose-500 hover:bg-rose-500 hover:text-white transition-all">
                      <Trash2 className="h-4 w-4" />
                   </button>
                   <div className="text-right flex items-center gap-4">
                      <div>
                        <h4 className="font-black text-lg dark:text-white leading-tight">{rest.name}</h4>
                        <p className="text-xs font-bold text-emerald-600">{rest.category}</p>
                      </div>
                      <div className="w-14 h-14 bg-white dark:bg-slate-800 rounded-2xl overflow-hidden shadow-sm">
                         {rest.photoURL ? <img src={rest.photoURL} className="w-full h-full object-cover" /> : <Building2 className="p-3 text-slate-300" />}
                      </div>
                   </div>
                </div>

                <div className="space-y-4">
                   <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">أصناف المنيو ({rest.menu?.length || 0})</h5>
                   <div className="grid gap-2">
                      {rest.menu?.map(item => (
                        <div key={item.id} className="bg-white dark:bg-slate-900 p-3 rounded-2xl flex justify-between items-center group">
                           <button onClick={() => deleteMenuItem(rest.id, item.id)} className="text-rose-300 hover:text-rose-500 p-1"><X className="h-4 w-4" /></button>
                           <div className="flex items-center gap-3">
                              <p className="font-bold text-xs dark:text-white">{item.name} - <span className="text-emerald-600">{item.price} ج.م</span></p>
                              <div className="w-10 h-10 rounded-lg bg-slate-50 overflow-hidden border">
                                 {item.photoURL ? <img src={item.photoURL} className="w-full h-full object-cover" /> : <UtensilsCrossed className="p-2 text-slate-200" />}
                              </div>
                           </div>
                        </div>
                      ))}
                   </div>

                   <div className="pt-4 border-t border-slate-200 dark:border-slate-800 space-y-3">
                      <div className="flex gap-2">
                         <div onClick={() => { setActiveRestId(rest.id); itemFileInputRef.current?.click(); }} className="w-12 h-12 bg-white dark:bg-slate-800 rounded-xl border-2 border-dashed flex items-center justify-center cursor-pointer overflow-hidden shrink-0">
                            {activeRestId === rest.id && newItemPhoto ? <img src={newItemPhoto} className="w-full h-full object-cover" /> : <Camera className="h-4 w-4 text-slate-300" />}
                         </div>
                         <input value={activeRestId === rest.id ? newItemName : ''} onChange={e => { setActiveRestId(rest.id); setNewItemName(e.target.value); }} placeholder="اسم الوجبة" className="flex-1 bg-white dark:bg-slate-800 rounded-xl px-4 text-xs font-black outline-none" />
                      </div>
                      <div className="flex gap-2">
                         <input type="number" value={activeRestId === rest.id ? (newItemPrice || '') : ''} onChange={e => { setActiveRestId(rest.id); setNewItemPrice(Number(e.target.value)); }} placeholder="السعر" className="flex-1 bg-white dark:bg-slate-800 rounded-xl px-4 text-xs font-black outline-none" />
                         <button onClick={() => addMenuItem(rest.id)} className="bg-emerald-600 text-white px-6 py-3 rounded-xl font-black text-[10px] active:scale-95 transition-all">إضافة للمنيو</button>
                      </div>
                      <input type="file" ref={itemFileInputRef} className="hidden" accept="image/*" onChange={(e) => handleImageUpload(e, 'ITEM')} />
                   </div>
                </div>
             </div>
           ))}
        </div>
      </div>
    </div>
  );
};

