                         {rest.photoURL ? <img src={rest.photoURL} className="w-full h-full object-cover" /> : <Building2 className="p-4 text-slate-200" />}
                      </div>
                   </div>
                </div>

                <div className="space-y-6">
                   <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-sm border border-slate-100 dark:border-slate-800">
                      <div className="flex justify-between items-center mb-4">
                         <button onClick={() => {
                           const input = document.createElement('input');
                           input.type = 'file';
                           input.accept = 'image/*';
                           input.onchange = (e: any) => {
                             const file = e.target.files?.[0];
                             if(!file) return;
                             const reader = new FileReader();
                             reader.onloadend = () => updateMenuImage(rest.id, reader.result as string);
                             reader.readAsDataURL(file);
                           };
                           input.click();
