                           <Camera className="h-3 w-3" /> تحديث صورة المنيو
                         </button>
                         <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">صورة المنيو الورقي</h5>
                      </div>
                      <div className="w-full h-32 bg-slate-50 dark:bg-slate-800 rounded-2xl overflow-hidden flex items-center justify-center border-2 border-dashed border-slate-200">
                         {rest.menuImageURL ? (
                           <img src={rest.menuImageURL} className="w-full h-full object-cover cursor-pointer hover:opacity-80" onClick={() => window.open(rest.menuImageURL, '_blank')} />
