    window.addEventListener('popstate', handlePopState);
    return () => {
      window.removeEventListener('popstate', handlePopState);
      if (window.history.state?.modal === 'full-menu') window.history.back();
    };
  }, [onClose]);

  return (
    <div className="fixed inset-0 z-[3000] bg-black/95 backdrop-blur-3xl flex flex-col animate-in fade-in duration-300">
      <div className="p-8 flex justify-between items-center text-white border-b border-white/10">
        <button onClick={() => {
          const link = document.createElement('a');
          link.href = url;
          link.download = 'menu.png';
          link.click();
        }} className="p-4 bg-emerald-600 rounded-2xl flex items-center gap-2 font-black text-xs shadow-lg active:scale-90">
