              {selectedCategory === 'FOOD' ? (
                <div className="space-y-8 animate-in zoom-in">
                   <VillageInput label="التوصيل إلى" helper="أين ستستلم طلبك؟" icon={<MapPin className="h-6 w-6" />} iconBg="bg-rose-500" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} />
