                       ))}
                    </div>
                    <button onClick={() => updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED })} className="text-rose-500 font-black text-xs uppercase tracking-widest">إلغاء الطلب</button>
                 </div>
               ) : (
                 <div className="animate-in zoom-in space-y-12 text-center">
                    <div className="bg-emerald-600 p-8 rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl">
                       <div className="text-right"><p className="text-[11px] font-black opacity-60 uppercase mb-2">تتبع الطلب</p><h3 className="text-2xl font-black">الكابتن في طريقه إليك</h3></div>
                       <Navigation2 className="h-8 w-8 animate-bounce" />
                    </div>
                    <div className="flex flex-col items-center gap-6">
                       <div className="w-32 h-32 bg-slate-100 rounded-[3rem] flex items-center justify-center border-8 border-white shadow-2xl overflow-hidden font-black text-4xl text-slate-300">{(activeOrder.driverName || 'ك')[0]}</div>
                       <h4 className="text-3xl font-black text-slate-950 tracking-tight">{activeOrder.driverName}</h4>
