                    <div className="grid grid-cols-2 gap-5">
                       <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-900 text-white py-8 rounded-[2.5rem] font-black text-lg flex items-center justify-center gap-4 shadow-2xl active:scale-95 transition-all"><PhoneCall className="h-7 w-7" /> اتصال</a>
                       <button onClick={() => setShowChat(true)} className="bg-white border-4 border-slate-100 text-slate-900 py-8 rounded-[2.5rem] font-black text-lg flex items-center justify-center gap-4 active:scale-95 transition-all relative"><MessageCircle className="h-7 w-7" /> محادثة</button>
                    </div>
                 </div>
               )}
            </div>
          )}
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-2xl border-t border-slate-100 px-10 py-6 flex justify-around items-center z-[150] shadow-2xl flex-row-reverse">
         {[
           {id: 'NEW', icon: <Plus className="h-7 w-7" />, label: 'طلب'},
           {id: 'ACTIVITY', icon: <History className="h-7 w-7" />, label: 'نشاطي'},
           {id: 'PROFILE', icon: <UserIcon className="h-7 w-7" />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-2 transition-all ${activeView === tab.id ? 'text-emerald-600 scale-125' : 'text-slate-300'}`}>
              <div className={`p-3.5 rounded-2xl ${activeView === tab.id ? 'bg-emerald-50 shadow-inner' : ''}`}>{tab.icon}</div>
              <span className="text-[10px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;

import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order, Village, Offer, OrderCategory, Restaurant, MenuItem, CartItem } from '../types';
import { OrderStatus, VehicleType } from '../types';
import { MENOFIA_DATA, DEFAULT_PRICING } from '../config/constants';

// Utils
import { stripFirestore, calculateDistance } from '../utils';

// Services
import { db } from '../services/firebase';
import { 
  collection, addDoc, query, where, onSnapshot, 
  doc, updateDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Icons
import { 
  MapPin, Bike, Check, 
  ChevronDown, ChevronRight, Star,
  User as UserIcon,
  MessageCircle, Loader2,
  Bot, History,
  Navigation2, UtensilsCrossed, ShoppingBag, 
  Trash, ArrowRight, ThumbsUp, PartyPopper,
  Download, ZoomIn, ChevronLeft, Plus, PhoneCall, Building2, Pill,
  X, Camera, FileText, ClipboardList
} from 'lucide-react';

// Components
import ProfileView from './ProfileView';
import ActivityView from './ActivityView';
import WalletView from './WalletView';
import ChatView from '../components/ChatView';
import AIAssistant from '../components/AIAssistant';

const FullMenuModal: React.FC<{ urls: string[], onClose: () => void }> = ({ urls, onClose }) => {
  const [index, setIndex] = useState(0);

  useEffect(() => {
    window.history.pushState({ modal: 'full-menu' }, '');
    const handlePopState = () => onClose();
    window.addEventListener('popstate', handlePopState);
    return () => {
      window.removeEventListener('popstate', handlePopState);
      if (window.history.state?.modal === 'full-menu') window.history.back();
    };
  }, [onClose]);

  return (
    <div className="fixed inset-0 z-[3000] bg-black/98 backdrop-blur-3xl flex flex-col animate-in fade-in duration-300">
      <div className="p-8 flex justify-between items-center text-white border-b border-white/5 bg-black/20">
        <div className="flex items-center gap-4">
           <button onClick={() => {
             const link = document.createElement('a');
             link.href = urls[index];
             link.download = `menu_page_${index + 1}.png`;
             link.click();
           }} className="p-4 bg-emerald-600 rounded-2xl flex items-center gap-2 font-black text-xs shadow-lg active:scale-90">
             <Download className="h-5 w-5" /> حفظ الصفحة
           </button>
           <span className="text-xs font-black bg-white/10 px-4 py-2 rounded-full border border-white/10 uppercase tracking-widest">
             صفحة {index + 1} من {urls.length}
           </span>
        </div>
        <button onClick={onClose} className="p-4 bg-white/5 rounded-2xl flex items-center gap-2 font-black text-xs active:scale-90 border border-white/10">
          إغلاق <X className="h-5 w-5" />
        </button>
      </div>

      <div className="flex-1 relative flex items-center justify-center overflow-hidden">
         {urls.length > 1 && (
           <>
              <button 
                onClick={() => setIndex(prev => (prev > 0 ? prev - 1 : urls.length - 1))}
                className="absolute left-6 z-10 p-5 bg-white/10 hover:bg-white/20 text-white rounded-full backdrop-blur-xl border border-white/10 active:scale-75 transition-all"
              >
                <ChevronLeft className="h-8 w-8" />
              </button>
              <button 
                onClick={() => setIndex(prev => (prev < urls.length - 1 ? prev + 1 : 0))}
                className="absolute right-6 z-10 p-5 bg-white/10 hover:bg-white/20 text-white rounded-full backdrop-blur-xl border border-white/10 active:scale-75 transition-all"
              >
                <ChevronRight className="h-8 w-8" />
              </button>
           </>
         )}
         <div className="w-full h-full p-4 flex items-center justify-center">
            <img 
              key={index}
              src={urls[index]} 
              className="max-w-full max-h-full object-contain rounded-xl shadow-2xl animate-in zoom-in slide-in-from-right duration-500" 
              alt={`Menu page ${index + 1}`} 
            />
         </div>
      </div>

      <div className="p-8 flex justify-center gap-3 bg-black/20">
         {urls.map((_, i) => (
           <div 
             key={i} 
             onClick={() => setIndex(i)}
             className={`h-1.5 rounded-full transition-all duration-300 cursor-pointer ${i === index ? 'w-12 bg-emerald-500' : 'w-4 bg-white/20'}`}
           />
         ))}
      </div>
    </div>
  );
};

const RestaurantMenu: React.FC<{ 
  restaurant: Restaurant, 
  onClose: () => void, 
  onCheckout: (cart: CartItem[]) => void 
}> = ({ restaurant, onClose, onCheckout }) => {
  const [cart, setCart] = useState<CartItem[]>([]);
  const [showFullMenu, setShowFullMenu] = useState(false);

  const allMenuImages = Array.from(new Set([
    ...(restaurant.menuImageURLs || []),
    ...(restaurant.menuImageURL ? [restaurant.menuImageURL] : [])
  ])).filter(Boolean);

  useEffect(() => {
    window.history.pushState({ modal: 'restaurant-menu' }, '');
    const handlePopState = () => onClose();
    window.addEventListener('popstate', handlePopState);
    return () => {
      window.removeEventListener('popstate', handlePopState);
      if (window.history.state?.modal === 'restaurant-menu') window.history.back();
    };
  }, [onClose]);

  const addToCart = (item: MenuItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { id: item.id, name: item.name, price: item.price, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.map(i => i.id === id ? { ...i, quantity: Math.max(0, i.quantity - 1) } : i).filter(i => i.quantity > 0));
  };

  const total = cart.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);

  return (
    <div className="fixed inset-0 bg-white z-[1100] flex flex-col animate-in slide-in-from-left duration-300">
       {showFullMenu && allMenuImages.length > 0 && <FullMenuModal urls={allMenuImages} onClose={() => setShowFullMenu(false)} />}

       <div className="bg-slate-900 p-8 pt-14 text-white flex justify-between items-center shadow-xl shrink-0">
          <button onClick={onClose} className="p-3 bg-white/10 rounded-2xl active:scale-90"><ArrowRight className="h-6 w-6" /></button>
          <div className="text-right">
             <h3 className="text-2xl font-black">{restaurant.name}</h3>
             <p className="text-xs font-bold text-emerald-400">{restaurant.category} • المنوفية</p>
          </div>
       </div>

       <div className="flex-1 overflow-y-auto p-6 space-y-6 no-scrollbar bg-slate-50">
          {allMenuImages.length > 0 && (
            <button onClick={() => setShowFullMenu(true)} className="w-full bg-emerald-600 p-6 rounded-[2.5rem] text-white flex justify-between items-center shadow-xl active:scale-95 border-none group">
               <div className="bg-white/20 p-4 rounded-2xl group-hover:rotate-12 transition-transform"><ZoomIn className="h-6 w-6" /></div>
               <div className="text-right">
                  <h4 className="font-black text-lg">تصفح المنيو الورقي</h4>
                  <p className="text-[10px] opacity-80 uppercase font-black tracking-widest mt-1">
                    {allMenuImages.length === 1 ? 'عرض المنيو كاملاً' : `عرض ${allMenuImages.length} صفحات`}
                  </p>
               </div>
            </button>
          )}

          <div className="space-y-4">
             {restaurant.menu?.map(item => (
               <div key={item.id} className="bg-white p-5 rounded-[2.5rem] shadow-sm border border-slate-100 flex justify-between items-center">
                  <div className="flex items-center gap-4">
                     <div className="flex items-center gap-2 bg-slate-50 p-2 rounded-2xl">
                        <button onClick={() => addToCart(item)} className="p-2 bg-emerald-500 text-white rounded-xl active:scale-75 transition-all"><Plus className="h-4 w-4" /></button>
                        <span className="font-black text-lg w-6 text-center">{cart.find(i => i.id === item.id)?.quantity || 0}</span>
                        <button onClick={() => removeFromCart(item.id)} className="p-2 bg-rose-50 text-rose-500 rounded-xl active:scale-75 transition-all"><Trash className="h-4 w-4" /></button>
                     </div>
                     <div className="text-left"><p className="font-black text-emerald-600">{item.price} ج.م</p></div>
                  </div>
                  <div className="text-right flex items-center gap-4 flex-row-reverse">
                     <div className="w-16 h-16 bg-slate-100 rounded-2xl overflow-hidden shrink-0 shadow-inner">
                        {item.photoURL ? <img src={item.photoURL} className="w-full h-full object-cover" /> : <UtensilsCrossed className="p-4 text-slate-200" />}
                     </div>
                     <div><p className="font-black text-slate-800 text-lg leading-tight">{item.name}</p></div>
                  </div>
               </div>
             ))}
          </div>
       </div>

       {cart.length > 0 && (
         <div className="p-8 bg-white border-t border-slate-100 pb-12 shadow-2xl shrink-0">
            <div className="flex justify-between items-center mb-6 px-2">
               <p className="text-2xl font-black text-slate-900">{total} <span className="text-xs opacity-40 uppercase">ج.م</span></p>
               <p className="text-xs font-black text-slate-400 uppercase tracking-widest">إجمالي الطلبات</p>
            </div>
            <button onClick={() => onCheckout(cart)} className="w-full bg-[#10b981] text-white py-7 rounded-[2.5rem] font-black text-lg shadow-2xl flex items-center justify-center gap-4 active:scale-95 transition-all">
               <ShoppingBag className="h-6 w-6" /> تأكيد طلب الطعام
            </button>
         </div>
       )}
    </div>
  );
};

const VillageInput: React.FC<{
  label: string; helper: string; icon: React.ReactNode; iconBg: string;
  selectedVillage: Village | null; onSelect: (v: Village) => void;
}> = ({ label, helper, icon, iconBg, selectedVillage, onSelect }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const allVillages = MENOFIA_DATA.flatMap(d => d.villages);
  const filtered = allVillages.filter(v => v.name.includes(searchTerm));

  return (
    <div className="relative space-y-1">
      <div className="flex flex-col px-2 text-right"><label className="label-strong">{label}</label><span className="helper-text">{helper}</span></div>
      <div onClick={() => setIsOpen(!isOpen)} className="bg-white border-2 border-slate-100 p-5 rounded-[2.2rem] flex items-center justify-between cursor-pointer shadow-sm active:border-emerald-500 transition-all">
        <ChevronDown className={`h-5 w-5 text-slate-400 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        <div className="flex items-center gap-4 flex-row-reverse text-right">
          <span className={`text-lg font-black ${selectedVillage ? 'text-slate-900' : 'text-slate-300'}`}>{selectedVillage?.name || "اختر القرية"}</span>
          <div className={`${iconBg} p-4 rounded-2xl text-white shadow-xl`}>{icon}</div>
        </div>
      </div>
      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-[3rem] shadow-2xl border border-slate-100 z-[200] max-h-[350px] overflow-hidden flex flex-col animate-in zoom-in">
          <div className="p-4 border-b border-slate-50"><input className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-black text-right outline-none" placeholder="ابحث عن قريتك..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} dir="rtl" /></div>
          <div className="flex-1 overflow-y-auto no-scrollbar p-4">
             {filtered.map(v => (
               <button key={v.id} onClick={() => { onSelect(v); setIsOpen(false); }} className="w-full p-4 hover:bg-emerald-50 rounded-2xl flex justify-between items-center transition-all flex-row-reverse">
                  <span className="font-bold text-slate-700">{v.name}</span>
                  {selectedVillage?.id === v.id && <Check className="h-5 w-5 text-emerald-500" />}
               </button>
             ))}
          </div>
        </div>
      )}
    </div>
  );
};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'PROFILE' | 'ACTIVITY' | 'WALLET'>('NEW');
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [viewingRestaurant, setViewingRestaurant] = useState<Restaurant | null>(null);
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);

  // Pharmacy specific states
  const [pharmacyNotes, setPharmacyNotes] = useState('');
  const [prescriptionPhoto, setPrescriptionPhoto] = useState<string | null>(null);
  const fileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });
    return onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder]);

  const handleCheckoutFood = async (cart: CartItem[]) => {
    if (!viewingRestaurant || !dropoffVillage) return alert('يرجى اختيار مكان التوصيل');
    const dist = calculateDistance(viewingRestaurant.lat, viewingRestaurant.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
    const deliveryPrice = Math.max(Math.round(DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)), DEFAULT_PRICING.minPrice);
    const foodTotal = cart.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);

    await addDoc(collection(db, "orders"), {
      customerId: user.id, customerPhone: user.phone, category: 'FOOD',
      pickup: { address: viewingRestaurant.name, lat: viewingRestaurant.lat, lng: viewingRestaurant.lng, villageName: viewingRestaurant.address },
      dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
      status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'MOTORCYCLE',
      price: deliveryPrice + foodTotal, distance: dist, operatorId: 'op_main', zoneId: 'zone_main',
      paymentMethod: 'CASH', foodItems: cart, restaurantId: viewingRestaurant.id, restaurantName: viewingRestaurant.name
    });
    setViewingRestaurant(null);
  };

  const handlePharmacyOrder = async () => {
    if (!dropoffVillage) return alert('يرجى اختيار مكان التوصيل');
    if (!pharmacyNotes.trim() && !prescriptionPhoto) return alert('يرجى كتابة الطلبات أو إرفاق صورة الروشتة');

    await addDoc(collection(db, "orders"), {
      customerId: user.id, customerPhone: user.phone, category: 'PHARMACY',
      pickup: { address: 'أقرب صيدلية', lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: 'منطقة الصيدلية' },
      dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
      status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'MOTORCYCLE',
      price: DEFAULT_PRICING.minPrice + 10, distance: 1, operatorId: 'op_main', zoneId: 'zone_main',
      paymentMethod: 'CASH', notes: pharmacyNotes, pickupNotes: prescriptionPhoto ? 'صورة الروشتة مرفقة' : ''
    });
    setPharmacyNotes('');
    setPrescriptionPhoto(null);
  };

  const handlePrescriptionUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => setPrescriptionPhoto(reader.result as string);
    reader.readAsDataURL(file);
  };

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone,
        status: OrderStatus.ACCEPTED, acceptedAt: Date.now()
      });
    } catch (e) { alert('فشل قبول العرض'); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />
      {viewingRestaurant && <RestaurantMenu restaurant={viewingRestaurant} onClose={() => setViewingRestaurant(null)} onCheckout={handleCheckoutFood} />}

      <div className="rh-ui-panel no-scrollbar z-[100] translate-y-0 bg-slate-50">
        <div className="bottom-sheet-grabber lg:hidden"></div>
        <div className="p-8 md:p-12 space-y-10 pb-32 max-w-2xl mx-auto h-full overflow-y-auto no-scrollbar text-right">
          {!activeOrder ? (
            <>
              <div className="flex items-center justify-between">
                 <div><h2 className="text-4xl font-black text-slate-950 tracking-tighter">وصـــلــهــا</h2><p className="text-slate-400 font-bold text-xs mt-1">توصيل المنوفية الذكي</p></div>
                 <button onClick={() => setAiOpen(true)} className="p-4 bg-emerald-50 text-emerald-600 rounded-3xl active:scale-90 shadow-sm border-none"><Bot className="h-8 w-8" /></button>
              </div>
              <div className="grid grid-cols-3 gap-4">
                  {[
                    { id: 'TAXI', label: 'مشوار', icon: <Bike className="h-8 w-8" /> },
                    { id: 'FOOD', label: 'أكل', icon: <UtensilsCrossed className="h-8 w-8" /> },
                    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill className="h-8 w-8" /> }
                  ].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`py-8 rounded-[2.5rem] flex flex-col items-center gap-3 border-4 transition-all ${selectedCategory === cat.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-2xl scale-105' : 'bg-white border-transparent text-slate-400 opacity-60'}`}>
                       {cat.icon} <span className="text-[11px] font-black uppercase tracking-widest">{cat.label}</span>
                    </button>
                  ))}
              </div>

              {selectedCategory === 'FOOD' ? (
                <div className="space-y-8 animate-in zoom-in">
                   <VillageInput label="التوصيل إلى" helper="أين ستستلم طلبك؟" icon={<MapPin className="h-6 w-6" />} iconBg="bg-rose-500" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} />
                   <div className="grid grid-cols-1 gap-6">
                      {restaurants.map(rest => (
                        <div key={rest.id} onClick={() => setViewingRestaurant(rest)} className="bg-white p-7 rounded-[3.5rem] border border-slate-100 shadow-sm flex flex-row-reverse justify-between items-center hover:border-emerald-500 cursor-pointer group active:scale-[0.98] transition-all">
                           <div className="flex items-center gap-5 flex-row-reverse text-right">
                              <div className="w-16 h-16 bg-slate-900 rounded-[1.8rem] flex items-center justify-center overflow-hidden shadow-lg">
                                 {rest.photoURL ? <img src={rest.photoURL} className="w-full h-full object-cover" /> : <UtensilsCrossed className="h-8 w-8 text-emerald-400" />}
                              </div>
                              <div><h4 className="text-xl font-black text-slate-800 leading-tight">{rest.name}</h4><p className="text-xs font-bold text-slate-400 uppercase tracking-tighter">{rest.category}</p></div>
                           </div>
                           <ChevronRight className="h-6 w-6 text-slate-300 rotate-180 group-hover:text-emerald-500 transition-colors" />
                        </div>
                      ))}
                   </div>
                </div>
              ) : selectedCategory === 'PHARMACY' ? (
                <div className="space-y-8 animate-in zoom-in">
                   <div className="bg-sky-50 border-2 border-sky-100 p-8 rounded-[3rem] text-center space-y-3">
                      <Pill className="h-12 w-12 text-sky-600 mx-auto" />
                      <h3 className="text-xl font-black text-sky-900">طلب أدوية صيدلية</h3>
                      <p className="text-xs font-bold text-sky-600">اكتب طلباتك أو ارفع صورة الروشتة وهنوصلك فوراً</p>
                   </div>

                   <VillageInput label="مكان التوصيل" helper="أين ستستلم الدواء؟" icon={<MapPin className="h-6 w-6" />} iconBg="bg-sky-600" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} />

                   <div className="space-y-4">
                      <div className="flex items-center justify-between px-2">
                        <label className="label-strong">طلبات الصيدلية</label>
                        <ClipboardList className="h-4 w-4 text-slate-300" />
                      </div>
                      <textarea 
                        value={pharmacyNotes}
                        onChange={e => setPharmacyNotes(e.target.value)}
                        placeholder="اكتب أسماء الأدوية أو المستلزمات..."
                        dir="rtl"
                        className="w-full bg-white border-2 border-slate-100 rounded-[2rem] p-6 text-sm font-bold outline-none focus:border-sky-500 min-h-[120px] transition-all shadow-sm"
                      />
                   </div>

                   <div className="space-y-4">
                      <div className="flex items-center justify-between px-2">
                         <label className="label-strong">صورة الروشتة (اختياري)</label>
                         <Camera className="h-4 w-4 text-slate-300" />
                      </div>
                      <div 
                        onClick={() => fileRef.current?.click()}
                        className="w-full h-32 bg-white border-2 border-dashed border-slate-200 rounded-[2rem] flex flex-col items-center justify-center cursor-pointer hover:border-sky-400 transition-all overflow-hidden relative"
                      >
                         {prescriptionPhoto ? (
                           <img src={prescriptionPhoto} className="w-full h-full object-cover" />
                         ) : (
                           <>
                             <Plus className="h-8 w-8 text-slate-300 mb-1" />
                             <span className="text-[10px] font-black text-slate-400 uppercase">ارفق الصورة</span>
                           </>
                         )}
                         <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={handlePrescriptionUpload} />
                      </div>
                   </div>

                   <button 
                     onClick={handlePharmacyOrder}
                     className="w-full bg-sky-600 text-white py-8 rounded-[3rem] font-black text-xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4"
                   >
                     إرسال طلب الصيدلية <FileText className="h-6 w-6" />
                   </button>
                </div>
              ) : (
                <div className="space-y-8 animate-in slide-in-from-right">
                   <VillageInput label="نقطة الانطلاق" helper="موقع استلامك" icon={<MapPin className="h-6 w-6" />} iconBg="bg-emerald-500" selectedVillage={pickupVillage} onSelect={setPickupVillage} />
                   <VillageInput label="وجهة الوصول" helper="الوجهة النهائية" icon={<Check className="h-6 w-6" />} iconBg="bg-rose-500" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} />
                   <button onClick={async () => {
                     if(!pickupVillage || !dropoffVillage) return;
                     const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
                     const price = Math.max(Math.round(DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)), DEFAULT_PRICING.minPrice);
                     await addDoc(collection(db, "orders"), {
                        customerId: user.id, customerPhone: user.phone, category: 'TAXI',
                        pickup: { address: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng, villageName: pickupVillage.name },
                        dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
                        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'TOKTOK',
                        price, distance: dist, operatorId: 'op_main', zoneId: 'zone_main', paymentMethod: 'CASH'
                     });
                   }} disabled={!pickupVillage || !dropoffVillage} className="w-full bg-slate-950 text-white py-8 rounded-[3rem] font-black text-2xl shadow-2xl active:scale-95 transition-all">اطلب الآن</button>
                </div>
              )}
            </>
          ) : (
            <div className="space-y-12">
               {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                 <div className="animate-in zoom-in space-y-12 text-center">
                    <Navigation2 className="h-24 w-24 text-emerald-600 animate-pulse mx-auto" />
                    <h2 className="text-3xl font-black text-slate-950 tracking-tighter">جاري جلب كباتن متاحين...</h2>
                    <div className="space-y-6">
                       {incomingOffers.map(offer => (
                         <div key={offer.id} className="bg-white p-8 rounded-[3rem] border-4 border-slate-50 shadow-xl flex justify-between items-center animate-in slide-in-from-bottom">
                            <div className="text-center">
                               <p className="text-3xl font-black text-emerald-700">{offer.price} ج.م</p>
                               <button onClick={() => handleAcceptOffer(offer)} className="bg-emerald-600 text-white px-8 py-2 rounded-2xl font-black text-xs shadow-lg active:scale-90 transition-all">قبول</button>
                            </div>
                            <div className="flex items-center gap-5 flex-row-reverse text-right">
                               <div className="w-14 h-14 bg-slate-900 text-emerald-400 rounded-2xl flex items-center justify-center font-black">{(offer.driverName || 'ك')[0]}</div>
                               <div><p className="font-black text-slate-900 text-lg">{offer.driverName}</p><div className="flex items-center gap-2 text-amber-500 font-black text-xs">{offer.driverRating} <Star className="h-3 w-3 fill-amber-400" /></div></div>
                            </div>
                         </div>
                       ))}
                    </div>
                    <button onClick={() => updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED })} className="text-rose-500 font-black text-xs uppercase tracking-widest">إلغاء الطلب</button>
                 </div>
               ) : (
                 <div className="animate-in zoom-in space-y-12 text-center">
                    <div className="bg-emerald-600 p-8 rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl">
                       <div className="text-right"><p className="text-[11px] font-black opacity-60 uppercase mb-2">تتبع الطلب</p><h3 className="text-2xl font-black">الكابتن في طريقه إليك</h3></div>
                       <Navigation2 className="h-8 w-8 animate-bounce" />
                    </div>
                    <div className="flex flex-col items-center gap-6">
                       <div className="w-32 h-32 bg-slate-100 rounded-[3rem] flex items-center justify-center border-8 border-white shadow-2xl overflow-hidden font-black text-4xl text-slate-300">{(activeOrder.driverName || 'ك')[0]}</div>
                       <h4 className="text-3xl font-black text-slate-950 tracking-tight">{activeOrder.driverName}</h4>
                    </div>
                    <div className="grid grid-cols-2 gap-5">
                       <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-900 text-white py-8 rounded-[2.5rem] font-black text-lg flex items-center justify-center gap-4 shadow-2xl active:scale-95 transition-all"><PhoneCall className="h-7 w-7" /> اتصال</a>
                       <button onClick={() => setShowChat(true)} className="bg-white border-4 border-slate-100 text-slate-900 py-8 rounded-[2.5rem] font-black text-lg flex items-center justify-center gap-4 active:scale-95 transition-all relative"><MessageCircle className="h-7 w-7" /> محادثة</button>
                    </div>
                 </div>
               )}
            </div>
          )}
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-2xl border-t border-slate-100 px-10 py-6 flex justify-around items-center z-[150] shadow-2xl flex-row-reverse">
         {[
           {id: 'NEW', icon: <Plus className="h-7 w-7" />, label: 'طلب'},
           {id: 'ACTIVITY', icon: <History className="h-7 w-7" />, label: 'نشاطي'},
           {id: 'PROFILE', icon: <UserIcon className="h-7 w-7" />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-2 transition-all ${activeView === tab.id ? 'text-emerald-600 scale-125' : 'text-slate-300'}`}>
              <div className={`p-3.5 rounded-2xl ${activeView === tab.id ? 'bg-emerald-50 shadow-inner' : ''}`}>{tab.icon}</div>
              <span className="text-[10px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;

import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order, Village, Restaurant, MenuItem } from '../types';
import { OrderStatus, UserStatus, UserRole } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Constants
import { DEFAULT_PRICING, ASHMOUN_VILLAGES as STATIC_VILLAGES, MENOFIA_DATA } from '../config/constants';

// Services
import { db } from '../services/firebase';
import { 
  collection, query, doc, onSnapshot, orderBy, 
  setDoc, addDoc, deleteDoc, updateDoc, limit, getDoc, where
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Icons
import { 
  User as UserIcon, DollarSign, Bike, Search, Car, 
  ShieldCheck, Megaphone, Trash2, Save, Loader2, MessageCircle, 
  Calculator, TrendingUp, ChevronRight, MapPin, 
  LayoutDashboard, Send, Users2, Plus, X, Building2, UtensilsCrossed,
  Image as ImageIcon, PlusCircle, Camera, FileText, ChevronLeft, Filter,
  Ban, CheckCircle, Smartphone, AlertTriangle
} from 'lucide-react';

const RestaurantEditor: React.FC = () => {
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [loading, setLoading] = useState(false);

  const [restData, setRestData] = useState({ 
    name: '', 
    category: 'مشويات', 
    photoURL: '', 
    menuImageURLs: [] as string[]
  });

  const [newItem, setNewItem] = useState({ name: '', price: 0, photoURL: '' });
  const [activeRestId, setActiveRestId] = useState<string | null>(null);

  const fileRef = useRef<HTMLInputElement>(null);
  const menuImgRef = useRef<HTMLInputElement>(null);
  const itemFileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    return onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });
  }, []);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, target: 'PHOTO' | 'MENU' | 'ITEM') => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64 = reader.result as string;
      if (target === 'PHOTO') setRestData(prev => ({ ...prev, photoURL: base64 }));
      if (target === 'MENU') setRestData(prev => ({ ...prev, menuImageURLs: [...prev.menuImageURLs, base64] }));
      if (target === 'ITEM') setNewItem(prev => ({ ...prev, photoURL: base64 }));
    };
    reader.readAsDataURL(file);
  };

  const removeMenuImageFromNew = (idx: number) => {
    setRestData(prev => ({
      ...prev,
      menuImageURLs: prev.menuImageURLs.filter((_, i) => i !== idx)
    }));
  };

  const saveRestaurant = async () => {
    if (!restData.name) return;
    setLoading(true);
    try {
      const id = `rest_${Date.now()}`;
      await setDoc(doc(db, "restaurants", id), {
        ...restData, id, menu: [], isOpen: true, address: 'المنوفية', lat: 30.5, lng: 30.9
      });
      setIsAdding(false);
      setRestData({ name: '', category: 'مشويات', photoURL: '', menuImageURLs: [] });
    } catch (e) { alert('خطأ في الحفظ'); } finally { setLoading(false); }
  };

  const addMenuItem = async (rid: string) => {
    if (!newItem.name || newItem.price <= 0) return;
    const rest = restaurants.find(r => r.id === rid);
    if (!rest) return;
    const menu = [...(rest.menu || []), { ...newItem, id: `item_${Date.now()}` }];
    await updateDoc(doc(db, "restaurants", rid), { menu });
    setNewItem({ name: '', price: 0, photoURL: '' });
  };

  const removeMenuImageFromExisting = async (rid: string, imgUrl: string) => {
    const rest = restaurants.find(r => r.id === rid);
    if (!rest) return;
    const menuImageURLs = (rest.menuImageURLs || []).filter(u => u !== imgUrl);
    await updateDoc(doc(db, "restaurants", rid), { menuImageURLs });
  };

  const addMenuImageToExisting = async (rid: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      const rest = restaurants.find(r => r.id === rid);
      if (!rest) return;
      const menuImageURLs = [...(rest.menuImageURLs || []), base64];
      await updateDoc(doc(db, "restaurants", rid), { menuImageURLs });
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-top duration-500">
      <div className="flex justify-between items-center px-4">
         <h3 className="text-2xl font-black text-slate-800 flex items-center gap-3">إدارة المطاعم <UtensilsCrossed className="text-emerald-500" /></h3>
         <button onClick={() => setIsAdding(!isAdding)} className={`px-8 py-4 rounded-[1.5rem] font-black text-xs flex items-center gap-2 shadow-xl transition-all active:scale-95 ${isAdding ? 'bg-rose-50 text-rose-500' : 'bg-emerald-600 text-white'}`}>
            {isAdding ? <X className="h-4 w-4" /> : <PlusCircle className="h-4 w-4" />}
            {isAdding ? 'إلغاء الإضافة' : 'إضافة مطعم جديد'}
         </button>
      </div>

      {isAdding && (
        <div className="bg-white p-10 rounded-[3.5rem] shadow-2xl border-4 border-emerald-50 animate-in zoom-in duration-300">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
             <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">صورة الواجهة الرئيسية</label>
                <div onClick={() => fileRef.current?.click()} className="w-full h-56 bg-slate-50 rounded-[2.5rem] border-4 border-dashed border-emerald-100 flex flex-col items-center justify-center cursor-pointer overflow-hidden relative group transition-all hover:border-emerald-300">
                   {restData.photoURL ? <img src={restData.photoURL} className="w-full h-full object-cover" /> : (
                     <>
                       <Camera className="h-12 w-12 text-emerald-200 mb-2" />
                       <span className="text-[10px] font-black text-emerald-300 uppercase">ارفع صورة الغلاف</span>
                     </>
                   )}
                </div>
                <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'PHOTO')} />
             </div>

             <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">صور المنيو الورقي ({restData.menuImageURLs.length})</label>
                <div className="grid grid-cols-3 gap-3">
                   {restData.menuImageURLs.map((url, i) => (
                     <div key={i} className="relative h-24 bg-white rounded-2xl overflow-hidden group border-2 border-slate-100 shadow-sm">
                        <img src={url} className="w-full h-full object-cover" />
                        <button onClick={() => removeMenuImageFromNew(i)} className="absolute inset-0 bg-rose-500/80 opacity-0 group-hover:opacity-100 flex items-center justify-center text-white transition-opacity"><X className="h-5 w-5" /></button>
                     </div>
                   ))}
                   <button onClick={() => menuImgRef.current?.click()} className="h-24 bg-slate-50 rounded-2xl border-2 border-dashed border-emerald-200 flex flex-col items-center justify-center text-emerald-400 hover:bg-emerald-50 transition-colors">
                      <Plus className="h-6 w-6" />
                   </button>
                </div>
                <input type="file" ref={menuImgRef} className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'MENU')} />
             </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-8">
             <input value={restData.name} onChange={e => setRestData({...restData, name: e.target.value})} placeholder="اسم المطعم" className="bg-slate-50 p-6 rounded-2xl font-black text-sm outline-none focus:ring-4 focus:ring-emerald-500/5 transition-all text-right" dir="rtl" />
             <input value={restData.category} onChange={e => setRestData({...restData, category: e.target.value})} placeholder="التصنيف (مثلاً: بيتزا وكريب)" className="bg-slate-50 p-6 rounded-2xl font-black text-sm outline-none focus:ring-4 focus:ring-emerald-500/5 transition-all text-right" dir="rtl" />
          </div>
          <button onClick={saveRestaurant} disabled={loading} className="w-full bg-slate-950 text-white py-8 rounded-[2rem] font-black text-xl shadow-2xl active:scale-95 transition-all mt-8">
            {loading ? <Loader2 className="h-8 w-8 animate-spin mx-auto" /> : 'حفظ المطعم في قاعدة البيانات'}
          </button>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
         {restaurants.map(rest => (
           <div key={rest.id} className="bg-white p-8 rounded-[3.5rem] border border-slate-100 shadow-sm flex flex-col gap-8 transition-all hover:shadow-xl">
              <div className="flex justify-between items-start">
                 <button onClick={async () => { if(confirm(`هل أنت متأكد من حذف مطعم ${rest.name} نهائياً؟`)) await deleteDoc(doc(db, "restaurants", rest.id)); }} className="bg-rose-50 p-4 rounded-2xl text-rose-500 hover:bg-rose-500 hover:text-white transition-all active:scale-90 shadow-sm"><Trash2 className="h-6 w-6" /></button>
                 <div className="text-right flex items-center gap-6">
                    <div className="space-y-1">
                      <h4 className="font-black text-2xl text-slate-900">{rest.name}</h4>
                      <p className="text-xs font-bold text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full inline-block">{rest.category}</p>
                    </div>
                    <div className="w-20 h-20 bg-slate-100 rounded-[1.8rem] overflow-hidden shadow-lg border-4 border-white">
                       {rest.photoURL ? <img src={rest.photoURL} className="w-full h-full object-cover" /> : <Building2 className="p-5 text-slate-300" />}
                    </div>
                 </div>
              </div>

              <div className="space-y-4">
                 <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest text-right px-2">صور المنيو ({rest.menuImageURLs?.length || 0})</h5>
                 <div className="grid grid-cols-4 gap-3">
                    {(rest.menuImageURLs || []).map((url, i) => (
                      <div key={i} className="relative h-16 bg-slate-50 rounded-xl overflow-hidden group border border-slate-100">
                         <img src={url} className="w-full h-full object-cover" />
                         <button onClick={() => removeMenuImageFromExisting(rest.id, url)} className="absolute inset-0 bg-rose-500/80 opacity-0 group-hover:opacity-100 flex items-center justify-center text-white transition-opacity"><X className="h-4 w-4" /></button>
                      </div>
                    ))}
                    <div className="relative h-16 bg-emerald-50 rounded-xl border-2 border-dashed border-emerald-200 flex items-center justify-center text-emerald-600 cursor-pointer overflow-hidden active:scale-95 transition-all">
                      <Plus className="h-5 w-5" />
                      <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*" onChange={(e) => addMenuImageToExisting(rest.id, e)} />
                    </div>
                 </div>
              </div>

              <div className="space-y-4 pt-4 border-t border-slate-50">
                 <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest text-right px-2">الوجبات المدرجة ({rest.menu?.length || 0})</h5>
                 <div className="grid gap-3 max-h-[300px] overflow-y-auto no-scrollbar">
                    {rest.menu?.map(item => (
                      <div key={item.id} className="bg-slate-50 p-4 rounded-2xl flex justify-between items-center group transition-all hover:bg-white hover:shadow-md border border-transparent hover:border-slate-100">
                         <button onClick={async () => {
                           const menu = rest.menu.filter(i => i.id !== item.id);
                           await updateDoc(doc(db, "restaurants", rest.id), { menu });
                         }} className="text-rose-200 hover:text-rose-500 transition-all p-2"><X className="h-4 w-4" /></button>
                         <div className="flex items-center gap-4 text-right">
                            <div>
                              <p className="font-black text-sm text-slate-800 leading-none mb-1">{item.name}</p>
                              <p className="text-xs font-bold text-emerald-600">{item.price} ج.م</p>
                            </div>
                            <div className="w-12 h-12 rounded-xl bg-white overflow-hidden shadow-inner border border-slate-100">
                               {item.photoURL ? <img src={item.photoURL} className="w-full h-full object-cover" /> : <UtensilsCrossed className="p-3 text-slate-200" />}
                            </div>
                         </div>
                      </div>
                    ))}
                 </div>

                 <div className="bg-slate-900 p-8 rounded-[2.5rem] shadow-2xl space-y-5">
                    <div className="flex gap-4 flex-row-reverse items-center">
                       <div onClick={() => { setActiveRestId(rest.id); itemFileRef.current?.click(); }} className="w-16 h-16 bg-white/10 rounded-2xl border-2 border-dashed border-emerald-500/30 flex items-center justify-center cursor-pointer shrink-0 overflow-hidden group">
                          {activeRestId === rest.id && newItem.photoURL ? <img src={newItem.photoURL} className="w-full h-full object-cover" /> : <Camera className="h-6 w-6 text-emerald-500 group-hover:scale-110 transition-transform" />}
                       </div>
                       <div className="flex-1 space-y-3">
                          <input value={activeRestId === rest.id ? newItem.name : ''} onChange={e => { setActiveRestId(rest.id); setNewItem({...newItem, name: e.target.value}); }} placeholder="اسم الوجبة" className="w-full bg-white/5 border border-white/10 rounded-xl p-4 text-xs font-black text-white outline-none focus:border-emerald-500 transition-all text-right" dir="rtl" />
                          <div className="flex gap-2">
                             <input type="number" value={activeRestId === rest.id ? (newItem.price || '') : ''} onChange={e => { setActiveRestId(rest.id); setNewItem({...newItem, price: Number(e.target.value)}); }} placeholder="السعر" className="flex-1 bg-white/5 border border-white/10 rounded-xl p-4 text-xs font-black text-white outline-none focus:border-emerald-500 transition-all text-right" dir="rtl" />
                             <button onClick={() => addMenuItem(rest.id)} className="bg-emerald-600 text-white px-8 py-3 rounded-xl font-black text-[10px] active:scale-95 shadow-lg shadow-emerald-900/50">إضافة</button>
                          </div>
                       </div>
                    </div>
                    <input type="file" ref={itemFileRef} className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'ITEM')} />
                 </div>
              </div>
           </div>
         ))}
      </div>
    </div>
  );
};

const SuperAdminDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'STATS' | 'USERS' | 'RESTAURANTS' | 'VILLAGES'>('STATS');
  const [users, setUsers] = useState<User[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [roleFilter, setRoleFilter] = useState<UserRole | 'ALL'>('ALL');

  useEffect(() => {
    const unsubUsers = onSnapshot(collection(db, "users"), (snap) => setUsers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as User[]));
    const unsubOrders = onSnapshot(query(collection(db, "orders"), orderBy("createdAt", "desc"), limit(200)), (snap) => setOrders(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[]));
    return () => { unsubUsers(); unsubOrders(); };
  }, []);

  const handleUpdateStatus = async (uid: string, status: UserStatus) => {
    if(!confirm('تغيير حالة الحساب؟')) return;
    try {
      await updateDoc(doc(db, "users", uid), { status });
    } catch (e) { alert('فشل'); }
  };

  const filteredUsers = users.filter(u => {
    const matchesSearch = (u.name?.toLowerCase().includes(searchTerm.toLowerCase()) || u.phone?.includes(searchTerm));
    const matchesRole = roleFilter === 'ALL' || u.role === roleFilter;
    return matchesSearch && matchesRole;
  });

  const sysStats = {
    totalBalance: users.reduce((acc, curr) => acc + (curr.wallet?.balance || 0), 0),
    totalOrders: orders.length,
    activeDrivers: users.filter(u => u.role === 'DRIVER' && u.status === 'APPROVED').length,
    pendingDrivers: users.filter(u => u.role === 'DRIVER' && u.status === 'PENDING_APPROVAL').length,
    totalCustomers: users.filter(u => u.role === 'CUSTOMER').length
  };

  return (
    <div className="max-w-7xl mx-auto space-y-10 pb-40 p-6 animate-in fade-in transition-all">
      {/* Navigation Header */}
      <div className="bg-white p-4 rounded-[3rem] shadow-sm border border-slate-100 flex gap-2 overflow-x-auto no-scrollbar sticky top-4 z-[500] backdrop-blur-2xl bg-white/90">
        {[
          { id: 'STATS', label: 'نظرة عامة', icon: <LayoutDashboard className="h-4 w-4" /> },
          { id: 'USERS', label: 'إدارة الأعضاء', icon: <Users2 className="h-4 w-4" /> },
          { id: 'RESTAURANTS', label: 'قائمة المطاعم', icon: <UtensilsCrossed className="h-4 w-4" /> },
          { id: 'VILLAGES', label: 'مناطق التغطية', icon: <MapPin className="h-4 w-4" /> },
        ].map(tab => (
          <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex items-center gap-3 px-10 py-5 rounded-[1.8rem] text-[11px] font-black transition-all whitespace-nowrap active:scale-95 ${activeTab === tab.id ? 'bg-slate-950 text-white shadow-2xl' : 'text-slate-400 hover:bg-slate-50'}`}>
            {tab.icon} {tab.label}
          </button>
        ))}
      </div>

      {activeTab === 'STATS' && (
        <div className="space-y-10 animate-in zoom-in duration-500">
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              <div className="bg-emerald-600 p-10 rounded-[3.5rem] text-white shadow-2xl shadow-emerald-500/20 relative overflow-hidden group">
                 <TrendingUp className="absolute -bottom-4 -left-4 h-32 w-32 opacity-10 group-hover:scale-110 transition-transform" />
                 <p className="text-[10px] font-black opacity-60 uppercase mb-3 tracking-widest">إجمالي المحافظ</p>
                 <h3 className="text-5xl font-black">{sysStats.totalBalance.toLocaleString()} <span className="text-sm opacity-40 font-bold">ج.م</span></h3>
