              <div className="bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-sm relative overflow-hidden group">
                 <Bike className="absolute -bottom-4 -left-4 h-24 w-24 text-emerald-500/5" />
                 <p className="text-[10px] font-black text-slate-400 uppercase mb-3 tracking-widest">كباتن المنوفية</p>
