  flex-direction: column;
}

.rh-map-view {
  position: absolute;
  inset: 0;
  z-index: 0;
  background: #e5ebee;
}

/* --- Floating UI Panel (Responsive Logic) --- */
.rh-ui-panel {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: white;
  border-top-left-radius: 3rem;
  border-top-right-radius: 3rem;
  box-shadow: 0 -20px 80px -15px rgba(0, 0, 0, 0.15);
  max-height: 85vh;
  overflow-y: auto;
  padding-bottom: calc(6rem + env(safe-area-inset-bottom));
  transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1);
