.bottom-sheet-grabber {
  width: 40px;
  height: 5px;
  background: #e2e8f0;
  border-radius: 99px;
  margin: 15px auto 5px;
  flex-shrink: 0;
}

/* Tablet / Desktop Overrides */
@media (min-width: 768px) {
  .rh-ui-panel {
    bottom: 2rem;
    left: 2rem;
    right: auto;
    width: 420px;
    border-radius: 3rem;
    max-height: calc(100% - 4rem);
    box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.25);
