  }
}

@media (min-width: 1024px) {
  .rh-layout { 
    flex-direction: row-reverse; 
  }
  .rh-map-view { 
    position: relative; 
    flex: 1; 
    margin: 1.5rem; 
    border-radius: 3rem; 
    overflow: hidden; 
  }
  .rh-ui-panel {
    position: relative;
    width: 400px;
    height: calc(100% - 3rem);
    max-height: none;
    margin: 1.5rem 0 1.5rem 1.5rem;
    border-radius: 3rem;
    box-shadow: -15px 0 50px rgba(0,0,0,0.03);
