                               <div><p className="font-black text-slate-900 text-base md:text-lg">{offer.driverName}</p><div className="flex items-center gap-1.5 md:gap-2 text-amber-500 font-black text-[10px] md:text-xs">{offer.driverRating} <Star className="h-3 w-3 fill-amber-400" /></div></div>
