                 <TrendingUp className="absolute -bottom-4 -left-4 h-32 w-32 opacity-10 group-hover:scale-110 transition-transform" />
                 <p className="text-[10px] font-black opacity-60 uppercase mb-3 tracking-widest">إجمالي المحافظ</p>
