                   <button onClick={() => menuImgRef.current?.click()} className="h-24 bg-slate-50 rounded-2xl border-2 border-dashed border-emerald-200 flex flex-col items-center justify-center text-emerald-400 hover:bg-emerald-50 transition-colors">
