const RestaurantEditor: React.FC = () => {
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [loading, setLoading] = useState(false);

  const [restData, setRestData] = useState({ 
    name: '', 
    category: 'مشويات', 
    photoURL: '', 
    menuImageURLs: [] as string[]
  });

  const [newItem, setNewItem] = useState({ name: '', price: 0, photoURL: '' });
  const [activeRestId, setActiveRestId] = useState<string | null>(null);

  const fileRef = useRef<HTMLInputElement>(null);
  const menuImgRef = useRef<HTMLInputElement>(null);
  const itemFileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    return onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });
  }, []);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, target: 'PHOTO' | 'MENU' | 'ITEM') => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64 = reader.result as string;
      if (target === 'PHOTO') setRestData(prev => ({ ...prev, photoURL: base64 }));
      if (target === 'MENU') setRestData(prev => ({ ...prev, menuImageURLs: [...prev.menuImageURLs, base64] }));
      if (target === 'ITEM') setNewItem(prev => ({ ...prev, photoURL: base64 }));
    };
    reader.readAsDataURL(file);
  };

  const removeMenuImageFromNew = (idx: number) => {
    setRestData(prev => ({
      ...prev,
      menuImageURLs: prev.menuImageURLs.filter((_, i) => i !== idx)
    }));
  };

  const saveRestaurant = async () => {
    if (!restData.name) return;
    setLoading(true);
    try {
      const id = `rest_${Date.now()}`;
      await setDoc(doc(db, "restaurants", id), {
        ...restData, id, menu: [], isOpen: true, address: 'المنوفية', lat: 30.55, lng: 31.01
      });
      setIsAdding(false);
      setRestData({ name: '', category: 'مشويات', photoURL: '', menuImageURLs: [] });
    } catch (e) { alert('خطأ في الحفظ'); } finally { setLoading(false); }
  };

  const addMenuItem = async (rid: string) => {
    if (!newItem.name || newItem.price <= 0) return;
    const rest = restaurants.find(r => r.id === rid);
    if (!rest) return;
    const menu = [...(rest.menu || []), { ...newItem, id: `item_${Date.now()}` }];
    await updateDoc(doc(db, "restaurants", rid), { menu });
    setNewItem({ name: '', price: 0, photoURL: '' });
  };

  const removeMenuImageFromExisting = async (rid: string, imgUrl: string) => {
    const rest = restaurants.find(r => r.id === rid);
    if (!rest) return;
    const menuImageURLs = (rest.menuImageURLs || []).filter(u => u !== imgUrl);
    await updateDoc(doc(db, "restaurants", rid), { menuImageURLs });
  };

  const addMenuImageToExisting = async (rid: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      const rest = restaurants.find(r => r.id === rid);
      if (!rest) return;
      const menuImageURLs = [...(rest.menuImageURLs || []), base64];
      await updateDoc(doc(db, "restaurants", rid), { menuImageURLs });
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-top duration-500">
      <div className="flex justify-between items-center px-4">
         <h3 className="text-2xl font-black text-slate-800 flex items-center gap-3">إدارة المطاعم <UtensilsCrossed className="text-emerald-500" /></h3>
         <button onClick={() => setIsAdding(!isAdding)} className={`px-8 py-4 rounded-[1.5rem] font-black text-xs flex items-center gap-2 shadow-xl transition-all active:scale-95 ${isAdding ? 'bg-rose-50 text-rose-500' : 'bg-emerald-600 text-white'}`}>
            {isAdding ? <X className="h-4 w-4" /> : <PlusCircle className="h-4 w-4" />}
            {isAdding ? 'إلغاء الإضافة' : 'إضافة مطعم جديد'}
         </button>
      </div>

      {isAdding && (
        <div className="bg-white p-10 rounded-[3.5rem] shadow-2xl border-4 border-emerald-50 animate-in zoom-in duration-300">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
             <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block text-right">صورة الواجهة الرئيسية</label>
                <div onClick={() => fileRef.current?.click()} className="w-full h-56 bg-slate-50 rounded-[2.5rem] border-4 border-dashed border-emerald-100 flex flex-col items-center justify-center cursor-pointer overflow-hidden relative group transition-all hover:border-emerald-300">
                   {restData.photoURL ? <img src={restData.photoURL} className="w-full h-full object-cover" /> : (
                     <>
                       <Camera className="h-12 w-12 text-emerald-200 mb-2" />
                       <span className="text-[10px] font-black text-emerald-300 uppercase">ارفع صورة الغلاف</span>
                     </>
                   )}
                </div>
                <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'PHOTO')} />
             </div>

             <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block text-right">صور المنيو الورقي ({restData.menuImageURLs.length})</label>
                <div className="grid grid-cols-3 gap-3">
                   {restData.menuImageURLs.map((url, i) => (
                     <div key={i} className="relative h-24 bg-white rounded-2xl overflow-hidden group border-2 border-slate-100 shadow-sm">
                        <img src={url} className="w-full h-full object-cover" />
