};

const MassActionsPanel: React.FC<{ users: User[] }> = ({ users }) => {
  const [loading, setLoading] = useState(false);
  const [amount, setAmount] = useState<string>('');
  const [targetRole, setTargetRole] = useState<UserRole | 'ALL'>('ALL');

  const handleApproveAllDrivers = async () => {
    const pendingDrivers = users.filter(u => u.role === 'DRIVER' && u.status === 'PENDING_APPROVAL');
    if (pendingDrivers.length === 0) return alert('لا يوجد كباتن بانتظار التفعيل');
    if (!confirm(`هل أنت متأكد من تفعيل ${pendingDrivers.length} كابتن دفعة واحدة؟`)) return;

    setLoading(true);
    try {
      const batch = writeBatch(db);
      pendingDrivers.forEach(u => {
        batch.update(doc(db, "users", u.id), { status: 'APPROVED' });
        // إرسال إشعار تلقائي
        const notifyRef = doc(collection(db, "notifications"));
        batch.set(notifyRef, {
          userId: u.id,
          title: "تم تفعيل حسابك!",
          body: "مبروك، تمت مراجعة بياناتك وأصبحت الآن كابتن معتمد في وصلها أشمون.",
          type: 'SUCCESS',
          createdAt: Date.now(),
          read: false
        });
      });
      await batch.commit();
      alert('تم تفعيل كافة الكباتن بنجاح');
    } catch (e) { alert('خطأ في العملية الجماعية'); } finally { setLoading(false); }
  };

  const handleWalletBlast = async () => {
    const num = parseFloat(amount);
    if (isNaN(num) || num === 0) return alert('يرجى إدخال مبلغ صحيح');
    const filtered = users.filter(u => targetRole === 'ALL' || u.role === targetRole);
    if (!confirm(`سيتم إضافة/خصم ${num} ج.م من ${filtered.length} مستخدم. هل أنت متأكد؟`)) return;

    setLoading(true);
    try {
      const batch = writeBatch(db);
      filtered.forEach(u => {
        const newBalance = (u.wallet?.balance || 0) + num;
        batch.update(doc(db, "users", u.id), { "wallet.balance": newBalance });

        // تسجيل المعاملة المالية
        const transRef = doc(collection(db, "transactions"));
        batch.set(transRef, {
          userId: u.id,
          amount: Math.abs(num),
          type: num > 0 ? 'CREDIT' : 'DEBIT',
          description: "تحديث رصيد جماعي من الإدارة العليا",
          createdAt: Date.now()
        });
      });
      await batch.commit();
      alert('تم تحديث المحافظ بنجاح');
      setAmount('');
    } catch (e) { alert('خطأ في تحديث المحافظ'); } finally { setLoading(false); }
  };

  return (
    <div className="bg-slate-900 rounded-[4rem] p-12 text-white space-y-10 shadow-2xl relative overflow-hidden animate-in zoom-in duration-500">
       <div className="absolute top-0 right-0 w-96 h-96 bg-emerald-500/10 blur-[150px] -mr-48 -mt-48"></div>
       <div className="flex flex-col md:flex-row justify-between items-center gap-6 relative z-10">
          <div className="text-center md:text-right">
             <h3 className="text-3xl font-black flex items-center gap-4 justify-center md:justify-start">
                التحكم المتقدم <Zap className="text-emerald-400 h-8 w-8 fill-emerald-400" />
             </h3>
             <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-widest">تحديث كامل قاعدة البيانات بضغطة زر</p>
          </div>
          <button onClick={handleApproveAllDrivers} disabled={loading} className="bg-emerald-600 hover:bg-emerald-500 px-10 py-6 rounded-[2rem] font-black text-xs flex items-center gap-3 shadow-xl active:scale-95 transition-all text-white">
             {loading ? <RefreshCw className="h-4 w-4 animate-spin" /> : <ShieldCheck className="h-4 w-4" />}
             تفعيل كافة الكباتن المعلقين
          </button>
       </div>

       <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 relative z-10">
          <div className="bg-white/5 p-10 rounded-[3rem] border border-white/10 space-y-6 text-right">
             <div className="flex items-center gap-4 mb-2 justify-end">
                <h4 className="font-black text-xl">توزيع أرصدة جماعي</h4>
                <div className="p-3 bg-white/10 rounded-2xl"><DollarSign className="text-emerald-400" /></div>
             </div>
             <div className="flex flex-col gap-4">
                <div className="flex gap-2 bg-black/20 p-2 rounded-[1.8rem]">
                   {['ALL', 'DRIVER', 'CUSTOMER'].map(r => (
                     <button key={r} onClick={() => setTargetRole(r as any)} className={`flex-1 py-3 rounded-2xl text-[10px] font-black transition-all ${targetRole === r ? 'bg-white text-slate-900 shadow-lg' : 'text-slate-500 hover:text-white'}`}>
                        {r === 'ALL' ? 'الكل' : r === 'DRIVER' ? 'كباتن' : 'عملاء'}
                     </button>
                   ))}
                </div>
                <div className="relative">
                   <input type="number" value={amount} onChange={e => setAmount(e.target.value)} placeholder="0.00" className="w-full bg-white/5 border border-white/10 rounded-[1.5rem] p-5 text-2xl font-black outline-none focus:border-emerald-500 transition-all text-center text-white" />
                   <span className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-600 font-black">ج.م</span>
                </div>
                <button onClick={handleWalletBlast} disabled={loading} className="w-full bg-white text-slate-900 py-6 rounded-[1.8rem] font-black text-sm active:scale-95 transition-all shadow-2xl flex items-center justify-center gap-3">
                   {loading ? <RefreshCw className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />} تنفيذ الإيداع الجماعي
                </button>
             </div>
          </div>

          <div className="bg-white/5 p-10 rounded-[3rem] border border-white/10 flex flex-col justify-center items-center text-center space-y-4">
             <Layers className="h-16 w-16 text-slate-700" />
             <h4 className="text-lg font-black text-slate-400">الإجراءات المجمعة القادمة</h4>
             <p className="text-[10px] font-bold text-slate-600 max-w-xs leading-relaxed">سيتم إضافة إمكانية إرسال إشعارات جماعية لكافة المستخدمين وإعادة ضبط الحالة السنوية للحسابات قريباً.</p>
          </div>
       </div>
    </div>
  );
};

const SuperAdminDashboard: React.FC<{ user: User }> = ({ user }) => {
