        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-2xl border-t border-slate-100 px-6 md:px-10 py-4 md:py-6 flex justify-around items-center z-[150] shadow-2xl flex-row-reverse">
         {[
           {id: 'NEW', icon: <Plus className="h-6 w-6 md:h-7 md:w-7" />, label: 'طلب'},
           {id: 'ACTIVITY', icon: <History className="h-6 w-6 md:h-7 md:w-7" />, label: 'نشاطي'},
           {id: 'PROFILE', icon: <UserIcon className="h-6 w-6 md:h-7 md:w-7" />, label: 'حسابي'}
