  const [offerPrice, setOfferPrice] = useState<string>('');
  const [showChat, setShowChat] = useState(false);
  const [showPrescriptionModal, setShowPrescriptionModal] = useState<string | null>(null);

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstance = useRef<any>(null);
  const watchId = useRef<number | null>(null);
  const driverMarker = useRef<any>(null);

  useEffect(() => {
    if (mapContainerRef.current && !mapInstance.current) {
      mapInstance.current = L.map(mapContainerRef.current, { zoomControl: false, attributionControl: false }).setView([30.556, 31.008], 11);
      L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png').addTo(mapInstance.current);
    }
  }, []);

  useEffect(() => {
    if (isOnline) {
      if ("geolocation" in navigator) {
        watchId.current = navigator.geolocation.watchPosition(
          (pos) => {
            const { latitude, longitude } = pos.coords;
            updateDoc(doc(db, "users", user.id), {
              location: { lat: latitude, lng: longitude, updatedAt: Date.now() }
            });
            if (mapInstance.current && driverMarker.current) {
               driverMarker.current.setLatLng([latitude, longitude]);
            }
          },
          null, { enableHighAccuracy: true }
        );
      }
    }
    return () => { if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current); };
  }, [isOnline, user.id]);

  useEffect(() => {
    if (!isOnline || user.status !== 'APPROVED') return;
    const unsubAvailable = onSnapshot(query(collection(db, "orders"), where("status", "==", OrderStatus.WAITING_FOR_OFFERS)), (snapshot) => {
      setAvailableOrders(snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[]);
    });
    const unsubActive = onSnapshot(query(collection(db, "orders"), where("driverId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
    return () => { unsubAvailable(); unsubActive(); };
  }, [isOnline, user.id, user.status]);

  const getDistrictName = (villageName?: string) => {
    return MENOFIA_DATA.find(d => d.villages.some(v => v.name === villageName))?.name || 'المنوفية';
  };

  const handleWhatsAppCustomer = (phone: string) => {
    const msg = `مرحباً، أنا كابتن "وصـــلــهــا"، أنا في طريقي إليك الآن.`;
    window.open(`https://wa.me/2${phone}?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const handleSendOffer = async (orderId: string) => {
    const price = parseFloat(offerPrice);
    if (!price || price <= 0 || isSubmitting) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "offers"), {
        orderId: orderId, driverId: user.id, driverName: user.name, driverPhone: user.phone,
        driverRating: 5.0, vehicleType: user.vehicleType || 'TOKTOK', price: price, createdAt: Date.now()
      });
      setShowOfferInput(null);
      setOfferPrice('');
    } catch (e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  const updateOrderStatus = async (status: OrderStatus) => {
    if (!activeOrder || isSubmitting) return;
    setIsSubmitting(true);
    try {
      const updates: any = { status };
      if (status === OrderStatus.DELIVERED) updates.deliveredAt = Date.now();
      await updateDoc(doc(db, "orders", activeOrder.id), updates);
    } catch (e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  if (user.status !== 'APPROVED') {
     return <div className="p-20 text-center font-black">حسابك قيد المراجعة في المنوفية...</div>;
  }

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('HOME')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onBack={() => setActiveView('HOME')} onUpdate={() => {}} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50">
      {/* Modal لعرص الروشتة بوضوح */}
      {showPrescriptionModal && <PrescriptionModal url={showPrescriptionModal} onClose={() => setShowPrescriptionModal(null)} />}

      <div ref={mapContainerRef} className={`rh-map-view absolute inset-0 z-0 transition-opacity duration-500 ${activeView === 'MAP' ? 'opacity-100 block' : 'opacity-0 hidden'}`}></div>

      <div className={`rh-ui-panel no-scrollbar px-6 space-y-8 pb-32 pt-8 animate-in fade-in overflow-y-auto z-[100] ${activeView === 'MAP' ? 'translate-y-full opacity-0' : 'translate-y-0 opacity-100 bg-slate-50'}`}>
        <div className="bottom-sheet-grabber lg:hidden"></div>
        <div className="max-w-2xl mx-auto space-y-8">
            <div className={`p-10 rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl transition-all duration-700 ${isOnline ? 'bg-emerald-600' : 'bg-slate-950'}`}>
               <div>
                  <h2 className="text-3xl font-black tracking-tighter">{isOnline ? 'نشط في المنوفية' : 'متوقف'}</h2>
                  <p className="text-[10px] font-black opacity-60 mt-2 uppercase tracking-widest">تغطية كاملة للمحافظة</p>
               </div>
               <button onClick={() => setIsOnline(!isOnline)} className={`p-6 rounded-[2.5rem] shadow-2xl active:scale-90 transition-all ${isOnline ? 'bg-white text-emerald-600' : 'bg-emerald-500 text-white'}`}><Power className="h-10 w-10" /></button>
            </div>

            {activeOrder ? (
               <div className="bg-white rounded-[4rem] shadow-2xl p-10 space-y-10 animate-in zoom-in border-t-8 border-t-emerald-500">
                  <div className="flex justify-between items-center">
                     <span className="bg-emerald-100 text-emerald-700 px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-widest">{activeOrder.status}</span>
                     <p className="text-5xl font-black text-slate-950">{activeOrder.price} <span className="text-lg opacity-30 font-bold uppercase">ج.م</span></p>
                  </div>

                  {/* عرض تفاصيل الروشتة إذا كان طلب صيدلية */}
                  {activeOrder.category === 'PHARMACY' && (
                    <div className="space-y-4 animate-reveal" style={{animationDelay: '0.2s'}}>
                       <div className="bg-sky-50 border-2 border-sky-100 p-8 rounded-[3rem] text-right space-y-4 shadow-inner">
                          <div className="flex items-center justify-between">
                            <p className="text-[10px] font-black text-sky-600 uppercase tracking-[0.2em]">طلب صيدلية مرفق</p>
                            <Pill className="h-5 w-5 text-sky-400" />
                          </div>

                          {activeOrder.notes && (
                            <div className="bg-white/80 p-4 rounded-2xl border border-sky-100">
                               <p className="text-xs font-bold text-slate-700">{activeOrder.notes}</p>
                            </div>
                          )}

                          {activeOrder.prescriptionImage && (
                            <div className="relative group">
                               <div onClick={() => setShowPrescriptionModal(activeOrder.prescriptionImage!)} className="w-full h-56 bg-white rounded-[2rem] overflow-hidden border-2 border-dashed border-sky-200 cursor-pointer transition-all hover:border-sky-400 active:scale-95 shadow-sm">
                                  <img src={activeOrder.prescriptionImage} className="w-full h-full object-cover transition-transform group-hover:scale-110 duration-700" alt="Prescription" />
                                  <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                                     <div className="bg-white/90 p-4 rounded-2xl shadow-xl flex items-center gap-2 font-black text-xs text-sky-600">
                                        <ZoomIn className="h-5 w-5" /> اضغط للتكبير
                                     </div>
                                  </div>
                               </div>
                            </div>
                          )}
                       </div>
                    </div>
                  )}

                  <div className="space-y-8 text-right">
                     <div className="flex gap-6 items-start">
                        <div className="bg-slate-50 p-5 rounded-3xl text-emerald-600 shrink-0"><MapPin className="h-8 w-8" /></div>
                        <div className="flex-1">
                           <p className="helper-text uppercase mb-2 tracking-widest">مسار المشوار</p>
                           <p className="font-black text-2xl text-slate-950 leading-tight mb-2">
                             مركز {getDistrictName(activeOrder.pickup?.villageName)} ({activeOrder.pickup?.villageName})
                             <br />
                             ← مركز {getDistrictName(activeOrder.dropoff?.villageName)} ({activeOrder.dropoff?.villageName})
                           </p>
                        </div>
                     </div>
                  </div>
                  <div className="grid grid-cols-2 md:grid-cols-3 gap-4 pt-4">
                     <a href={`tel:${activeOrder.customerPhone}`} className="bg-slate-950 text-white py-6 rounded-[2rem] font-black text-lg flex items-center justify-center gap-3 shadow-xl active:scale-95 transition-all"><PhoneCall className="h-7 w-7" /></a>
                     <button onClick={() => handleWhatsAppCustomer(activeOrder.customerPhone)} className="bg-[#25D366] text-white py-6 rounded-[2rem] font-black text-lg flex items-center justify-center gap-3 shadow-xl active:scale-95 transition-all"><MessageCircle className="h-7 w-7" /></button>
                     <button onClick={() => setShowChat(true)} className="bg-white border-4 border-slate-50 text-slate-900 py-6 rounded-[2rem] font-black text-lg flex items-center justify-center gap-3 active:scale-95 relative transition-all"><Bot className="h-7 w-7" /></button>
                     <button onClick={() => updateOrderStatus(activeOrder.status === OrderStatus.ACCEPTED ? OrderStatus.PICKED_UP : OrderStatus.DELIVERED)} disabled={isSubmitting} className="col-span-full bg-emerald-600 text-white py-8 rounded-[2.5rem] font-black text-2xl shadow-2xl active:scale-95 mt-2 animate-glow">
                        {isSubmitting ? <Loader2 className="h-10 w-10 animate-spin mx-auto" /> : activeOrder.status === OrderStatus.ACCEPTED ? 'تأكيد الاستلام' : 'تم التوصيل والتحصيل'}
                     </button>
                  </div>
               </div>
            ) : (
               <div className="space-y-6">
                  <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.4em] px-4 text-right">مشاوير المنوفية المتاحة ({availableOrders.length})</h3>
                  {availableOrders.map(o => (
                     <div key={o.id} className="bg-white p-10 rounded-[4rem] border-2 border-slate-50 shadow-xl space-y-8 animate-reveal transition-all hover:border-emerald-500">
                        {showOfferInput === o.id ? (
                          <div className="space-y-8 animate-in zoom-in text-center">
                             <h4 className="text-xl font-black">تقديم عرض سعر</h4>
                             <div className="relative">
                                <input autoFocus type="number" value={offerPrice} onChange={e => setOfferPrice(e.target.value)} placeholder={o.price.toString()} className="w-full bg-slate-50 border-none rounded-3xl p-8 text-5xl font-black text-center outline-none focus:ring-4 focus:ring-emerald-500/10" />
                                <DollarSign className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-200 h-10 w-10" />
                             </div>
                             <div className="flex gap-4">
                                <button onClick={() => setShowOfferInput(null)} className="flex-1 py-6 rounded-[2rem] font-black text-slate-400">إلغاء</button>
                                <button onClick={() => handleSendOffer(o.id)} disabled={isSubmitting} className="flex-[2] bg-emerald-600 text-white py-6 rounded-[2rem] font-black shadow-xl flex items-center justify-center gap-3">
                                   {isSubmitting ? <Loader2 className="h-6 w-6 animate-spin" /> : <><Check className="h-6 w-6" /> إرسال العرض</>}
                                </button>
                             </div>
                          </div>
                        ) : (
                          <>
                            <div className="flex justify-between items-start text-right">
                               <div className="space-y-2">
                                  <div className="flex items-center gap-2 text-emerald-600 mb-2 justify-end">
                                     <span className="text-[10px] font-black uppercase tracking-widest">{o.category === 'PHARMACY' ? 'صيدلية 💊' : `مركز ${getDistrictName(o.pickup?.villageName)}`}</span>
                                     <Building2 className="h-4 w-4" />
                                  </div>
                                  <p className="text-2xl font-black text-slate-950 leading-none">{o.pickup?.villageName} ← {o.dropoff?.villageName}</p>
                                  <p className="text-[10px] font-black text-emerald-600 mt-2 bg-emerald-50 inline-block px-4 py-1.5 rounded-full">{o.requestedVehicleType}</p>
                                  {o.category === 'PHARMACY' && o.prescriptionImage && (
                                    <div className="flex items-center gap-2 text-sky-600 text-[10px] font-black mt-2">
                                       <Eye className="h-3 w-3" /> صورة الروشتة مرفقة
                                    </div>
                                  )}
                               </div>
                               <div className="bg-slate-950 text-emerald-400 p-6 rounded-3xl font-black text-3xl shadow-2xl shrink-0">{o.price}</div>
                            </div>
                            <button onClick={() => { setShowOfferInput(o.id); setOfferPrice(o.price.toString()); }} className="w-full bg-slate-950 text-white py-7 rounded-[2.5rem] font-black text-xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4">
                                <Zap className="h-6 w-6 text-emerald-400" /> تقديم عرض سعر
                            </button>
                          </>
                        )}
                     </div>
                  ))}
                  {availableOrders.length === 0 && (
                     <div className="py-24 text-center text-slate-300 font-black border-4 border-dashed border-slate-100 rounded-[4rem] bg-white">
                        <Bot className="h-16 w-16 mx-auto mb-6 opacity-20" />
                        <p className="tracking-widest uppercase">بانتظار طلبات جديدة في المنوفية...</p>
                     </div>
                  )}
               </div>
            )}
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-2xl border-t border-slate-100 p-8 flex justify-around items-center z-[200] shadow-[0_-20px_50px_rgba(0,0,0,0.12)]">
         {[
           {id: 'HOME', icon: <Home className="h-7 w-7" />, label: 'الرئيسية'},
           {id: 'MAP', icon: <MapIcon className="h-7 w-7" />, label: 'الخريطة'},
           {id: 'ACTIVITY', icon: <History className="h-7 w-7" />, label: 'سجلي'},
           {id: 'PROFILE', icon: <UserIcon className="h-7 w-7" />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-2 transition-all ${activeView === tab.id ? 'text-emerald-600 scale-125' : 'text-slate-300'}`}>
              <div className={`p-3.5 rounded-[1.5rem] transition-all ${activeView === tab.id ? 'bg-emerald-50 shadow-inner' : ''}`}>{tab.icon}</div>
              <span className="text-[10px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CourierDashboard;

import React, { useState, useRef, useEffect } from 'react';

// Types
import type { User, Order } from '../types';
import { OrderStatus } from '../types';
import { MENOFIA_DATA } from '../config/constants';

// Services
import { auth, db } from '../services/firebase';
import { doc, updateDoc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { signOut } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";

// Icons
import { 
  User as UserIcon, Smartphone, Edit3, Camera, Loader2, ChevronRight, 
  Bike, Car, Star, ShieldCheck, Zap, Wallet as WalletIcon, ArrowRight,
  Building2, MapPin, LogOut, AlertTriangle
} from 'lucide-react';

const ProfileView: React.FC<{ user: User, onUpdate: (u: User) => void, onBack: () => void, onOpenWallet?: () => void }> = ({ user, onUpdate, onBack, onOpenWallet }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [name, setName] = useState(user.name);
  const [phone, setPhone] = useState(user.phone);
  const [isSaving, setIsSaving] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const getDistrictName = () => {
    return "أشمون"; 
  };

  const handleUpdateProfile = async () => {
    if (!name.trim() || phone.length < 11) {
      alert("يرجى التأكد من الاسم ورقم الهاتف");
      return;
    }
    setIsSaving(true);
    try {
      await updateDoc(doc(db, "users", user.id), { name, phone });
      onUpdate({ ...user, name, phone });
      setIsEditing(false);
    } catch (e) { 
      alert('خطأ في التحديث'); 
    } finally { 
      setIsSaving(false); 
    }
  };

  const handleImageChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) return alert('يرجى اختيار ملف صورة صحيح');
    if (file.size > 2 * 1024 * 1024) return alert('حجم الصورة كبير جداً، يرجى اختيار صورة أقل من 2 ميجابايت');

    setIsUploading(true);
    const reader = new FileReader();

    reader.onload = async () => {
      const base64Image = reader.result as string;
      try {
        await updateDoc(doc(db, "users", user.id), { photoURL: base64Image });
        onUpdate({ ...user, photoURL: base64Image });
      } catch (err) {
        alert('فشل في حفظ الصورة');
      } finally {
        setIsUploading(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleLogout = () => {
    if (window.confirm('هل أنت متأكد أنك تريد تسجيل الخروج من تطبيق وصلها؟')) {
      signOut(auth);
    }
  };

  return (
    <div className="max-w-2xl mx-auto pb-32 space-y-8 p-6 animate-in slide-in-from-bottom duration-500 overflow-y-auto h-full no-scrollbar">
      <div className="flex items-center justify-between px-2">
        <div className="text-right">
           <h2 className="text-3xl font-black text-slate-900 tracking-tighter">حسابي الشخصي</h2>
           <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">عضوية وصلها المميزة</p>
        </div>
        <button onClick={onBack} className="p-3.5 bg-white border border-slate-100 rounded-[1.5rem] shadow-sm active:scale-90 transition-all"><ChevronRight /></button>
      </div>

      <div className="bg-[#2D9469] rounded-[4rem] p-12 text-white text-center shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full blur-[100px] -mr-32 -mt-32"></div>

        <div className="relative inline-block group">
          <div className="w-40 h-40 bg-white/20 backdrop-blur-xl rounded-[3.5rem] mx-auto flex items-center justify-center mb-8 overflow-hidden border-8 border-white/10 shadow-2xl relative transition-transform hover:scale-105 duration-500">
            {isUploading ? (
              <div className="absolute inset-0 bg-black/20 flex items-center justify-center z-10">
                <Loader2 className="h-10 w-10 animate-spin text-white" />
              </div>
            ) : null}

            {user.photoURL ? (
              <img src={user.photoURL} className="w-full h-full object-cover" alt="Profile" />
            ) : (
              <UserIcon className="h-20 w-20 text-white/50" />
            )}
          </div>

          <button 
            onClick={() => fileInputRef.current?.click()}
            className="absolute bottom-6 -right-2 bg-white text-[#2D9469] p-4 rounded-3xl shadow-xl active:scale-75 transition-all border-4 border-[#2D9469] hover:rotate-12"
          >
            <Camera className="h-6 w-6" />
          </button>

          <input type="file" ref={fileInputRef} onChange={handleImageChange} className="hidden" accept="image/*" />
        </div>

        <h3 className="text-3xl font-black tracking-tight">{user.name}</h3>
        <div className="flex items-center justify-center gap-3 mt-3">
          {user.status === 'APPROVED' && (
            <div className="flex items-center gap-2 bg-emerald-400/20 text-emerald-100 px-4 py-1.5 rounded-full text-[9px] font-black border border-emerald-400/20 backdrop-blur-md">
               <ShieldCheck className="h-4 w-4" /> حساب موثق في المنوفية
            </div>
          )}
        </div>
      </div>

      <div className="space-y-6">
        {user.role === 'DRIVER' && (
           <div className="grid grid-cols-2 gap-4 px-2">
              <div className="bg-white p-7 rounded-[2.5rem] shadow-sm border border-slate-50 text-center space-y-2">
                 <div className="bg-emerald-50 p-3 rounded-2xl inline-block text-emerald-600 mb-2"><Building2 className="h-6 w-6" /></div>
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">المركز</p>
                 <p className="font-black text-slate-800 uppercase leading-none">مركز {getDistrictName()}</p>
              </div>
              <div className="bg-white p-7 rounded-[2.5rem] shadow-sm border border-slate-50 text-center space-y-2">
                 <div className="bg-amber-50 p-3 rounded-2xl inline-block text-amber-500 mb-2"><MapPin className="h-6 w-6" /></div>
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">التغطية</p>
                 <p className="font-black text-slate-800 uppercase leading-none">كامل المحافظة</p>
              </div>
           </div>
        )}

        {onOpenWallet && (
           <div className="px-2">
              <button onClick={onOpenWallet} className="w-full bg-slate-950 text-white p-10 rounded-[3.5rem] flex justify-between items-center shadow-xl group active:scale-95 transition-all">
                 <div className="flex items-center gap-6 text-right">
                    <div className="bg-emerald-500 p-5 rounded-[2.5rem] group-hover:scale-110 transition-transform shadow-xl">
                       <WalletIcon className="h-8 w-8 text-white" />
                    </div>
                    <div>
                       <p className="text-[10px] font-black text-emerald-400 uppercase tracking-widest mb-1">رصيدي الحالي</p>
                       <p className="text-4xl font-black">{(user.wallet?.balance || 0).toFixed(2)} <span className="text-sm opacity-40 font-bold">ج.م</span></p>
                    </div>
                 </div>
                 <ArrowRight className="h-8 w-8 text-slate-700" />
              </button>
           </div>
        )}

        <div className="bg-white p-10 rounded-[3.5rem] shadow-sm border border-slate-100 space-y-8 mx-2">
           <div className="flex justify-between items-center">
              <h4 className="font-black text-slate-800 text-lg flex items-center gap-3"><Edit3 className="h-5 w-5 text-[#2D9469]" /> البيانات الأساسية</h4>
              <button 
                onClick={() => isEditing ? handleUpdateProfile() : setIsEditing(true)} 
                disabled={isSaving}
                className={`font-black text-xs uppercase tracking-widest px-8 py-3 rounded-[1.2rem] transition-all ${isEditing ? 'bg-emerald-500 text-white shadow-xl scale-105' : 'bg-slate-50 text-slate-400 hover:text-[#2D9469]'}`}
              >
                {isSaving ? <Loader2 className="h-4 w-4 animate-spin" /> : isEditing ? 'حفظ' : 'تعديل'}
              </button>
           </div>
           <div className="space-y-6">
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">الاسم</label>
                 <input value={name} onChange={e => setName(e.target.value)} disabled={!isEditing} className={`w-full bg-slate-50 rounded-3xl p-6 font-black text-sm outline-none transition-all ${isEditing ? 'bg-white border-2 border-emerald-100 ring-4 ring-emerald-500/5' : 'border-none shadow-inner'}`} />
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">رقم الموبايل</label>
                 <input value={phone} onChange={e => setPhone(e.target.value)} disabled={!isEditing} maxLength={11} className={`w-full bg-slate-50 rounded-3xl p-6 font-black text-sm outline-none transition-all text-left ${isEditing ? 'bg-white border-2 border-emerald-100 ring-4 ring-emerald-500/5' : 'border-none shadow-inner'}`} dir="ltr" />
              </div>
           </div>
        </div>

        {/* زر تسجيل الخروج الجديد */}
        <div className="px-2 pt-4">
           <button 
             onClick={handleLogout}
             className="w-full bg-rose-50 text-rose-600 p-8 rounded-[3rem] flex items-center justify-center gap-4 shadow-sm border border-rose-100 hover:bg-rose-100 active:scale-95 transition-all group"
           >
              <div className="bg-white p-3 rounded-2xl shadow-sm group-hover:scale-110 transition-transform">
                <LogOut className="h-6 w-6 text-rose-500 rotate-180" />
              </div>
              <span className="font-black text-lg tracking-tight">تسجيل الخروج من الحساب</span>
           </button>
        </div>
      </div>

      <div className="p-10 text-center opacity-30 grayscale pointer-events-none space-y-4">
         <img src="https://img.icons8.com/fluency-systems-filled/512/000000/bicycle.png" className="h-12 w-12 mx-auto" />
         <p className="text-[9px] font-black uppercase tracking-[0.5em]">كل الحقوق محفوظة لشركة وصلها المنوفية ©M.R Mahmoud Khalifa</p>
      </div>
    </div>
  );
};

export default ProfileView;

@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;900&display=swap');

:root {
  --brand-emerald: #10b981;
  --brand-emerald-deep: #065f46;
  --slate-950: #020617;
  --slate-900: #0f172a;
  --header-height-mobile: 70px;
  --header-height-desktop: 90px;

  /* أحجام خطوط ديناميكية */
  --font-size-base: clamp(0.875rem, 1vw + 0.5rem, 1.125rem);
  --font-size-h1: clamp(1.5rem, 4vw + 1rem, 3.5rem);
  --font-size-h2: clamp(1.25rem, 2vw + 1rem, 2.25rem);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: 'Cairo', sans-serif;
  direction: rtl;
  background-color: #f1f5f9;
  color: var(--slate-900);
  -webkit-font-smoothing: antialiased;
  overflow: hidden;
  font-size: var(--font-size-base);
  height: 100dvh; /* استخدام Dynamic Viewport Height */
  width: 100vw;
}

.app-container {
  display: flex;
  flex-direction: column;
  height: 100dvh;
  width: 100vw;
}

.main-content {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* تخطيط الخريطة واللوحة */
.rh-layout {
  position: relative;
  height: 100%;
  width: 100%;
  display: flex;
  flex-direction: column;
}

/* تحسين استجابة اللوحة العائمة */
.rh-ui-panel {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: white;
  border-top-left-radius: 2.5rem;
  border-top-right-radius: 2.5rem;
  box-shadow: 0 -15px 50px -12px rgba(0, 0, 0, 0.15);
  max-height: 85dvh;
  height: auto;
  overflow-y: auto;
  padding-bottom: calc(5rem + env(safe-area-inset-bottom));
  transition: all 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

/* تحسينات الصور المتجاوبة */
img {
  max-width: 100%;
  height: auto;
  object-fit: cover;
}

/* Media Queries محسنة */

/* تابلت (iPad / Small Laptops) */
@media (min-width: 768px) {
  .rh-ui-panel {
    bottom: 2rem;
    left: 2rem;
    right: auto;
    width: clamp(380px, 40vw, 450px);
    border-radius: 2.5rem;
    max-height: calc(100% - 4rem);
    padding-bottom: 2rem;
  }
}

/* ديسكتوب كبير */
@media (min-width: 1024px) {
  .rh-layout { 
    flex-direction: row-reverse; 
  }
  .rh-map-view { 
    position: relative; 
    flex: 1; 
    margin: 1.5rem; 
    border-radius: 2.5rem; 
    overflow: hidden;
    box-shadow: 0 10px 25px -5px rgba(0,0,0,0.1);
  }
  .rh-ui-panel {
    position: relative;
    width: clamp(400px, 30vw, 500px);
    height: calc(100% - 3rem);
    max-height: none;
    margin: 1.5rem 0 1.5rem 1.5rem;
    border-radius: 2.5rem;
    box-shadow: none;
    border: 1px solid #e2e8f0;
    bottom: auto;
    left: auto;
    right: auto;
  }
}

/* أحجام أزرار محسنة للمس */
button, a {
  min-height: 44px;
  min-width: 44px;
}

/* تخصيص الـ scrollbar */
.no-scrollbar::-webkit-scrollbar { display: none; }
.no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }

.label-strong { font-weight: 900; color: var(--slate-950); }
.helper-text { font-weight: 600; color: #64748b; font-size: 0.75rem; }

import React, { useState } from 'react';

// Types
import type { User, VehicleType } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Services
import { auth, db } from '../services/firebase';
import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword 
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { doc, getDoc, setDoc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Icons
import { 
  Bike, Mail, Lock, User as UserIcon, 
  Smartphone, ShieldCheck,
  ChevronLeft, Car, Globe, Trophy, 
  Loader2, ArrowRight, MessageCircle, Zap
} from 'lucide-react';

const APP_LOGO_ICON = "https://img.icons8.com/fluency-systems-filled/512/FFFFFF/bicycle.png";

const Onboarding: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
  const [step, setStep] = useState(0);
  const slides = [
    { title: "أهلاً بك في المنوفية", body: "وصـــلــهــا هو تطبيق التوصيل الأول والوحيد المخصص لخدمة كافة مراكز وقرى محافظة المنوفية.", icon: <Globe className="h-16 w-16 md:h-20 md:w-20 text-emerald-400" />, color: "from-[#2D9469] to-[#1e6346]" },
    { title: "كباتن ثقة وأمان", body: "كل رحلاتك مراقبة ومؤمنة، كباتننا هم جيرانك وأهلك من قلب مراكزنا العشرة.", icon: <ShieldCheck className="h-16 w-16 md:h-20 md:w-20 text-emerald-400" />, color: "from-slate-900 to-slate-800" },
    { title: "وفر وقتك وفلوسك", body: "أفضل تسعيرة في أقاليم مصر، مع نظام نقاط ومكافآت لكل مشوار بتمشي معانا فيه.", icon: <Trophy className="h-16 w-16 md:h-20 md:w-20 text-amber-400" />, color: "from-indigo-900 to-indigo-800" }
  ];

  return (
    <div className={`fixed inset-0 z-[5000] flex flex-col transition-all duration-1000 bg-gradient-to-br ${slides[step].color}`}>
       <div className="flex-1 flex flex-col items-center justify-center p-6 md:p-10 text-center text-white space-y-8 md:space-y-12">
          <div className="bg-white/10 p-10 md:p-16 rounded-[3rem] md:rounded-[4.5rem] backdrop-blur-3xl animate-in zoom-in duration-700 shadow-2xl border border-white/20">
             {slides[step].icon}
          </div>
          <div className="space-y-4 md:space-y-6 animate-in slide-in-from-bottom duration-1000 max-w-sm">
             <h2 className="text-3xl md:text-5xl font-black tracking-tighter leading-tight">{slides[step].title}</h2>
             <p className="text-white/70 font-bold leading-relaxed text-sm md:text-md">{slides[step].body}</p>
          </div>
       </div>
       <div className="p-8 md:p-12 pb-16 md:pb-20 space-y-8 md:space-y-12 bg-gradient-to-t from-black/20 to-transparent">
          <div className="flex justify-center gap-2 md:gap-3">
             {slides.map((_, i) => (
               <div key={i} className={`h-2 rounded-full transition-all duration-500 ${i === step ? 'w-12 md:w-16 bg-white' : 'w-2 bg-white/20'}`}></div>
             ))}
          </div>
          <div className="flex gap-3 md:gap-4">
             {step > 0 && (
               <button onClick={() => setStep(step - 1)} className="p-5 md:p-7 bg-white/10 text-white rounded-2xl md:rounded-[2.5rem] backdrop-blur-md active:scale-90 transition-all">
                 <ArrowRight className="h-5 w-5 md:h-6 md:w-6" />
               </button>
             )}
             <button onClick={() => step < slides.length - 1 ? setStep(step + 1) : onComplete()} className="flex-1 bg-white text-slate-900 py-5 md:py-7 rounded-[2rem] md:rounded-[3rem] font-black text-lg md:text-xl flex items-center justify-center gap-3 md:gap-4 shadow-xl active:scale-95 transition-all">
                {step === slides.length - 1 ? 'ابدأ الآن' : 'استمر'}
                <ChevronLeft className="h-5 w-5 md:h-6 md:w-6" />
             </button>
          </div>
       </div>
