};

const Login: React.FC<{ onLogin: (user: User) => void }> = ({ onLogin }) => {
  const [showOnboarding, setShowOnboarding] = useState(true);
  const [isRegistering, setIsRegistering] = useState(false);
  const [step, setStep] = useState<'INPUT' | 'OTP'>('INPUT');
  const [role, setRole] = useState<'CUSTOMER' | 'DRIVER'>('CUSTOMER');
  const [vehicleType, setVehicleType] = useState<VehicleType>('TOKTOK');
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [phone, setPhone] = useState('');
  const [otp, setOtp] = useState('');
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMsg(null);
    if (isRegistering && step === 'INPUT') {
      const nameParts = name.trim().split(/\s+/);
      if (nameParts.length < 4) { setErrorMsg('يرجى إدخال الاسم رباعياً'); return; }
      const phoneRegex = /^01[0125][0-9]{8}$/;
      if (!phoneRegex.test(phone)) { setErrorMsg('رقم الهاتف غير صحيح'); return; }
      if (password.length < 8) { setErrorMsg('كلمة المرور قصيرة'); return; }

      setLoading(true);
      const whatsappMsg = `أنا ${name}\nرقم هاتفي: ${phone}\nمحتاج كود تفعيل لتطبيق وصـــلــهــا المنوفية.`;
      window.open(`https://wa.me/201065019364?text=${encodeURIComponent(whatsappMsg)}`, '_blank');
      setTimeout(() => { setStep('OTP'); setLoading(false); }, 1000);
      return;
    }
    setLoading(true);
    try {
      if (isRegistering) {
        const userCredential = await createUserWithEmailAndPassword(auth, email, password);
        const userData: User = {
          id: userCredential.user.uid, email, name, phone, role,
          status: role === 'DRIVER' ? 'PENDING_APPROVAL' : 'APPROVED',
          vehicleType: role === 'DRIVER' ? vehicleType : undefined,
          wallet: { balance: 0, totalEarnings: 0, withdrawn: 0 }
        };
        await setDoc(doc(db, "users", userCredential.user.uid), userData);
        onLogin(userData);
      } else {
        const userCredential = await signInWithEmailAndPassword(auth, email, password);
        const userSnap = await getDoc(doc(db, "users", userCredential.user.uid));
        if (userSnap.exists()) onLogin(stripFirestore(userSnap.data()) as User);
      }
    } catch (err: any) { 
      setErrorMsg("خطأ في البيانات، تأكد من البريد وكلمة المرور.");
    } finally { setLoading(false); }
  };

  if (showOnboarding) return <Onboarding onComplete={() => setShowOnboarding(false)} />;

  return (
    <div className="min-h-screen bg-[#f8fafc] flex flex-col items-center justify-center p-4 md:p-6 font-['Cairo'] relative overflow-y-auto">
      <div className="w-full max-w-lg bg-white rounded-[3rem] md:rounded-[5rem] shadow-2xl border border-slate-50 overflow-hidden animate-in zoom-in duration-700">
        <div className="bg-[#2D9469] p-10 md:p-20 text-center relative">
          <div className="bg-white/10 p-6 md:p-8 rounded-[2rem] md:rounded-[3rem] backdrop-blur-xl border border-white/20 inline-block mb-6 md:mb-8 shadow-2xl">
             <img src={APP_LOGO_ICON} alt="Logo" className="h-16 w-16 md:h-24 md:w-24 mx-auto" />
          </div>
          <h1 className="text-4xl md:text-6xl font-black text-white tracking-tighter">وصـــلــهــا</h1>
          <p className="text-emerald-100/60 font-bold text-[9px] md:text-[10px] uppercase tracking-[0.4em] mt-3">المنوفية • تغطية شاملة</p>
        </div>
        <div className="p-8 md:p-12">
          {errorMsg && <div className="mb-6 p-4 md:p-6 bg-rose-50 text-rose-600 rounded-2xl md:rounded-[2rem] text-xs md:text-sm font-black border border-rose-100">{errorMsg}</div>}
          <form onSubmit={handleAuth} className="space-y-4 md:space-y-6">
            {isRegistering ? (
              step === 'INPUT' ? (
                <div className="space-y-4 md:space-y-6">
                  <div className="flex bg-slate-100 p-1.5 md:p-2 rounded-2xl md:rounded-[2.5rem]">
                    <button type="button" onClick={() => setRole('CUSTOMER')} className={`flex-1 py-3 md:py-4 rounded-xl md:rounded-[2.2rem] font-black text-[11px] md:text-xs ${role === 'CUSTOMER' ? 'bg-white text-[#2D9469] shadow-md' : 'text-slate-400'}`}>عميل</button>
                    <button type="button" onClick={() => setRole('DRIVER')} className={`flex-1 py-3 md:py-4 rounded-xl md:rounded-[2.2rem] font-black text-[11px] md:text-xs ${role === 'DRIVER' ? 'bg-white text-[#2D9469] shadow-md' : 'text-slate-400'}`}>كابتن</button>
                  </div>
                  <div className="relative"><UserIcon className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5" /><input type="text" placeholder="الاسم الرباعي" value={name} onChange={e => setName(e.target.value)} required className="w-full bg-slate-50 rounded-2xl md:rounded-[1.8rem] py-4 md:py-6 pr-12 md:pr-14 pl-6 font-black outline-none text-sm md:text-base border border-transparent transition-all" /></div>
                  <div className="relative"><Smartphone className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5" /><input type="tel" placeholder="رقم الموبايل" value={phone} onChange={e => setPhone(e.target.value)} required className="w-full bg-slate-50 rounded-2xl md:rounded-[1.8rem] py-4 md:py-6 pr-12 md:pr-14 pl-6 font-black outline-none text-sm md:text-base text-left" dir="ltr" /></div>
                  <div className="relative"><Mail className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5" /><input type="email" placeholder="البريد الإلكتروني" value={email} onChange={e => setEmail(e.target.value)} required className="w-full bg-slate-50 rounded-2xl md:rounded-[1.8rem] py-4 md:py-6 pr-12 md:pr-14 pl-6 font-black outline-none text-sm md:text-base text-left" dir="ltr" /></div>
                  <div className="relative"><Lock className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5" /><input type="password" placeholder="كلمة المرور" value={password} onChange={e => setPassword(e.target.value)} required className="w-full bg-slate-50 rounded-2xl md:rounded-[1.8rem] py-4 md:py-6 pr-12 md:pr-14 pl-6 font-black outline-none text-sm md:text-base text-left" dir="ltr" /></div>
                  <button type="submit" disabled={loading} className="w-full bg-slate-900 text-white py-5 md:py-7 rounded-2xl md:rounded-[2.5rem] font-black shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3">{loading ? <Loader2 className="h-5 w-5 animate-spin" /> : 'تفعيل الحساب'}</button>
                </div>
              ) : (
                <div className="space-y-6 md:space-y-8 text-center animate-in zoom-in">
                  <h2 className="text-xl md:text-2xl font-black">كود التفعيل</h2>
                  <input type="text" maxLength={6} placeholder="000000" value={otp} onChange={e => setOtp(e.target.value)} className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl md:rounded-[2rem] py-6 md:py-8 text-center text-3xl md:text-4xl font-black tracking-[0.5em]" />
                  <button type="submit" disabled={loading} className="w-full bg-[#2D9469] text-white py-5 md:py-7 rounded-2xl md:rounded-[2.5rem] font-black shadow-xl flex items-center justify-center gap-3">{loading ? <Loader2 className="h-5 w-5 animate-spin" /> : 'ابدأ الآن'}</button>
                </div>
              )
            ) : (
              <div className="space-y-4 md:space-y-6">
                <input type="email" placeholder="البريد الإلكتروني" value={email} onChange={e => setEmail(e.target.value)} required className="w-full bg-slate-50 rounded-2xl md:rounded-[1.8rem] py-4 md:py-6 px-6 md:px-8 font-black outline-none text-sm md:text-base text-left" dir="ltr" />
                <input type="password" placeholder="كلمة المرور" value={password} onChange={e => setPassword(e.target.value)} required className="w-full bg-slate-50 rounded-2xl md:rounded-[1.8rem] py-4 md:py-6 px-6 md:px-8 font-black outline-none text-sm md:text-base text-left" dir="ltr" />
                <button type="submit" disabled={loading} className="w-full bg-[#2D9469] text-white py-5 md:py-7 rounded-2xl md:rounded-[2.5rem] font-black shadow-xl flex items-center justify-center gap-3">{loading ? <Loader2 className="h-5 w-5 animate-spin" /> : 'دخول'}</button>
              </div>
            )}
            <button type="button" onClick={() => { setIsRegistering(!isRegistering); setStep('INPUT'); setErrorMsg(null); }} className="w-full text-slate-400 font-black text-[10px] md:text-[11px] py-4 uppercase tracking-widest">{isRegistering ? 'لديك حساب؟ سجل دخولك' : 'جديد في المنوفية؟ سجل معنا'}</button>
          </form>
        </div>
      </div>
      <footer className="app-footer text-[10px] md:text-xs">© جميع الحقوق محفوظة لشركة وصـــلــهــا المنوفية</footer>
    </div>
  );
};

export default Login;

export type UserRole = 'ADMIN' | 'OPERATOR' | 'DRIVER' | 'CUSTOMER';
export type UserStatus = 'PENDING_APPROVAL' | 'APPROVED' | 'SUSPENDED';
export type PaymentMethod = 'CASH' | 'WALLET';
export type VehicleType = 'TOKTOK' | 'MOTORCYCLE' | 'CAR';
export type OrderCategory = 'TAXI' | 'FOOD' | 'PHARMACY' | 'GROCERY' | 'PARCEL';

export enum OrderStatus {
  PENDING = 'PENDING',
  WAITING_FOR_OFFERS = 'WAITING_FOR_OFFERS',
  ACCEPTED = 'ACCEPTED',
  PICKED_UP = 'PICKED_UP',
  ON_THE_WAY = 'ON_THE_WAY',
  DELIVERED = 'DELIVERED',
  DELIVERED_RATED = 'DELIVERED_RATED',
  CANCELLED = 'CANCELLED'
}

export interface MenuItem {
  id: string;
  name: string;
  price: number;
  description?: string;
  photoURL?: string;
}

export interface Restaurant {
  id: string;
  name: string;
  category: string;
  address: string;
  lat: number;
  lng: number;
  photoURL?: string;
  menuImageURL?: string; // للحفاظ على التوافق القديم
  menuImageURLs?: string[]; // الميزة الجديدة: دعم صور متعددة
  menu: MenuItem[];
  isOpen: boolean;
}

export interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
}

export interface Offer {
  id: string;
  orderId: string;
  driverId: string;
  driverName: string;
  driverPhone: string;
  driverRating: number;
  driverPhoto?: string;
  vehicleType: VehicleType;
  price: number;
  createdAt: number;
}

export interface Village {
  id: string;
  name: string;
  center: { lat: number, lng: number };
}

export interface District {
  id: string;
  name: string;
  villages: Village[];
}

export interface Zone {
  id: string;
  name: string;
  operatorId: string;
  pricing: {
    basePrice: number;
    pricePerKm: number;
    minPrice: number;
    maxPrice: number;
    sameVillagePrice: number;
    multipliers: Record<VehicleType, number>;
  };
  center: { lat: number; lng: number };
}

export interface Order {
  id: string;
  customerId: string;
  customerPhone: string;
  driverId?: string;
  driverName?: string;
  driverPhone?: string;
  driverPhoto?: string;
  operatorId: string;
  zoneId: string;
  category: OrderCategory;
  pickup: { address: string; lat: number; lng: number; villageName?: string };
  dropoff: { address: string; lat: number; lng: number; villageName?: string };
  status: OrderStatus;
  price: number;
  distance: number;
  commission: number;
  operatorCut: number;
  driverCut: number;
  createdAt: number;
  acceptedAt?: number;
  deliveredAt?: number;
  cancelledAt?: number;
  ratedAt?: number;
  notes?: string;
  pickupNotes?: string;
  dropoffNotes?: string;
  // Added prescriptionImage to support pharmacy orders with uploaded images
  prescriptionImage?: string;
  paymentMethod: PaymentMethod;
  requestedVehicleType: VehicleType;
  transactionId?: string;
  rating?: number;
  feedback?: string;
  foodItems?: CartItem[];
  restaurantId?: string;
  restaurantName?: string;
}

export interface User {
  id: string;
  email: string;
  phone: string;
  name: string;
  role: UserRole;
  status: UserStatus;
  photoURL?: string;
  vehicleType?: VehicleType;
  operatorId?: string;
  zoneId?: string;
  wallet: {
    balance: number;
    totalEarnings: number;
    withdrawn: number;
  };
  location?: {
    lat: number;
    lng: number;
    updatedAt: number;
  };
}

