const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'PROFILE' | 'ACTIVITY' | 'WALLET'>('NEW');
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [viewingRestaurant, setViewingRestaurant] = useState<Restaurant | null>(null);
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);

  const [pharmacyNotes, setPharmacyNotes] = useState('');
  const [prescriptionPhoto, setPrescriptionPhoto] = useState<string | null>(null);
  const fileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });
    return onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder]);

  const handleCheckoutFood = async (cart: CartItem[]) => {
    if (!viewingRestaurant || !dropoffVillage) return alert('يرجى اختيار مكان التوصيل');
    setIsSubmitting(true);
    try {
      const dist = calculateDistance(viewingRestaurant.lat, viewingRestaurant.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const deliveryPrice = Math.max(Math.round(DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)), DEFAULT_PRICING.minPrice);
      const foodTotal = cart.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);

      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: 'FOOD',
        pickup: { address: viewingRestaurant.name, lat: viewingRestaurant.lat, lng: viewingRestaurant.lng, villageName: viewingRestaurant.address },
        dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'MOTORCYCLE',
        price: deliveryPrice + foodTotal, distance: dist, operatorId: 'op_main', zoneId: 'zone_main',
        paymentMethod: 'CASH', foodItems: cart, restaurantId: viewingRestaurant.id, restaurantName: viewingRestaurant.name
      });
      setViewingRestaurant(null);
    } catch(e) { alert('خطأ فني'); } finally { setIsSubmitting(false); }
  };

  const handlePharmacyOrder = async () => {
    if (!dropoffVillage) return alert('يرجى اختيار مكان التوصيل');
    if (!pharmacyNotes.trim() && !prescriptionPhoto) return alert('يرجى كتابة الطلبات أو إرفاق صورة الروشتة');

    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: 'PHARMACY',
        pickup: { address: 'أقرب صيدلية', lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: 'منطقة الصيدلية' },
        dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'MOTORCYCLE',
        price: DEFAULT_PRICING.minPrice + 10, distance: 1, operatorId: 'op_main', zoneId: 'zone_main',
        paymentMethod: 'CASH', 
        notes: pharmacyNotes, 
        pickupNotes: prescriptionPhoto ? 'صورة الروشتة مرفقة' : 'لا توجد صورة',
        prescriptionImage: prescriptionPhoto 
      });
      setPharmacyNotes('');
      setPrescriptionPhoto(null);
    } catch(e) { alert('فشل إرسال الطلب'); } finally { setIsSubmitting(false); }
  };

  // وظيفة لضغط الصورة لضمان عدم تجاوز حدود Firestore (1MB)
  const handlePrescriptionUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const MAX_WIDTH = 1024; // تصغير العرض لتقليل الحجم
        const scale = MAX_WIDTH / img.width;
        canvas.width = MAX_WIDTH;
        canvas.height = img.height * scale;

        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, canvas.width, canvas.height);

        // استخراج الصورة مضغوطة بصيغة JPEG وبجودة 70%
        const compressedBase64 = canvas.toDataURL('image/jpeg', 0.7);
        setPrescriptionPhoto(compressedBase64);
      };
      img.src = event.target?.result as string;
    };
    reader.readAsDataURL(file);
  };

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone,
        status: OrderStatus.ACCEPTED, acceptedAt: Date.now()
      });
    } catch (e) { alert('فشل قبول العرض'); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />
      {viewingRestaurant && <RestaurantMenu restaurant={viewingRestaurant} onClose={() => setViewingRestaurant(null)} onCheckout={handleCheckoutFood} />}

      <div className="rh-ui-panel no-scrollbar z-[100] translate-y-0 bg-slate-50">
        <div className="bottom-sheet-grabber lg:hidden"></div>
        <div className="p-6 md:p-12 space-y-8 md:space-y-10 pb-32 max-w-2xl mx-auto h-full overflow-y-auto no-scrollbar text-right">
          {!activeOrder ? (
            <>
              <div className="flex items-center justify-between">
                 <div><h2 className="text-3xl md:text-4xl font-black text-slate-950 tracking-tighter">وصـــلــهــا</h2><p className="text-slate-400 font-bold text-[10px] md:text-xs mt-1">توصيل المنوفية الذكي</p></div>
                 <button onClick={() => setAiOpen(true)} className="p-3.5 md:p-4 bg-emerald-50 text-emerald-600 rounded-2xl md:rounded-3xl active:scale-90 shadow-sm border-none"><Bot className="h-6 w-6 md:h-8 md:w-8" /></button>
              </div>
              <div className="grid grid-cols-3 gap-3 md:gap-4">
                  {[
                    { id: 'TAXI', label: 'مشوار', icon: <Bike className="h-6 w-6 md:h-8 md:w-8" /> },
                    { id: 'FOOD', label: 'أكل', icon: <UtensilsCrossed className="h-6 w-6 md:h-8 md:w-8" /> },
                    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill className="h-6 w-6 md:h-8 md:w-8" /> }
                  ].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`py-6 md:py-8 rounded-[1.5rem] md:rounded-[2.5rem] flex flex-col items-center gap-2 md:gap-3 border-4 transition-all ${selectedCategory === cat.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-2xl scale-105' : 'bg-white border-transparent text-slate-400 opacity-60'}`}>
                       {cat.icon} <span className="text-[9px] md:text-[11px] font-black uppercase tracking-widest">{cat.label}</span>
                    </button>
                  ))}
              </div>

              {selectedCategory === 'FOOD' ? (
                <div className="space-y-6 md:space-y-8 animate-in zoom-in">
                   <VillageInput label="التوصيل إلى" helper="أين ستستلم طلبك؟" icon={<MapPin className="h-5 w-5 md:h-6 md:w-6" />} iconBg="bg-rose-500" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} />
                   <div className="grid grid-cols-1 gap-4 md:gap-6">
                      {restaurants.map(rest => (
                        <div key={rest.id} onClick={() => setViewingRestaurant(rest)} className="bg-white p-5 md:p-7 rounded-[2rem] md:rounded-[3.5rem] border border-slate-100 shadow-sm flex flex-row-reverse justify-between items-center hover:border-emerald-500 transition-all cursor-pointer group active:scale-[0.98] transition-all">
                           <div className="flex items-center gap-3 md:gap-5 flex-row-reverse text-right">
                              <div className="w-12 h-12 md:w-16 md:h-16 bg-slate-900 rounded-[1.2rem] md:rounded-[1.8rem] flex items-center justify-center overflow-hidden shadow-lg">
                                 {rest.photoURL ? <img src={rest.photoURL} className="w-full h-full object-cover" /> : <UtensilsCrossed className="h-6 w-6 md:h-8 md:w-8 text-emerald-400" />}
                              </div>
                              <div><h4 className="text-lg md:text-xl font-black text-slate-800 leading-tight">{rest.name}</h4><p className="text-[9px] md:text-xs font-bold text-slate-400 uppercase tracking-tighter">{rest.category}</p></div>
                           </div>
                           <ChevronRight className="h-5 w-5 md:h-6 md:w-6 text-slate-300 rotate-180 group-hover:text-emerald-500 transition-colors" />
                        </div>
                      ))}
                   </div>
                </div>
              ) : selectedCategory === 'PHARMACY' ? (
                <div className="space-y-6 md:space-y-8 animate-in zoom-in">
                   <div className="bg-sky-50 border-2 border-sky-100 p-6 md:p-8 rounded-[2rem] md:rounded-[3rem] text-center space-y-2 md:space-y-3">
                      <Pill className="h-10 w-10 md:h-12 md:w-12 text-sky-600 mx-auto" />
                      <h3 className="text-lg md:text-xl font-black text-sky-900">طلب أدوية صيدلية</h3>
                      <p className="text-[10px] md:text-xs font-bold text-sky-600">اكتب طلباتك أو ارفع صورة الروشتة</p>
                   </div>

                   <VillageInput label="مكان التوصيل" helper="أين ستستلم الدواء؟" icon={<MapPin className="h-5 w-5 md:h-6 md:w-6" />} iconBg="bg-sky-600" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} />

                   <div className="space-y-3 md:space-y-4">
                      <div className="flex items-center justify-between px-2"><label className="label-strong">طلبات الصيدلية</label><ClipboardList className="h-4 w-4 text-slate-300" /></div>
                      <textarea value={pharmacyNotes} onChange={e => setPharmacyNotes(e.target.value)} placeholder="اكتب أسماء الأدوية..." dir="rtl" className="w-full bg-white border-2 border-slate-100 rounded-[1.5rem] md:rounded-[2rem] p-5 md:p-6 text-sm font-bold outline-none focus:border-sky-500 min-h-[100px] md:min-h-[120px] transition-all shadow-sm" />
                   </div>

                   <div className="space-y-3 md:space-y-4">
                      <div className="flex items-center justify-between px-2"><label className="label-strong">صورة الروشتة (اختياري)</label><Camera className="h-4 w-4 text-slate-300" /></div>
                      <div onClick={() => fileRef.current?.click()} className="w-full h-28 md:h-32 bg-white border-2 border-dashed border-slate-200 rounded-[1.5rem] md:rounded-[2rem] flex flex-col items-center justify-center cursor-pointer hover:border-sky-400 transition-all overflow-hidden relative">
                         {prescriptionPhoto ? <img src={prescriptionPhoto} className="w-full h-full object-cover" /> : <><Plus className="h-6 w-6 md:h-8 md:w-8 text-slate-300 mb-1" /><span className="text-[9px] md:text-[10px] font-black text-slate-400 uppercase">ارفق الصورة</span></>}
                         <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={handlePrescriptionUpload} />
                      </div>
                   </div>

                   <button onClick={handlePharmacyOrder} disabled={isSubmitting} className="w-full bg-sky-600 text-white py-6 md:py-8 rounded-[2rem] md:rounded-[3rem] font-black text-lg md:text-xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3 md:gap-4">
                      {isSubmitting ? <Loader2 className="animate-spin h-6 w-6" /> : <>إرسال طلب الصيدلية <FileText className="h-5 w-5 md:h-6 md:w-6" /></>}
                   </button>
                </div>
              ) : (
                <div className="space-y-6 md:space-y-8 animate-in slide-in-from-right">
                   <VillageInput label="نقطة الانطلاق" helper="موقع استلامك" icon={<MapPin className="h-5 w-5 md:h-6 md:w-6" />} iconBg="bg-emerald-500" selectedVillage={pickupVillage} onSelect={setPickupVillage} />
                   <VillageInput label="وجهة الوصول" helper="الوجهة النهائية" icon={<Check className="h-5 w-5 md:h-6 md:w-6" />} iconBg="bg-rose-500" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} />
                   <button onClick={async () => {
                     if(!pickupVillage || !dropoffVillage) return;
                     setIsSubmitting(true);
                     try {
                        const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
                        const price = Math.max(Math.round(DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)), DEFAULT_PRICING.minPrice);
                        await addDoc(collection(db, "orders"), {
                           customerId: user.id, customerPhone: user.phone, category: 'TAXI',
                           pickup: { address: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng, villageName: pickupVillage.name },
                           dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
                           status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'TOKTOK',
                           price, distance: dist, operatorId: 'op_main', zoneId: 'zone_main', paymentMethod: 'CASH'
                        });
                     } catch(e) { alert('خطأ'); } finally { setIsSubmitting(false); }
                   }} disabled={!pickupVillage || !dropoffVillage || isSubmitting} className="w-full bg-slate-950 text-white py-6 md:py-8 rounded-[2rem] md:rounded-[3rem] font-black text-xl md:text-2xl shadow-2xl active:scale-95 transition-all">
                      {isSubmitting ? <Loader2 className="animate-spin h-8 w-8" /> : 'اطلب الآن'}
                   </button>
                </div>
              )}
            </>
          ) : (
            <div className="space-y-8 md:space-y-12">
               {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                 <div className="animate-in zoom-in space-y-8 md:space-y-12 text-center">
                    <Navigation2 className="h-16 w-16 md:h-24 md:w-24 text-emerald-600 animate-pulse mx-auto" />
                    <h2 className="text-2xl md:text-3xl font-black text-slate-950 tracking-tighter">جاري جلب كباتن متاحين...</h2>
                    <div className="space-y-4 md:space-y-6">
                       {incomingOffers.map(offer => (
                         <div key={offer.id} className="bg-white p-6 md:p-8 rounded-[2rem] md:rounded-[3rem] border-4 border-slate-50 shadow-xl flex justify-between items-center animate-in slide-in-from-bottom">
                            <div className="text-center">
                               <p className="text-2xl md:text-3xl font-black text-emerald-700">{offer.price} <span className="text-[10px]">ج.م</span></p>
                               <button onClick={() => handleAcceptOffer(offer)} className="bg-emerald-600 text-white px-6 md:px-8 py-2 rounded-xl md:rounded-2xl font-black text-[10px] md:text-xs shadow-lg active:scale-90 transition-all">قبول</button>
                            </div>
                            <div className="flex items-center gap-3 md:gap-5 flex-row-reverse text-right">
                               <div className="w-12 h-12 md:w-14 md:h-14 bg-slate-900 text-emerald-400 rounded-xl md:rounded-2xl flex items-center justify-center font-black">{(offer.driverName || 'ك')[0]}</div>
                               <div><p className="font-black text-slate-900 text-base md:text-lg">{offer.driverName}</p><div className="flex items-center gap-1.5 md:gap-2 text-amber-500 font-black text-[10px] md:text-xs">{offer.driverRating} <Star className="h-3 w-3 fill-amber-400" /></div></div>
                            </div>
                         </div>
                       ))}
                    </div>
                    <button onClick={() => updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED })} className="text-rose-500 font-black text-[10px] md:text-xs uppercase tracking-widest">إلغاء الطلب</button>
                 </div>
               ) : (
                 <div className="animate-in zoom-in space-y-8 md:space-y-12 text-center">
                    <div className="bg-emerald-600 p-6 md:p-8 rounded-[2.5rem] md:rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl">
                       <div className="text-right"><p className="text-[10px] font-black opacity-60 uppercase mb-1 md:mb-2">تتبع الطلب</p><h3 className="text-xl md:text-2xl font-black">الكابتن في طريقه إليك</h3></div>
                       <Navigation2 className="h-6 w-6 md:h-8 md:w-8 animate-bounce" />
                    </div>
                    <div className="flex flex-col items-center gap-4 md:gap-6">
                       <div className="w-24 h-24 md:w-32 md:h-32 bg-slate-100 rounded-[2rem] md:rounded-[3rem] flex items-center justify-center border-4 md:border-8 border-white shadow-2xl overflow-hidden font-black text-3xl md:text-4xl text-slate-300">{(activeOrder.driverName || 'ك')[0]}</div>
                       <h4 className="text-2xl md:text-3xl font-black text-slate-950 tracking-tight">{activeOrder.driverName}</h4>
                    </div>
                    <div className="grid grid-cols-2 gap-3 md:gap-5">
                       <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-900 text-white py-6 md:py-8 rounded-[1.8rem] md:rounded-[2.5rem] font-black text-md md:text-lg flex items-center justify-center gap-3 md:gap-4 shadow-2xl active:scale-95 transition-all"><PhoneCall className="h-6 w-6 md:h-7 md:w-7" /> اتصال</a>
                       <button onClick={() => setShowChat(true)} className="bg-white border-4 border-slate-100 text-slate-900 py-6 md:py-8 rounded-[1.8rem] md:rounded-[2.5rem] font-black text-md md:text-lg flex items-center justify-center gap-3 md:gap-4 active:scale-95 transition-all relative"><MessageCircle className="h-6 w-6 md:h-7 md:w-7" /> محادثة</button>
                    </div>
                 </div>
               )}
            </div>
          )}
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-2xl border-t border-slate-100 px-6 md:px-10 py-4 md:py-6 flex justify-around items-center z-[150] shadow-2xl flex-row-reverse">
         {[
           {id: 'NEW', icon: <Plus className="h-6 w-6 md:h-7 md:w-7" />, label: 'طلب'},
           {id: 'ACTIVITY', icon: <History className="h-6 w-6 md:h-7 md:w-7" />, label: 'نشاطي'},
           {id: 'PROFILE', icon: <UserIcon className="h-6 w-6 md:h-7 md:w-7" />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-1.5 md:gap-2 transition-all ${activeView === tab.id ? 'text-emerald-600 scale-110 md:scale-125' : 'text-slate-300'}`}>
              <div className={`p-2.5 md:p-3.5 rounded-xl md:rounded-2xl ${activeView === tab.id ? 'bg-emerald-50 shadow-inner' : ''}`}>{tab.icon}</div>
              <span className="text-[8px] md:text-[10px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;

import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order, OrderCategory } from '../types';
import { OrderStatus } from '../types';
import { MENOFIA_DATA } from '../config/constants';

// Utils
import { stripFirestore } from '../utils';

// Icons
import { 
  Bike, MapPin, Loader2, Power, 
  MessageCircle, History, X,
  PhoneCall, Map as MapIcon, User as UserIcon, Home, 
  ShieldAlert, StickyNote, Coffee, Pill, Bot, Zap, Car,
  Plus, Minus, Crosshair, Check, DollarSign, Building2,
  Camera, Eye, ZoomIn, Download, AlertTriangle
} from 'lucide-react';

// Services
import { db } from '../services/firebase';
import { 
  collection, query, where, onSnapshot, updateDoc, 
  doc, addDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Components
import ChatView from '../components/ChatView';
import ActivityView from './ActivityView';
import ProfileView from './ProfileView';

// Leaflet Global Access
declare var L: any;

const PrescriptionModal: React.FC<{ url: string, onClose: () => void }> = ({ url, onClose }) => {
  return (
    <div className="fixed inset-0 z-[12000] bg-black/95 backdrop-blur-3xl flex flex-col animate-in fade-in duration-300">
      <div className="p-8 flex justify-between items-center text-white border-b border-white/5 relative z-10">
        <button onClick={() => {
          const link = document.createElement('a');
          link.href = url;
          link.download = 'prescription.png';
          link.click();
        }} className="p-4 bg-emerald-600 rounded-2xl flex items-center gap-2 font-black text-xs shadow-lg active:scale-90 transition-all">
          <Download className="h-5 w-5" /> حفظ الصورة
        </button>
        <button onClick={onClose} className="p-4 bg-white/10 rounded-2xl flex items-center gap-2 font-black text-xs hover:bg-white/20 active:scale-90 transition-all">
          إغلاق <X className="h-5 w-5" />
        </button>
      </div>
      <div className="flex-1 overflow-auto p-4 flex items-center justify-center no-scrollbar">
         <img 
           src={url} 
           className="max-w-full max-h-full object-contain shadow-2xl rounded-lg animate-reveal" 
           alt="Prescription"
         />
      </div>
    </div>
  );
};

const CourierDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'HOME' | 'MAP' | 'ACTIVITY' | 'PROFILE'>('HOME');
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [isOnline, setIsOnline] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showOfferInput, setShowOfferInput] = useState<string | null>(null);
  const [offerPrice, setOfferPrice] = useState<string>('');
  const [showChat, setShowChat] = useState(false);
  const [showPrescriptionModal, setShowPrescriptionModal] = useState<string | null>(null);

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstance = useRef<any>(null);
  const watchId = useRef<number | null>(null);
  const driverMarker = useRef<any>(null);

  useEffect(() => {
    if (mapContainerRef.current && !mapInstance.current) {
      mapInstance.current = L.map(mapContainerRef.current, { zoomControl: false, attributionControl: false }).setView([30.556, 31.008], 11);
      L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png').addTo(mapInstance.current);
    }
  }, []);

  useEffect(() => {
    if (isOnline) {
      if ("geolocation" in navigator) {
        watchId.current = navigator.geolocation.watchPosition(
          (pos) => {
            const { latitude, longitude } = pos.coords;
            updateDoc(doc(db, "users", user.id), {
              location: { lat: latitude, lng: longitude, updatedAt: Date.now() }
            });
            if (mapInstance.current && driverMarker.current) {
               driverMarker.current.setLatLng([latitude, longitude]);
            }
          },
          null, { enableHighAccuracy: true }
        );
      }
    }
    return () => { if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current); };
  }, [isOnline, user.id]);

  useEffect(() => {
    if (!isOnline || user.status !== 'APPROVED') return;
    const unsubAvailable = onSnapshot(query(collection(db, "orders"), where("status", "==", OrderStatus.WAITING_FOR_OFFERS)), (snapshot) => {
      setAvailableOrders(snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[]);
    });
    const unsubActive = onSnapshot(query(collection(db, "orders"), where("driverId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
    return () => { unsubAvailable(); unsubActive(); };
  }, [isOnline, user.id, user.status]);

  const getDistrictName = (villageName?: string) => {
    return MENOFIA_DATA.find(d => d.villages.some(v => v.name === villageName))?.name || 'المنوفية';
  };

  const handleWhatsAppCustomer = (phone: string) => {
    const msg = `مرحباً، أنا كابتن "وصـــلــهــا"، أنا في طريقي إليك الآن.`;
    window.open(`https://wa.me/2${phone}?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const handleSendOffer = async (orderId: string) => {
    const price = parseFloat(offerPrice);
    if (!price || price <= 0 || isSubmitting) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "offers"), {
        orderId: orderId, driverId: user.id, driverName: user.name, driverPhone: user.phone,
        driverRating: 5.0, vehicleType: user.vehicleType || 'TOKTOK', price: price, createdAt: Date.now()
      });
      setShowOfferInput(null);
      setOfferPrice('');
    } catch (e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  const updateOrderStatus = async (status: OrderStatus) => {
    if (!activeOrder || isSubmitting) return;
    setIsSubmitting(true);
    try {
      const updates: any = { status };
      if (status === OrderStatus.DELIVERED) updates.deliveredAt = Date.now();
      await updateDoc(doc(db, "orders", activeOrder.id), updates);
    } catch (e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  if (user.status !== 'APPROVED') {
     return <div className="p-20 text-center font-black">حسابك قيد المراجعة في المنوفية...</div>;
  }

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('HOME')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onBack={() => setActiveView('HOME')} onUpdate={() => {}} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50">
      {/* Modal لعرص الروشتة بوضوح */}
      {showPrescriptionModal && <PrescriptionModal url={showPrescriptionModal} onClose={() => setShowPrescriptionModal(null)} />}

      <div ref={mapContainerRef} className={`rh-map-view absolute inset-0 z-0 transition-opacity duration-500 ${activeView === 'MAP' ? 'opacity-100 block' : 'opacity-0 hidden'}`}></div>

      <div className={`rh-ui-panel no-scrollbar px-6 space-y-8 pb-32 pt-8 animate-in fade-in overflow-y-auto z-[100] ${activeView === 'MAP' ? 'translate-y-full opacity-0' : 'translate-y-0 opacity-100 bg-slate-50'}`}>
        <div className="bottom-sheet-grabber lg:hidden"></div>
        <div className="max-w-2xl mx-auto space-y-8">
            <div className={`p-10 rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl transition-all duration-700 ${isOnline ? 'bg-emerald-600' : 'bg-slate-950'}`}>
               <div>
                  <h2 className="text-3xl font-black tracking-tighter">{isOnline ? 'نشط في المنوفية' : 'متوقف'}</h2>
                  <p className="text-[10px] font-black opacity-60 mt-2 uppercase tracking-widest">تغطية كاملة للمحافظة</p>
               </div>
               <button onClick={() => setIsOnline(!isOnline)} className={`p-6 rounded-[2.5rem] shadow-2xl active:scale-90 transition-all ${isOnline ? 'bg-white text-emerald-600' : 'bg-emerald-500 text-white'}`}><Power className="h-10 w-10" /></button>
            </div>

            {activeOrder ? (
               <div className="bg-white rounded-[4rem] shadow-2xl p-10 space-y-10 animate-in zoom-in border-t-8 border-t-emerald-500">
                  <div className="flex justify-between items-center">
                     <span className="bg-emerald-100 text-emerald-700 px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-widest">{activeOrder.status}</span>
                     <p className="text-5xl font-black text-slate-950">{activeOrder.price} <span className="text-lg opacity-30 font-bold uppercase">ج.م</span></p>
                  </div>

                  {/* عرض تفاصيل الروشتة إذا كان طلب صيدلية */}
                  {activeOrder.category === 'PHARMACY' && (
                    <div className="space-y-4 animate-reveal" style={{animationDelay: '0.2s'}}>
                       <div className="bg-sky-50 border-2 border-sky-100 p-8 rounded-[3rem] text-right space-y-4 shadow-inner">
                          <div className="flex items-center justify-between">
                            <p className="text-[10px] font-black text-sky-600 uppercase tracking-[0.2em]">طلب صيدلية مرفق</p>
                            <Pill className="h-5 w-5 text-sky-400" />
                          </div>

                          {activeOrder.notes && (
                            <div className="bg-white/80 p-4 rounded-2xl border border-sky-100">
                               <p className="text-xs font-bold text-slate-700">{activeOrder.notes}</p>
                            </div>
                          )}

                          {activeOrder.prescriptionImage ? (
                            <div className="relative group">
                               <div onClick={() => setShowPrescriptionModal(activeOrder.prescriptionImage!)} className="w-full h-56 bg-white rounded-[2rem] overflow-hidden border-2 border-dashed border-sky-200 cursor-pointer transition-all hover:border-sky-400 active:scale-95 shadow-sm">
                                  <img src={activeOrder.prescriptionImage} className="w-full h-full object-cover transition-transform group-hover:scale-110 duration-700" alt="Prescription" />
                                  <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                                     <div className="bg-white/90 p-4 rounded-2xl shadow-xl flex items-center gap-2 font-black text-xs text-sky-600">
                                        <ZoomIn className="h-5 w-5" /> اضغط للتكبير
                                     </div>
                                  </div>
                               </div>
                            </div>
                          ) : activeOrder.pickupNotes === 'صورة الروشتة مرفقة' && (
                            <div className="p-6 bg-rose-50 border-2 border-rose-100 rounded-2xl text-center space-y-2">
                               <AlertTriangle className="h-8 w-8 text-rose-500 mx-auto" />
                               <p className="text-xs font-black text-rose-600">عذراً، فشل تحميل صورة الروشتة</p>
                               <p className="text-[9px] font-bold text-slate-400">قد يكون حجم الصورة كبيراً جداً أو هناك مشكلة في الإنترنت</p>
                            </div>
                          )}
                       </div>
                    </div>
                  )}

                  <div className="space-y-8 text-right">
                     <div className="flex gap-6 items-start">
                        <div className="bg-slate-50 p-5 rounded-3xl text-emerald-600 shrink-0"><MapPin className="h-8 w-8" /></div>
                        <div className="flex-1">
                           <p className="helper-text uppercase mb-2 tracking-widest">مسار المشوار</p>
                           <p className="font-black text-2xl text-slate-950 leading-tight mb-2">
                             مركز {getDistrictName(activeOrder.pickup?.villageName)} ({activeOrder.pickup?.villageName})
                             <br />
                             ← مركز {getDistrictName(activeOrder.dropoff?.villageName)} ({activeOrder.dropoff?.villageName})
                           </p>
                        </div>
                     </div>
                  </div>
                  <div className="grid grid-cols-2 md:grid-cols-3 gap-4 pt-4">
                     <a href={`tel:${activeOrder.customerPhone}`} className="bg-slate-950 text-white py-6 rounded-[2rem] font-black text-lg flex items-center justify-center gap-3 shadow-xl active:scale-95 transition-all"><PhoneCall className="h-7 w-7" /></a>
                     <button onClick={() => handleWhatsAppCustomer(activeOrder.customerPhone)} className="bg-[#25D366] text-white py-6 rounded-[2rem] font-black text-lg flex items-center justify-center gap-3 shadow-xl active:scale-95 transition-all"><MessageCircle className="h-7 w-7" /></button>
