const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [connectionError, setConnectionError] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [showSupport, setShowSupport] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);
  const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);

  useEffect(() => {
    const unsubscribeAuth = onAuthStateChanged(auth, async (fbUser) => {
      try {
        if (fbUser) {
          await fetchUserData(fbUser.uid);
        } else {
          setUser(null);
          setLoading(false);
        }
      } catch (error) {
        console.error("Auth error:", error);
        setLoading(false);
      }
    });
    return () => unsubscribeAuth();
  }, []);

  const fetchUserData = async (uid: string) => {
    try {
      const userSnap = await getDoc(doc(db, "users", uid));
      if (userSnap.exists()) {
        const data = stripFirestore(userSnap.data()) as User;
        setUser(data);

        const q = query(collection(db, "notifications"), where("userId", "in", [data.id, "ALL", data.role]));
        const unsubscribeNotifications = onSnapshot(q, (snap) => {
          const unread = snap.docs.filter(d => !d.data().read).length;
          setUnreadCount(unread);
        });
        return () => unsubscribeNotifications();
      } else {
        setUser(null);
      }
    } catch (error) {
      console.error("Error fetching user data:", error);
      if (!navigator.onLine) setConnectionError(true);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    signOut(auth);
    setIsLogoutModalOpen(false);
  };

  if (loading) return (
    <div className="min-h-screen bg-[#10b981] flex flex-col items-center justify-center p-6 text-center">
      <div className="bg-white/20 p-8 md:p-12 rounded-[4rem] md:rounded-[5rem] backdrop-blur-3xl mb-8 md:mb-12 border border-white/30 shadow-2xl animate-pulse">
         <img src={APP_LOGO_ICON} alt="Loading..." className="h-20 w-20 md:h-32 md:w-32 object-contain" />
      </div>
      <h2 className="text-white font-black text-4xl md:text-5xl tracking-tighter mb-4">وصـــلــهــا</h2>
      <div className="flex items-center gap-3 bg-black/10 px-6 py-2.5 rounded-full backdrop-blur-md border border-white/10">
        <Loader2 className="h-4 w-4 text-white animate-spin" />
        <p className="text-white/80 font-bold text-[9px] uppercase tracking-widest">جاري التحميل...</p>
      </div>
    </div>
  );

  if (connectionError) return (
    <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-10 text-center">
       <WifiOff className="h-16 w-16 text-rose-500 mb-6" />
       <h2 className="text-xl font-black text-slate-800 mb-4">لا يوجد اتصال بالإنترنت</h2>
       <button onClick={() => window.location.reload()} className="bg-[#10b981] text-white px-8 py-4 rounded-[1.8rem] font-black shadow-xl flex items-center gap-3 active:scale-95"><RefreshCcw className="h-4 w-4" /> تحديث</button>
    </div>
  );

  if (!user) return <Login onLogin={(u) => setUser(stripFirestore(u))} />;

  const getDashboard = () => {
    if (showNotifications) return <NotificationsView user={user} onBack={() => setShowNotifications(false)} />;
    if (showSupport) return <SupportView user={user} onBack={() => setShowSupport(false)} />;

    switch (user.role) {
      case 'ADMIN': return <SuperAdminDashboard user={user} />;
      case 'OPERATOR': return <OperatorDashboard user={user} />;
      case 'DRIVER': return <CourierDashboard user={user} />;
      case 'CUSTOMER': return <CustomerDashboard user={user} />;
      default: return <div className="p-20 text-center font-black">الحساب غير مفعل</div>;
    }
  };

  return (
    <HashRouter>
      <LogoutModal 
        isOpen={isLogoutModalOpen} 
        onConfirm={handleLogout} 
        onCancel={() => setIsLogoutModalOpen(false)} 
      />
      <div className="app-container">
        <header className="bg-white/95 backdrop-blur-md border-b border-slate-100 sticky top-0 z-[110] px-4 md:px-6 h-[70px] md:h-[90px] flex items-center shadow-sm">
          <div className="max-w-7xl mx-auto w-full flex items-center justify-between">
            <Link to="/" onClick={() => { setShowNotifications(false); setShowSupport(false); }} className="flex items-center gap-3 md:gap-5">
              <div className="bg-[#10b981] p-2 md:p-3 rounded-2xl md:rounded-[1.8rem] shadow-lg border-2 md:border-4 border-emerald-50">
                <img src={APP_LOGO_ICON} alt="Logo" className="h-6 w-6 md:h-9 md:w-9" />
              </div>
              <div className="flex flex-col">
                <h1 className="font-black text-lg md:text-2xl text-slate-800 tracking-tighter leading-none mb-0.5 md:mb-1">وصـــلــهــا</h1>
                <span className="text-[7px] md:text-[9px] font-black text-slate-300 uppercase tracking-widest">المنوفية</span>
              </div>
            </Link>
            <div className="flex items-center gap-1.5 md:gap-4">
              <button onClick={() => setShowSupport(true)} className="p-3 md:p-4 bg-slate-50 text-slate-400 rounded-xl md:rounded-2xl border border-slate-100 transition-all active:scale-90 hover:text-emerald-600">
                <MessageCircle className="h-5 w-5 md:h-6 md:w-6" />
              </button>
              <button onClick={() => setShowNotifications(true)} className={`p-3 md:p-4 bg-slate-50 text-slate-400 rounded-xl md:rounded-2xl relative border border-slate-100 transition-all active:scale-90 hover:text-emerald-600`}>
                <Bell className="h-5 w-5 md:h-6 md:w-6" />
                {unreadCount > 0 && (
                  <span className="absolute -top-1 -right-1 bg-rose-500 text-white w-5 h-5 md:w-6 md:h-6 rounded-full text-[8px] md:text-[10px] flex items-center justify-center border-2 border-white font-black">{unreadCount}</span>
                )}
              </button>
              <button onClick={() => setIsLogoutModalOpen(true)} className="p-3 md:p-4 bg-rose-50 text-rose-500 rounded-xl md:rounded-2xl border border-rose-100 transition-all active:scale-90 hover:bg-rose-100">
                <LogOut className="h-5 w-5 md:h-6 md:w-6 rotate-180" />
              </button>
            </div>
          </div>
        </header>
        <main className="main-content">
          <Routes>
            <Route path="/" element={getDashboard()} />
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </main>
      </div>
    </HashRouter>
  );
};

