        <div className="fixed inset-0 z-[1200] bg-slate-950/60 backdrop-blur-md flex items-center justify-center p-6 animate-in fade-in">
           <div className="bg-white w-full max-w-sm rounded-[3rem] p-10 text-center space-y-6 shadow-2xl animate-in zoom-in border border-slate-100">
              <div className="bg-rose-50 w-20 h-20 rounded-[2.5rem] flex items-center justify-center mx-auto text-rose-500">
                <LogOut className="h-10 w-10 rotate-180" />
              </div>
              <div className="space-y-2">
                 <h3 className="text-2xl font-black text-slate-900 tracking-tight">تأكيد الخروج</h3>
                 <p className="text-sm font-bold text-slate-400">هل تريد حقاً تسجيل الخروج من حسابك؟</p>
              </div>
              <div className="flex flex-col gap-3 pt-4">
                 <button onClick={handleLogout} className="w-full bg-rose-500 text-white py-5 rounded-[1.8rem] font-black shadow-xl active:scale-95 transition-all">خروج</button>
                 <button onClick={() => setShowLogoutConfirm(false)} className="w-full bg-slate-50 text-slate-400 py-5 rounded-[1.8rem] font-black active:scale-95 transition-all">تراجع</button>
              </div>
           </div>
        </div>
      )}

      <div className="flex items-center justify-between px-2">
        <div className="text-right">
           <h2 className="text-3xl font-black text-slate-900 tracking-tighter">حسابي الشخصي</h2>
           <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">عضوية وصلها المميزة</p>
        </div>
        <button onClick={onBack} className="p-3.5 bg-white border border-slate-100 rounded-[1.5rem] shadow-sm active:scale-90 transition-all"><ChevronRight /></button>
      </div>

      <div className="bg-[#2D9469] rounded-[4rem] p-12 text-white text-center shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full blur-[100px] -mr-32 -mt-32"></div>

        <div className="relative inline-block group">
          <div className="w-40 h-40 bg-white/20 backdrop-blur-xl rounded-[3.5rem] mx-auto flex items-center justify-center mb-8 overflow-hidden border-8 border-white/10 shadow-2xl relative transition-transform hover:scale-105 duration-500">
