const MassActions: React.FC<{ users: User[] }> = ({ users }) => {
  const [amount, setAmount] = useState<string>('');
  const [loading, setLoading] = useState(false);

  const handleBulkCredit = async (role: UserRole) => {
    const num = parseFloat(amount);
    if (!num || isNaN(num)) return alert('المبلغ غير صحيح');
    if (!confirm(`سيتم إضافة ${num} ج.م لـ ${users.filter(u => u.role === role).length} مستخدم. هل أنت متأكد؟`)) return;

    setLoading(true);
    try {
      const batch = writeBatch(db);
      users.filter(u => u.role === role).forEach(u => {
        batch.update(doc(db, "users", u.id), { "wallet.balance": (u.wallet?.balance || 0) + num });
      });
      await batch.commit();
      setAmount('');
      alert('تم التنفيذ بنجاح!');
    } catch (e) { alert('فشل الإجراء'); } finally { setLoading(false); }
  };

  return (
    <div className="bg-slate-900 rounded-[3.5rem] p-10 text-white space-y-8 shadow-2xl relative overflow-hidden animate-reveal">
       <div className="absolute top-0 right-0 w-64 h-64 bg-emerald-500/10 blur-[100px]"></div>
       <div className="flex flex-col md:flex-row justify-between items-center gap-6 relative z-10">
          <div className="text-right">
             <h3 className="text-2xl font-black flex items-center gap-3 justify-end">إجراءات جماعية <Zap className="text-emerald-400 fill-emerald-400 animate-pulse" /></h3>
             <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">توزيع أرصدة مجمعة في ثوانٍ</p>
          </div>
          <div className="flex gap-4 w-full md:w-auto">
             <div className="relative flex-1 md:w-48">
                <input type="number" value={amount} onChange={e => setAmount(e.target.value)} placeholder="المبلغ..." className="w-full bg-white/5 border border-white/10 rounded-2xl p-5 font-black text-center outline-none focus:border-emerald-500 transition-all" />
             </div>
             <div className="flex gap-2">
                <button onClick={() => handleBulkCredit('DRIVER')} disabled={loading} className="bg-emerald-600 px-6 py-4 rounded-2xl font-black text-[10px] uppercase shadow-lg active:scale-95 transition-all">للكباتن</button>
                <button onClick={() => handleBulkCredit('CUSTOMER')} disabled={loading} className="bg-white/10 px-6 py-4 rounded-2xl font-black text-[10px] uppercase hover:bg-white/20 active:scale-95 transition-all">للعملاء</button>
             </div>
          </div>
       </div>
    </div>
  );
};

