const ManualAssignModal: React.FC<{ order: Order, onClose: () => void }> = ({ order, onClose }) => {
  const [drivers, setDrivers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const q = query(collection(db, "users"), where("role", "==", "DRIVER"), where("status", "==", "APPROVED"), limit(30));
    getDocs(q).then(snap => {
      setDrivers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as User[]);
      setLoading(false);
    }).catch(() => setLoading(false));
  }, []);

  const assignDriver = async (driver: User) => {
    try {
      await updateDoc(doc(db, "orders", order.id), {
        driverId: driver.id,
        driverName: driver.name || 'كابتن',
        driverPhone: driver.phone || '',
        status: OrderStatus.ACCEPTED,
        acceptedAt: Date.now()
      });
      onClose();
    } catch (e) { alert('فشل التوجيه'); }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-xl z-[11000] flex items-center justify-center p-4 animate-in fade-in">
      <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-10 flex flex-col max-h-[80vh] shadow-2xl">
        <div className="flex justify-between items-center mb-8 px-2">
           <h3 className="text-2xl font-black text-slate-800 tracking-tight text-right w-full">توجيه كابتن يدوياً</h3>
           <button onClick={onClose} className="p-3 bg-slate-100 rounded-2xl hover:bg-slate-200 transition-all"><X className="h-5 w-5" /></button>
        </div>
        <div className="flex-1 overflow-y-auto no-scrollbar space-y-3 px-2">
          {loading ? (
             <div className="py-20 flex justify-center"><Loader2 className="h-10 w-10 animate-spin text-emerald-500" /></div>
          ) : drivers.map(d => (
            <div key={d.id} onClick={() => assignDriver(d)} className="p-6 bg-slate-50 rounded-[2.5rem] flex justify-between items-center hover:bg-emerald-50 hover:border-emerald-200 border-2 border-transparent transition-all cursor-pointer group">
              <div className="flex items-center gap-4">
                 <div className="w-14 h-14 bg-white rounded-2xl flex items-center justify-center font-black text-slate-300 text-xl group-hover:bg-emerald-500 group-hover:text-white transition-all shadow-sm">
                    {(d.name || 'ك')[0]}
                 </div>
                 <div className="text-right">
                    <p className="font-black text-slate-800 text-lg">{d.name}</p>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{d.vehicleType || 'توكتوك'}</p>
                 </div>
              </div>
              <ChevronRight className="h-6 w-6 text-slate-300 group-hover:text-emerald-500 transition-colors" />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

