/**
 * مكون للعمليات الجماعية على المستخدمين
 */
const MassActions: React.FC<{ users: User[] }> = ({ users }) => {
  const pendingDrivers = users.filter(u => u.role === 'DRIVER' && u.status === 'PENDING_APPROVAL');

  const approveAll = async () => {
    if (pendingDrivers.length === 0) return;
    if (!confirm(`هل أنت متأكد من تفعيل جميع الكباتن (${pendingDrivers.length}) في المنوفية؟`)) return;

    const batch = writeBatch(db);
    pendingDrivers.forEach(u => {
      batch.update(doc(db, "users", u.id), { status: 'APPROVED' });
    });

    try {
      await batch.commit();
      alert('تم تفعيل جميع الكباتن المعلقين بنجاح');
    } catch (e) {
      alert('فشل تنفيذ العملية الجماعية');
    }
  };

  return (
    <div className="bg-white p-8 rounded-[3.5rem] border border-slate-100 shadow-sm flex flex-col md:flex-row-reverse justify-between items-center gap-6">
       <div className="text-right">
          <h4 className="text-lg font-black text-slate-800">إجراءات سريعة</h4>
          <p className="text-xs font-bold text-slate-400">إدارة الكباتن والطلبات المعلقة دفعة واحدة</p>
       </div>
       <button 
         onClick={approveAll}
         disabled={pendingDrivers.length === 0}
         className="bg-emerald-600 text-white px-10 py-5 rounded-[1.8rem] font-black text-xs shadow-xl shadow-emerald-100 active:scale-95 disabled:opacity-20 transition-all flex items-center gap-3"
       >
         <CheckCircle className="h-4 w-4" /> تفعيل جميع الكباتن المعلقين ({pendingDrivers.length})
       </button>
    </div>
  );
};

const RestaurantEditor: React.FC = () => {
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [loading, setLoading] = useState(false);
  const [restData, setRestData] = useState({ name: '', category: 'مشويات', photoURL: '', menuImageURLs: [] as string[] });
  const [newItem, setNewItem] = useState({ name: '', price: 0, photoURL: '' });
  const [activeRestId, setActiveRestId] = useState<string | null>(null);

  const fileRef = useRef<HTMLInputElement>(null);
  const itemFileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    return onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });
  }, []);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, target: 'PHOTO' | 'ITEM') => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64 = reader.result as string;
      if (target === 'PHOTO') setRestData(prev => ({ ...prev, photoURL: base64 }));
      if (target === 'ITEM') setNewItem(prev => ({ ...prev, photoURL: base64 }));
    };
    reader.readAsDataURL(file);
  };

  const saveRestaurant = async () => {
    if (!restData.name) return;
    setLoading(true);
    try {
      const id = `rest_${Date.now()}`;
      await setDoc(doc(db, "restaurants", id), {
        ...restData, id, menu: [], isOpen: true, address: 'المنوفية', lat: 30.5, lng: 31.0
      });
      setIsAdding(false);
      setRestData({ name: '', category: 'مشويات', photoURL: '', menuImageURLs: [] });
    } catch (e) { alert('خطأ'); } finally { setLoading(false); }
  };

  const addMenuItem = async (rid: string) => {
    if (!newItem.name || newItem.price <= 0) return;
    const rest = restaurants.find(r => r.id === rid);
    if (!rest) return;
    const menu = [...(rest.menu || []), { ...newItem, id: `item_${Date.now()}` }];
    await updateDoc(doc(db, "restaurants", rid), { menu });
    setNewItem({ name: '', price: 0, photoURL: '' });
  };

  return (
    <div className="space-y-8 animate-reveal text-right" dir="rtl">
      <div className="bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-xl">
        <div className="flex justify-between items-center mb-10">
           <h3 className="text-2xl font-black text-slate-900 flex items-center gap-4"><UtensilsCrossed className="text-emerald-500" /> إدارة المطاعم</h3>
           <button onClick={() => setIsAdding(!isAdding)} className="bg-slate-900 text-white px-8 py-4 rounded-2xl font-black text-xs flex items-center gap-3 active:scale-95 transition-all">
              {isAdding ? <X className="h-5 w-5" /> : <PlusCircle className="h-5 w-5" />}
              {isAdding ? 'إلغاء' : 'إضافة مطعم جديد'}
           </button>
        </div>

        {isAdding && (
          <div className="bg-slate-50 p-10 rounded-[3rem] mb-12 border-2 border-emerald-500/10 space-y-8 animate-in zoom-in">
             <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-4">
                   <label className="text-[10px] font-black text-slate-400 uppercase mr-4">صورة الغلاف</label>
                   <div onClick={() => fileRef.current?.click()} className="w-full h-48 bg-white rounded-3xl border-4 border-dashed border-slate-200 flex items-center justify-center cursor-pointer overflow-hidden relative group">
                      {restData.photoURL ? <img src={restData.photoURL} className="w-full h-full object-cover" /> : <Camera className="h-10 w-10 text-slate-300" />}
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center text-white font-black text-xs uppercase tracking-widest transition-opacity">تغيير الصورة</div>
                   </div>
                   <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'PHOTO')} />
                </div>
                <div className="space-y-6">
                   <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 mr-4">اسم المطعم</label>
                      <input value={restData.name} onChange={e => setRestData({...restData, name: e.target.value})} className="w-full bg-white rounded-2xl p-5 font-black outline-none border-2 border-transparent focus:border-emerald-500 transition-all shadow-sm" placeholder="مثلاً: حضرموت المنوفية" />
                   </div>
                   <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 mr-4">التصنيف</label>
                      <input value={restData.category} onChange={e => setRestData({...restData, category: e.target.value})} className="w-full bg-white rounded-2xl p-5 font-black outline-none border-2 border-transparent focus:border-emerald-500 transition-all shadow-sm" placeholder="مشويات، بيتزا، إلخ" />
                   </div>
                   <button onClick={saveRestaurant} disabled={loading} className="w-full bg-emerald-600 text-white py-6 rounded-3xl font-black shadow-2xl active:scale-95 transition-all">
                      {loading ? <Loader2 className="animate-spin mx-auto" /> : 'حفظ المطعم الآن'}
                   </button>
                </div>
             </div>
          </div>
        )}

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
           {restaurants.map(rest => (
             <div key={rest.id} className="bg-slate-50 p-8 rounded-[3rem] border border-slate-100 space-y-8">
                <div className="flex justify-between items-start">
                   <div className="flex items-center gap-6">
                      <div className="w-20 h-20 bg-white rounded-[1.8rem] overflow-hidden shadow-lg border-4 border-white">
                         {rest.photoURL ? <img src={rest.photoURL} className="w-full h-full object-cover" /> : <Building2 className="p-5 text-slate-200" />}
                      </div>
                      <div>
                        <h4 className="font-black text-2xl text-slate-900">{rest.name}</h4>
                        <p className="text-sm font-bold text-emerald-600">{rest.category}</p>
                      </div>
                   </div>
                   <button onClick={async () => { if(confirm('حذف المطعم نهائياً؟')) await deleteDoc(doc(db, "restaurants", rest.id)); }} className="p-4 bg-rose-50 text-rose-500 rounded-2xl hover:bg-rose-500 hover:text-white transition-all"><Trash2 className="h-5 w-5" /></button>
                </div>

                <div className="space-y-4">
                   <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mr-2">منيو الوجبات ({rest.menu?.length || 0})</h5>
                   <div className="grid gap-3">
                      {rest.menu?.map(item => (
                        <div key={item.id} className="bg-white p-4 rounded-2xl flex justify-between items-center group shadow-sm border border-slate-100">
                           <button onClick={async () => {
                             const menu = rest.menu.filter(i => i.id !== item.id);
                             await updateDoc(doc(db, "restaurants", rest.id), { menu });
                           }} className="text-slate-200 hover:text-rose-500 transition-colors p-2"><X className="h-4 w-4" /></button>
                           <div className="flex items-center gap-4">
                              <div className="text-right">
                                <p className="font-black text-sm text-slate-800">{item.name}</p>
                                <p className="text-xs font-bold text-emerald-600">{item.price} ج.م</p>
                              </div>
                              <div className="w-12 h-12 rounded-xl bg-slate-50 overflow-hidden">
                                 {item.photoURL ? <img src={item.photoURL} className="w-full h-full object-cover" /> : <UtensilsCrossed className="p-3 text-slate-200" />}
                              </div>
                           </div>
                        </div>
                      ))}
                   </div>
                   <div className="bg-emerald-50 p-6 rounded-[2rem] border border-emerald-100 flex gap-4">
                      <div onClick={() => { setActiveRestId(rest.id); itemFileRef.current?.click(); }} className="w-16 h-16 bg-white rounded-2xl border-2 border-dashed border-emerald-200 flex items-center justify-center cursor-pointer shrink-0 overflow-hidden">
                         {activeRestId === rest.id && newItem.photoURL ? <img src={newItem.photoURL} className="w-full h-full object-cover" /> : <Camera className="h-6 w-6 text-emerald-300" />}
                      </div>
                      <div className="flex-1 space-y-2">
                         <input value={activeRestId === rest.id ? newItem.name : ''} onChange={e => { setActiveRestId(rest.id); setNewItem({...newItem, name: e.target.value}); }} placeholder="اسم الوجبة..." className="w-full bg-white p-3 rounded-xl text-xs font-bold outline-none" />
                         <div className="flex gap-2">
                            <input type="number" value={activeRestId === rest.id ? (newItem.price || '') : ''} onChange={e => { setActiveRestId(rest.id); setNewItem({...newItem, price: Number(e.target.value)}); }} placeholder="السعر" className="flex-1 bg-white p-3 rounded-xl text-xs font-bold outline-none" />
                            <button onClick={() => addMenuItem(rest.id)} className="bg-emerald-600 text-white px-6 py-2 rounded-xl font-black text-[10px]">إضافة</button>
                         </div>
                      </div>
                      <input type="file" ref={itemFileRef} className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'ITEM')} />
                   </div>
                </div>
             </div>
           ))}
        </div>
      </div>
    </div>
  );
};

const PaymentRequests: React.FC = () => {
  const [requests, setRequests] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const q = query(collection(db, "payment_requests"), where("status", "==", "PENDING"), orderBy("createdAt", "desc"));
    return onSnapshot(q, (snap) => setRequests(snap.docs.map(d => ({ id: d.id, ...d.data() }))));
  }, []);

  const handleApprove = async (req: any) => {
    if (!confirm('هل تم تحويل المبلغ بالفعل؟ سيتم خصم الرصيد من الكابتن وتوثيق العملية.')) return;
    setLoading(true);
    try {
      const batch = writeBatch(db);
      // 1. تحديث حالة الطلب
      batch.update(doc(db, "payment_requests", req.id), { status: 'APPROVED', approvedAt: Date.now() });

      // 2. تحديث رصيد المستخدم
      const userRef = doc(db, "users", req.userId);
      const userSnap = await getDoc(userRef);
      if (userSnap.exists()) {
        const currentBalance = userSnap.data().wallet?.balance || 0;
        const currentWithdrawn = userSnap.data().wallet?.withdrawn || 0;
        batch.update(userRef, { 
          "wallet.balance": currentBalance - req.amount,
          "wallet.withdrawn": currentWithdrawn + req.amount
        });
      }

      // 3. إضافة عملية مالية في السجل
      const transId = `trans_${Date.now()}`;
      batch.set(doc(db, "transactions", transId), {
        userId: req.userId,
        amount: req.amount,
        type: 'DEBIT',
        description: 'سحب أرباح نقداً',
        createdAt: Date.now()
      });

      // 4. إرسال إشعار للمستخدم
      const notifId = `notif_${Date.now()}`;
      batch.set(doc(db, "notifications", notifId), {
        userId: req.userId,
        title: 'تمت عملية السحب بنجاح',
        body: `تمت الموافقة على طلب سحب مبلغ ${req.amount} ج.م من أرباحك.`,
        type: 'SUCCESS',
        createdAt: Date.now(),
        read: false
      });

      await batch.commit();
      alert('تمت الموافقة وتحديث الرصيد بنجاح!');
    } catch (e) { alert('فشل الإجراء'); } finally { setLoading(false); }
  };

  return (
    <div className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-xl space-y-8 animate-reveal text-right" dir="rtl">
       <div className="flex justify-between items-center mb-4 px-4">
          <h3 className="text-2xl font-black text-slate-900 flex items-center gap-4"><Banknote className="text-amber-500" /> طلبات السحب المعلقة</h3>
          <span className="bg-amber-100 text-amber-700 px-6 py-2 rounded-full font-black text-[10px] uppercase tracking-widest">{requests.length} طلب جديد</span>
       </div>

       <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {requests.map(req => (
            <div key={req.id} className="p-8 bg-slate-50 rounded-[3rem] border border-slate-100 flex flex-col gap-6 hover:border-emerald-500 transition-all">
               <div className="flex justify-between items-start">
                  <div className="text-left"><p className="text-3xl font-black text-slate-950">{req.amount} <span className="text-xs opacity-30 font-bold">ج.م</span></p></div>
                  <div className="text-right">
                     <p className="font-black text-lg text-slate-800">{req.userName}</p>
                     <p className="text-xs font-bold text-slate-400" dir="ltr">{req.userPhone}</p>
                  </div>
               </div>
               <div className="flex gap-3">
                  <button onClick={() => handleApprove(req)} disabled={loading} className="flex-[2] bg-emerald-600 text-white py-5 rounded-2xl font-black text-sm shadow-lg active:scale-95 transition-all flex items-center justify-center gap-3">
                     {loading ? <Loader2 className="animate-spin" /> : <><Check className="h-5 w-5" /> موافقة وصرف</>}
                  </button>
                  <button onClick={async () => { if(confirm('رفض الطلب؟')) await updateDoc(doc(db, "payment_requests", req.id), { status: 'REJECTED' }); }} className="flex-1 bg-rose-50 text-rose-500 py-5 rounded-2xl font-black text-sm">رفض</button>
               </div>
            </div>
          ))}
          {requests.length === 0 && (
             <div className="col-span-full py-20 text-center text-slate-300 font-bold bg-white border-4 border-dashed border-slate-50 rounded-[3rem]">
                لا توجد طلبات سحب حالياً
             </div>
          )}
       </div>
    </div>
  );
};

