const ZoneManager: React.FC = () => {
  const [zones, setZones] = useState<Zone[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [loading, setLoading] = useState(false);
  const [editingZone, setEditingZone] = useState<Zone | null>(null);

  const [newZoneData, setNewZoneData] = useState<Partial<Zone>>({
    name: '',
    pricing: {
      basePrice: 15,
      pricePerKm: 8,
      minPrice: 20,
      maxPrice: 500,
      sameVillagePrice: 15,
      multipliers: { TOKTOK: 1.0, MOTORCYCLE: 0.8, CAR: 2.0 }
    },
    villages: []
  });

  const [newVillageName, setNewVillageName] = useState('');

  useEffect(() => {
    return onSnapshot(collection(db, "zones"), (snap) => {
      setZones(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Zone[]);
    });
  }, []);

  const saveZone = async () => {
    if (!newZoneData.name) return alert('يرجى إدخال اسم المنطقة');
    setLoading(true);
    try {
      const id = editingZone?.id || `zone_${Date.now()}`;
      await setDoc(doc(db, "zones", id), { ...newZoneData, id });
      setIsAdding(false);
      setEditingZone(null);
      setNewZoneData({
        name: '',
        pricing: { basePrice: 15, pricePerKm: 8, minPrice: 20, maxPrice: 500, sameVillagePrice: 15, multipliers: { TOKTOK: 1.0, MOTORCYCLE: 0.8, CAR: 2.0 } },
        villages: []
      });
    } catch (e) { alert('خطأ في الحفظ'); } finally { setLoading(false); }
  };

  const addVillageToZone = () => {
    if (!newVillageName.trim()) return;
    const village: Village = {
      id: `v_${Date.now()}`,
      name: newVillageName.trim(),
      center: { lat: 30.5, lng: 31.0 }
    };
    setNewZoneData(prev => ({
      ...prev,
      villages: [...(prev.villages || []), village]
    }));
    setNewVillageName('');
  };

  const removeVillage = (vid: string) => {
    setNewZoneData(prev => ({
      ...prev,
      villages: prev.villages?.filter(v => v.id !== vid)
    }));
  };

