                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">اسم المنطقة (مثلاً: مركز أشمون)</label>
                      <input 
                        value={newZoneData.name} 
                        onChange={e => setNewZoneData({...newZoneData, name: e.target.value})} 
                        className="w-full bg-white rounded-3xl p-6 font-black outline-none border-2 border-transparent focus:border-blue-500 transition-all shadow-sm" 
