                            <input type="number" value={newZoneData.pricing?.sameVillagePrice} onChange={e => setNewZoneData({...newZoneData, pricing: {...newZoneData.pricing!, sameVillagePrice: Number(e.target.value)}})} className="w-full bg-slate-50 p-4 rounded-2xl font-black text-sm outline-none" />
                         </div>
                      </div>

                      <div className="pt-4 border-t border-slate-50 space-y-4">
                         <label className="text-[9px] font-black text-slate-400 mr-2">مضاعف سعر المركبات (Relative to Toktok)</label>
