                            <div className="bg-slate-50 p-3 rounded-2xl text-center">
                               <p className="text-[8px] font-bold text-slate-400 mb-1">موتوسيكل</p>
                               <input type="number" step="0.1" value={newZoneData.pricing?.multipliers.MOTORCYCLE} onChange={e => setNewZoneData({...newZoneData, pricing: {...newZoneData.pricing!, multipliers: {...newZoneData.pricing!.multipliers, MOTORCYCLE: Number(e.target.value)}}})} className="w-full bg-transparent text-center font-black text-xs outline-none" />
                            </div>
                            <div className="bg-slate-50 p-3 rounded-2xl text-center border-2 border-emerald-500/20">
                               <p className="text-[8px] font-bold text-slate-400 mb-1">توكتوك</p>
                               <input disabled value="1.0" className="w-full bg-transparent text-center font-black text-xs outline-none" />
                            </div>
                            <div className="bg-slate-50 p-3 rounded-2xl text-center">
                               <p className="text-[8px] font-bold text-slate-400 mb-1">سيارة</p>
                               <input type="number" step="0.1" value={newZoneData.pricing?.multipliers.CAR} onChange={e => setNewZoneData({...newZoneData, pricing: {...newZoneData.pricing!, multipliers: {...newZoneData.pricing!.multipliers, CAR: Number(e.target.value)}}})} className="w-full bg-transparent text-center font-black text-xs outline-none" />
                            </div>
                         </div>
                      </div>
                   </div>
                   <button 
                     onClick={saveZone} 
                     disabled={loading}
                     className="w-full bg-blue-600 text-white py-6 rounded-[2.5rem] font-black shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3"
                   >
                      {loading ? <Loader2 className="animate-spin h-6 w-6" /> : <><Save className="h-6 w-6" /> اعتماد منطقة التشغيل</>}
                   </button>
                </div>
             </div>
          </div>
