              {filteredUsers.map((u, index) => (
                <div key={u.id} style={{animationDelay: `${index * 0.05}s`}} className="p-8 bg-slate-50 rounded-[3rem] border-2 border-transparent hover:border-emerald-500 hover:bg-white hover:shadow-2xl transition-all group flex flex-col items-center text-center relative overflow-hidden animate-reveal">
                   <button onClick={() => setEditingUser(u)} className="absolute top-4 left-4 p-3 bg-white rounded-2xl shadow-sm text-slate-400 hover:text-emerald-600 transition-all opacity-0 group-hover:opacity-100 transform translate-y-[-10px] group-hover:translate-y-0"><Settings2 className="h-5 w-5" /></button>
                   <div className="relative mb-6">
                      <div className="w-24 h-24 bg-white rounded-[2.5rem] flex items-center justify-center font-black text-slate-300 text-3xl group-hover:bg-slate-950 group-hover:text-emerald-400 transition-all shadow-xl border-4 border-white overflow-hidden">
                        {u.photoURL ? <img src={u.photoURL} className="w-full h-full object-cover" /> : (u.name || 'ع')[0]}
                      </div>
                      <div className={`absolute -bottom-1 -right-1 p-2 rounded-full border-4 border-white shadow-lg ${u.status === 'APPROVED' ? 'bg-emerald-500' : 'bg-rose-500'}`}><CheckCircle className="h-3 w-3 text-white" /></div>
                   </div>
                   <div className="space-y-1 mb-6">
                      <h4 className="font-black text-slate-900 text-lg leading-tight group-hover:text-emerald-600 transition-colors">{u.name}</h4>
                      <p className="text-xs font-bold text-slate-400" dir="ltr">{u.phone}</p>
                      <span className="inline-block mt-2 px-4 py-1.5 bg-white rounded-full text-[8px] font-black uppercase tracking-widest text-slate-400 border border-slate-100">{u.role}</span>
                   </div>
                   <div className="w-full grid grid-cols-2 gap-3 pt-6 border-t border-slate-200" dir="rtl">
                      <div className="text-right"><p className="text-[8px] font-black text-slate-400 uppercase mb-1">الرصيد</p><p className="text-md font-black text-emerald-600">{(u.wallet?.balance || 0).toFixed(1)} <span className="text-[8px]">ج.م</span></p></div>
                      <div className="text-left"><p className="text-[8px] font-black text-slate-400 uppercase mb-1">الرحلات</p><p className="text-md font-black text-slate-800">12</p></div>
                   </div>
                </div>
              ))}
           </div>
        </div>
      )}

      {activeTab === 'RESTAURANTS' && <RestaurantEditor />}
      {activeTab === 'PAYMENTS' && <PaymentRequests />}
      {activeTab === 'ZONES' && <ZoneManager />}
    </div>
  );
};

