                   <div className="w-full grid grid-cols-2 gap-3 pt-6 border-t border-slate-200" dir="rtl"><div className="text-right"><p className="text-[8px] font-black text-slate-400 uppercase mb-1">الرصيد</p><p className="text-md font-black text-emerald-600">{(u.wallet?.balance || 0).toFixed(1)} <span className="text-[8px]">ج.م</span></p></div><div className="text-left"><p className="text-[8px] font-black text-slate-400 uppercase mb-1">الرحلات</p><p className="text-md font-black text-slate-800">12</p></div></div>
                </div>
