/**
 * مكون إدارة محافظة المنوفية (المراكز والقرى)
 */
const MenofiaGovernorateManager: React.FC = () => {
  const [zones, setZones] = useState<Zone[]>([]);
  const [loading, setLoading] = useState(false);
  const [activeDistrictId, setActiveDistrictId] = useState<string | null>(null);
  const [isAddingZone, setIsAddingZone] = useState(false);
  const [newVillageName, setNewVillageName] = useState('');

  // بيانات افتراضية للمراكز إذا كانت القاعدة فارغة
  const MONOFIA_DISTRICTS = [
    'شبين الكوم', 'أشمون', 'منوف', 'قويسنا', 'الباجور', 
    'تلا', 'بركة السبع', 'الشهداء', 'السادات', 'سرس الليان'
  ];

  useEffect(() => {
    const unsub = onSnapshot(collection(db, "zones"), (snap) => {
      setZones(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Zone[]);
    });
    return () => unsub();
  }, []);

  const handleCreateDistrictZone = async (name: string) => {
    setLoading(true);
    try {
      const id = `zone_${Date.now()}`;
      const newZone: Partial<Zone> = {
        id,
        name,
        pricing: {
          basePrice: 15,
          pricePerKm: 8,
          minPrice: 20,
          maxPrice: 500,
          sameVillagePrice: 15,
          multipliers: { TOKTOK: 1.0, MOTORCYCLE: 0.8, CAR: 2.0 }
        },
        villages: []
      };
      await setDoc(doc(db, "zones", id), newZone);
      setActiveDistrictId(id);
    } catch (e) { alert('فشل إنشاء المركز'); } finally { setLoading(false); }
  };

  const addVillage = async (zoneId: string) => {
    if (!newVillageName.trim()) return;
    const zone = zones.find(z => z.id === zoneId);
    if (!zone) return;

    const newVillage: Village = {
      id: `v_${Date.now()}`,
      name: newVillageName.trim(),
      center: { lat: 30.5, lng: 31.0 }
    };

    try {
      await updateDoc(doc(db, "zones", zoneId), {
        villages: [...(zone.villages || []), newVillage]
      });
      setNewVillageName('');
    } catch (e) { alert('خطأ في الإضافة'); }
  };

  const deleteVillage = async (zoneId: string, villageId: string) => {
    const zone = zones.find(z => z.id === zoneId);
    if (!zone) return;
    try {
      await updateDoc(doc(db, "zones", zoneId), {
        villages: zone.villages?.filter(v => v.id !== villageId) || []
      });
    } catch (e) { alert('خطأ في الحذف'); }
  };

  const updatePricing = async (zoneId: string, pricing: any) => {
    try {
      await updateDoc(doc(db, "zones", zoneId), { pricing });
      alert('تم تحديث الأسعار بنجاح');
    } catch (e) { alert('خطأ في التحديث'); }
  };

  return (
    <div className="space-y-10 animate-reveal text-right" dir="rtl">
      {/* رأس القسم */}
      <div className="bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
        <div>
           <h3 className="text-3xl font-black text-slate-900 flex items-center gap-4">
              <div className="bg-emerald-500 p-3 rounded-2xl text-white shadow-lg"><Globe className="h-6 w-6" /></div>
              إدارة محافظة المنوفية
           </h3>
           <p className="text-slate-400 font-bold text-xs mt-2 mr-14">التحكم في المراكز، القرى، وتسعيرة التوصيل الذكية</p>
        </div>
        <div className="flex gap-3">
           <div className="bg-slate-50 px-6 py-4 rounded-2xl border border-slate-100 text-slate-500 font-black text-xs uppercase tracking-widest">
              {zones.length} مراكز مفعلة
           </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
         {/* قائمة المراكز */}
         <div className="lg:col-span-4 space-y-4">
            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] px-6 mb-4">مراكز المحافظة</h4>
            {MONOFIA_DISTRICTS.map((name) => {
              const zone = zones.find(z => z.name === name);
              return (
                <div 
                  key={name}
                  onClick={() => zone ? setActiveDistrictId(zone.id) : handleCreateDistrictZone(name)}
                  className={`p-6 rounded-[2.2rem] border-2 cursor-pointer transition-all flex items-center justify-between group ${
                    activeDistrictId === zone?.id 
                      ? 'bg-slate-900 border-slate-900 text-white shadow-2xl scale-[1.02]' 
                      : zone 
                        ? 'bg-white border-slate-100 text-slate-800 hover:border-emerald-500 hover:shadow-lg' 
                        : 'bg-slate-50 border-dashed border-slate-200 text-slate-300 hover:bg-white hover:border-emerald-200 opacity-60'
                  }`}
                >
                   <div className="flex items-center gap-4">
                      <div className={`p-3.5 rounded-2xl transition-colors ${activeDistrictId === zone?.id ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-400 group-hover:bg-emerald-50 group-hover:text-emerald-500'}`}>
                         {DISTRICT_ICONS[name] || <Building2 className="h-6 w-6" />}
                      </div>
                      <div>
                         <p className="font-black text-lg leading-none">{name}</p>
                         <p className={`text-[10px] font-bold mt-1.5 ${activeDistrictId === zone?.id ? 'text-emerald-400' : 'text-slate-400'}`}>
                            {zone ? `${zone.villages?.length || 0} قرية مضافة` : 'غير مفعّل'}
                         </p>
                      </div>
                   </div>
                   {!zone && <PlusCircle className="h-5 w-5 opacity-0 group-hover:opacity-100 transition-opacity" />}
                   {zone && activeDistrictId !== zone.id && <ChevronRight className="h-5 w-5 opacity-40 group-hover:translate-x-[-5px] transition-transform rotate-180" />}
                </div>
              );
            })}
         </div>

         {/* تفاصيل المركز المختار */}
         <div className="lg:col-span-8 space-y-8">
            {activeDistrictId ? (
              <div className="animate-in slide-in-from-left duration-500 space-y-8">
                 {/* كارت الأسعار */}
                 <div className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-xl space-y-10 relative overflow-hidden">
                    <div className="absolute top-0 left-0 w-64 h-64 bg-emerald-500/5 blur-[100px] pointer-events-none"></div>
                    <div className="flex justify-between items-center relative z-10">
                       <h4 className="text-2xl font-black text-slate-900 flex items-center gap-3">
                          <DollarSign className="text-emerald-500" /> 
                          تسعيرة مركز {zones.find(z => z.id === activeDistrictId)?.name}
                       </h4>
                       <span className="bg-emerald-50 text-emerald-600 px-4 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest">تحديث لحظي للأسعار</span>
                    </div>

                    <div className="grid grid-cols-2 md:grid-cols-4 gap-6 relative z-10">
                       {[
                         { key: 'basePrice', label: 'فتح العداد', icon: <Zap className="h-4 w-4" /> },
                         { key: 'pricePerKm', label: 'سعر الكيلومتر', icon: <TrendingUp className="h-4 w-4" /> },
                         { key: 'minPrice', label: 'أقل سعر رحلة', icon: <Percent className="h-4 w-4" /> },
                         { key: 'sameVillagePrice', label: 'داخل القرية', icon: <MapPin className="h-4 w-4" /> }
                       ].map((item) => (
                         <div key={item.key} className="bg-slate-50 p-6 rounded-[2.5rem] border border-slate-100 space-y-3">
                            <div className="flex items-center gap-2 text-slate-400 font-black text-[9px] uppercase tracking-widest">
                               {item.icon} {item.label}
                            </div>
                            <input 
                               type="number" 
                               value={zones.find(z => z.id === activeDistrictId)?.pricing[item.key as keyof Zone['pricing']] as number}
                               onChange={(e) => {
                                  const zone = zones.find(z => z.id === activeDistrictId);
                                  if (zone) {
                                     const newPricing = { ...zone.pricing, [item.key]: Number(e.target.value) };
                                     updatePricing(activeDistrictId, newPricing);
                                  }
                               }}
                               className="w-full bg-transparent font-black text-2xl text-slate-900 outline-none"
                            />
                         </div>
                       ))}
                    </div>
                 </div>

                 {/* إدارة القرى */}
                 <div className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-xl space-y-8">
                    <div className="flex justify-between items-center px-2">
                       <h4 className="text-2xl font-black text-slate-900 flex items-center gap-3">
                          <Navigation className="text-blue-500" />
                          إدارة القرى والعزب
                       </h4>
                       <div className="flex gap-2">
                          <input 
                            value={newVillageName} 
                            onChange={e => setNewVillageName(e.target.value)}
                            onKeyPress={e => e.key === 'Enter' && addVillage(activeDistrictId)}
                            placeholder="اسم القرية الجديدة..." 
                            className="bg-slate-50 rounded-2xl px-6 py-3 font-bold text-sm border-none focus:ring-2 focus:ring-blue-500 outline-none w-48 md:w-64"
                          />
                          <button onClick={() => addVillage(activeDistrictId)} className="bg-blue-600 text-white p-4 rounded-2xl shadow-lg active:scale-90 transition-all"><PlusCircle className="h-6 w-6" /></button>
                       </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                       {zones.find(z => z.id === activeDistrictId)?.villages?.map((v) => (
                         <div key={v.id} className="p-5 bg-slate-50 rounded-[2rem] border border-slate-100 flex justify-between items-center group hover:bg-white hover:border-blue-500/20 hover:shadow-xl transition-all">
                            <div className="flex items-center gap-4">
                               <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-blue-500 shadow-sm font-black text-xs">{v.name[0]}</div>
                               <span className="font-black text-slate-800">{v.name}</span>
                            </div>
                            <button onClick={() => deleteVillage(activeDistrictId, v.id)} className="p-3 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all"><Trash2 className="h-5 w-5" /></button>
                         </div>
                       ))}
                       {(zones.find(z => z.id === activeDistrictId)?.villages?.length || 0) === 0 && (
                         <div className="col-span-full py-16 text-center text-slate-300 font-bold border-2 border-dashed border-slate-100 rounded-[3rem]">
                            لا يوجد قرى مضافة لهذا المركز حالياً
                         </div>
                       )}
                    </div>
                 </div>
              </div>
            ) : (
              <div className="h-full flex flex-col items-center justify-center py-40 bg-white rounded-[4rem] border-4 border-dashed border-slate-50 text-slate-300 space-y-6">
                 <div className="bg-slate-50 p-10 rounded-full animate-pulse"><Globe className="h-20 w-20" /></div>
                 <p className="font-black text-xl tracking-tight">اختر مركزاً من القائمة الجانبية للتحكم في إعداداته</p>
              </div>
            )}
         </div>
      </div>
    </div>
  );
};

/**
 * مكون لتعديل بيانات المستخدم بالكامل (الحالة والدور)
