       </div>

       <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-4 md:space-y-6 no-scrollbar bg-slate-50">
          {allMenuImages.length > 0 && (
            <button onClick={() => setShowFullMenu(true)} className="w-full bg-emerald-600 p-5 md:p-6 rounded-[2rem] md:rounded-[2.5rem] text-white flex justify-between items-center shadow-xl active:scale-95 border-none group">
               <div className="bg-white/20 p-3 md:p-4 rounded-xl md:rounded-2xl group-hover:rotate-12 transition-transform"><ZoomIn className="h-5 w-5 md:h-6 md:w-6" /></div>
               <div className="text-right">
                  <h4 className="font-black text-md md:text-lg">تصفح المنيو الورقي</h4>
                  <p className="text-[9px] md:text-[10px] opacity-80 uppercase font-black tracking-widest mt-1">
                    {allMenuImages.length === 1 ? 'عرض المنيو كاملاً' : `عرض ${allMenuImages.length} صفحات`}
                  </p>
               </div>
            </button>
          )}

          <div className="space-y-3 md:space-y-4">
             {restaurant.menu?.map(item => (
               <div key={item.id} className="bg-white p-4 md:p-5 rounded-[2rem] md:rounded-[2.5rem] shadow-sm border border-slate-100 flex justify-between items-center">
                  <div className="flex items-center gap-3 md:gap-4">
                     <div className="flex items-center gap-1.5 md:gap-2 bg-slate-50 p-1.5 md:p-2 rounded-xl md:rounded-2xl">
                        <button onClick={() => addToCart(item)} className="p-1.5 md:p-2 bg-emerald-500 text-white rounded-lg md:rounded-xl active:scale-75 transition-all"><Plus className="h-3.5 w-3.5 md:h-4 md:w-4" /></button>
                        <span className="font-black text-md md:text-lg w-5 md:w-6 text-center">{cart.find(i => i.id === item.id)?.quantity || 0}</span>
                        <button onClick={() => removeFromCart(item.id)} className="p-1.5 md:p-2 bg-rose-50 text-rose-500 rounded-lg md:rounded-xl active:scale-75 transition-all"><Trash className="h-3.5 w-3.5 md:h-4 md:w-4" /></button>
                     </div>
                     <div className="text-left"><p className="font-black text-emerald-600 text-sm md:text-base">{item.price} <span className="text-[10px] font-bold">ج.م</span></p></div>
                  </div>
                  <div className="text-right flex items-center gap-3 md:gap-4 flex-row-reverse">
                     <div className="w-12 h-12 md:w-16 md:h-16 bg-slate-100 rounded-xl md:rounded-2xl overflow-hidden shrink-0 shadow-inner">
                        {item.photoURL ? <img src={item.photoURL} className="w-full h-full object-cover" /> : <UtensilsCrossed className="p-3 md:p-4 text-slate-200" />}
                     </div>
                     <div><p className="font-black text-slate-800 text-sm md:text-lg leading-tight">{item.name}</p></div>
                  </div>
               </div>
             ))}
          </div>
       </div>

       {cart.length > 0 && (
         <div className="p-6 md:p-8 bg-white border-t border-slate-100 pb-10 md:pb-12 shadow-2xl shrink-0">
            <div className="flex justify-between items-center mb-4 md:mb-6 px-2">
               <p className="text-xl md:text-2xl font-black text-slate-900">{total} <span className="text-[10px] opacity-40 uppercase">ج.م</span></p>
               <p className="text-[10px] md:text-xs font-black text-slate-400 uppercase tracking-widest">إجمالي الطلبات</p>
            </div>
            <button onClick={() => onCheckout(cart)} className="w-full bg-[#10b981] text-white py-5 md:py-7 rounded-[1.8rem] md:rounded-[2.5rem] font-black text-md md:text-lg shadow-2xl flex items-center justify-center gap-3 md:gap-4 active:scale-95 transition-all">
               <ShoppingBag className="h-5 w-5 md:h-6 md:w-6" /> تأكيد طلب الطعام
            </button>
         </div>
       )}
    </div>
  );
};

const VillageInput: React.FC<{
  label: string; helper: string; icon: React.ReactNode; iconBg: string;
  selectedVillage: Village | null; onSelect: (v: Village) => void;
}> = ({ label, helper, icon, iconBg, selectedVillage, onSelect }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const allVillages = MENOFIA_DATA.flatMap(d => d.villages);
  const filtered = allVillages.filter(v => v.name.includes(searchTerm));

  return (
    <div className="relative space-y-1">
      <div className="flex flex-col px-2 text-right"><label className="label-strong">{label}</label><span className="helper-text">{helper}</span></div>
      <div onClick={() => setIsOpen(!isOpen)} className="bg-white border-2 border-slate-100 p-4 md:p-5 rounded-[1.8rem] md:rounded-[2.2rem] flex items-center justify-between cursor-pointer shadow-sm active:border-emerald-500 transition-all">
        <ChevronDown className={`h-4 w-4 md:h-5 md:w-5 text-slate-400 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        <div className="flex items-center gap-3 md:gap-4 flex-row-reverse text-right">
          <span className={`text-base md:text-lg font-black ${selectedVillage ? 'text-slate-900' : 'text-slate-300'}`}>{selectedVillage?.name || "اختر القرية"}</span>
          <div className={`${iconBg} p-3 md:p-4 rounded-xl md:rounded-2xl text-white shadow-xl`}>{icon}</div>
        </div>
      </div>
      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-[2rem] md:rounded-[3rem] shadow-2xl border border-slate-100 z-[200] max-h-[300px] md:max-h-[350px] overflow-hidden flex flex-col animate-in zoom-in">
          <div className="p-3 md:p-4 border-b border-slate-50"><input className="w-full bg-slate-50 border-none rounded-xl md:rounded-2xl py-3 md:py-4 px-5 md:px-6 text-xs md:text-sm font-black text-right outline-none" placeholder="ابحث عن قريتك..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} dir="rtl" /></div>
          <div className="flex-1 overflow-y-auto no-scrollbar p-3 md:p-4">
             {filtered.map(v => (
               <button key={v.id} onClick={() => { onSelect(v); setIsOpen(false); }} className="w-full p-3 md:p-4 hover:bg-emerald-50 rounded-xl md:rounded-2xl flex justify-between items-center transition-all flex-row-reverse">
                  <span className="font-bold text-slate-700 text-sm md:text-base">{v.name}</span>
                  {selectedVillage?.id === v.id && <Check className="h-4 w-4 md:h-5 md:w-5 text-emerald-500" />}
               </button>
             ))}
          </div>
        </div>
      )}
    </div>
  );
};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'PROFILE' | 'ACTIVITY' | 'WALLET'>('NEW');
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [viewingRestaurant, setViewingRestaurant] = useState<Restaurant | null>(null);
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [pickupNotes, setPickupNotes] = useState('');
  const [dropoffNotes, setDropoffNotes] = useState('');
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);

  const [pharmacyNotes, setPharmacyNotes] = useState('');
  const [prescriptionPhoto, setPrescriptionPhoto] = useState<string | null>(null);
  const fileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });
    return onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder]);

  const handleCheckoutFood = async (cart: CartItem[]) => {
    if (!viewingRestaurant || !dropoffVillage) return alert('يرجى اختيار مكان التوصيل');
    setIsSubmitting(true);
    try {
      const dist = calculateDistance(viewingRestaurant.lat, viewingRestaurant.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const deliveryPrice = Math.max(Math.round(DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)), DEFAULT_PRICING.minPrice);
      const foodTotal = cart.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);

      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: 'FOOD',
        pickup: { address: viewingRestaurant.name, lat: viewingRestaurant.lat, lng: viewingRestaurant.lng, villageName: viewingRestaurant.address },
        dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'MOTORCYCLE',
        price: deliveryPrice + foodTotal, distance: dist, operatorId: 'op_main', zoneId: 'zone_main',
        paymentMethod: 'CASH', foodItems: cart, restaurantId: viewingRestaurant.id, restaurantName: viewingRestaurant.name
      });
      setViewingRestaurant(null);
    } catch(e) { alert('خطأ فني'); } finally { setIsSubmitting(false); }
  };

  const handlePharmacyOrder = async () => {
    if (!dropoffVillage) return alert('يرجى اختيار مكان التوصيل');
    if (!pharmacyNotes.trim() && !prescriptionPhoto) return alert('يرجى كتابة الطلبات أو إرفاق صورة الروشتة');

    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: 'PHARMACY',
        pickup: { address: 'أقرب صيدلية', lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: 'منطقة الصيدلية' },
        dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'MOTORCYCLE',
        price: DEFAULT_PRICING.minPrice + 10, distance: 1, operatorId: 'op_main', zoneId: 'zone_main',
        paymentMethod: 'CASH', 
        notes: pharmacyNotes, 
        pickupNotes: prescriptionPhoto ? 'صورة الروشتة مرفقة' : 'لا توجد صورة',
        prescriptionImage: prescriptionPhoto 
      });
      setPharmacyNotes('');
      setPrescriptionPhoto(null);
    } catch(e) { alert('فشل إرسال الطلب'); } finally { setIsSubmitting(false); }
  };

  const handlePrescriptionUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const MAX_WIDTH = 1024;
        const scale = MAX_WIDTH / img.width;
        canvas.width = MAX_WIDTH;
        canvas.height = img.height * scale;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, canvas.width, canvas.height);
        setPrescriptionPhoto(canvas.toDataURL('image/jpeg', 0.7));
      };
      img.src = event.target?.result as string;
    };
    reader.readAsDataURL(file);
  };

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone,
        status: OrderStatus.ACCEPTED, acceptedAt: Date.now()
      });
    } catch (e) { alert('فشل قبول العرض'); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />
      {viewingRestaurant && <RestaurantMenu restaurant={viewingRestaurant} onClose={() => setViewingRestaurant(null)} onCheckout={handleCheckoutFood} />}

      <div className="rh-ui-panel no-scrollbar z-[100] translate-y-0 bg-slate-50">
        <div className="bottom-sheet-grabber lg:hidden"></div>
        <div className="p-6 md:p-12 space-y-8 md:space-y-10 pb-32 max-w-2xl mx-auto h-full overflow-y-auto no-scrollbar text-right">
          {!activeOrder ? (
            <>
              <div className="flex items-center justify-between">
                 <div><h2 className="text-3xl md:text-4xl font-black text-slate-950 tracking-tighter">وصـــلــهــا</h2><p className="text-slate-400 font-bold text-[10px] md:text-xs mt-1">توصيل المنوفية الذكي</p></div>
                 <button onClick={() => setAiOpen(true)} className="p-3.5 md:p-4 bg-emerald-50 text-emerald-600 rounded-2xl md:rounded-3xl active:scale-90 shadow-sm border-none"><Bot className="h-6 w-6 md:h-8 md:w-8" /></button>
              </div>
              <div className="grid grid-cols-3 gap-3 md:gap-4">
                  {[
                    { id: 'TAXI', label: 'مشوار', icon: <Bike className="h-6 w-6 md:h-8 md:w-8" /> },
                    { id: 'FOOD', label: 'أكل', icon: <UtensilsCrossed className="h-6 w-6 md:h-8 md:w-8" /> },
                    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill className="h-6 w-6 md:h-8 md:w-8" /> }
                  ].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`py-6 md:py-8 rounded-[1.5rem] md:rounded-[2.5rem] flex flex-col items-center gap-2 md:gap-3 border-4 transition-all ${selectedCategory === cat.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-2xl scale-105' : 'bg-white border-transparent text-slate-400 opacity-60'}`}>
                       {cat.icon} <span className="text-[9px] md:text-[11px] font-black uppercase tracking-widest">{cat.label}</span>
                    </button>
                  ))}
              </div>

              {selectedCategory === 'FOOD' ? (
                <div className="space-y-6 md:space-y-8 animate-in zoom-in">
                   <VillageInput label="التوصيل إلى" helper="أين ستستلم طلبك؟" icon={<MapPin className="h-5 w-5 md:h-6 md:w-6" />} iconBg="bg-rose-500" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} />
                   <div className="grid grid-cols-1 gap-4 md:gap-6">
                      {restaurants.map(rest => (
                        <div key={rest.id} onClick={() => setViewingRestaurant(rest)} className="bg-white p-5 md:p-7 rounded-[2rem] md:rounded-[3.5rem] border border-slate-100 shadow-sm flex flex-row-reverse justify-between items-center hover:border-emerald-500 transition-all cursor-pointer group active:scale-[0.98] transition-all">
                           <div className="flex items-center gap-3 md:gap-5 flex-row-reverse text-right">
                              <div className="w-12 h-12 md:w-16 md:h-16 bg-slate-900 rounded-[1.2rem] md:rounded-[1.8rem] flex items-center justify-center overflow-hidden shadow-lg">
                                 {rest.photoURL ? <img src={rest.photoURL} className="w-full h-full object-cover" /> : <UtensilsCrossed className="h-6 w-6 md:h-8 md:w-8 text-emerald-400" />}
                              </div>
                              <div><h4 className="text-lg md:text-xl font-black text-slate-800 leading-tight">{rest.name}</h4><p className="text-[9px] md:text-xs font-bold text-slate-400 uppercase tracking-tighter">{rest.category}</p></div>
                           </div>
                           <ChevronRight className="h-5 w-5 md:h-6 md:w-6 text-slate-300 rotate-180 group-hover:text-emerald-500 transition-colors" />
                        </div>
                      ))}
                   </div>
                </div>
              ) : selectedCategory === 'PHARMACY' ? (
                <div className="space-y-6 md:space-y-8 animate-in zoom-in">
                   <div className="bg-sky-50 border-2 border-sky-100 p-6 md:p-8 rounded-[2rem] md:rounded-[3rem] text-center space-y-2 md:space-y-3">
                      <Pill className="h-10 w-10 md:h-12 md:w-12 text-sky-600 mx-auto" />
                      <h3 className="text-lg md:text-xl font-black text-sky-900">طلب أدوية صيدلية</h3>
                      <p className="text-[10px] md:text-xs font-bold text-sky-600">اكتب طلباتك أو ارفع صورة الروشتة</p>
                   </div>

                   <VillageInput label="مكان التوصيل" helper="أين ستستلم الدواء؟" icon={<MapPin className="h-5 w-5 md:h-6 md:w-6" />} iconBg="bg-sky-600" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} />

                   <div className="space-y-3 md:space-y-4">
                      <div className="flex items-center justify-between px-2"><label className="label-strong">طلبات الصيدلية</label><ClipboardList className="h-4 w-4 text-slate-300" /></div>
                      <textarea value={pharmacyNotes} onChange={e => setPharmacyNotes(e.target.value)} placeholder="اكتب أسماء الأدوية..." dir="rtl" className="w-full bg-white border-2 border-slate-100 rounded-[1.5rem] md:rounded-[2rem] p-5 md:p-6 text-sm font-bold outline-none focus:border-sky-500 min-h-[100px] md:min-h-[120px] transition-all shadow-sm" />
                   </div>

                   <div className="space-y-3 md:space-y-4">
                      <div className="flex items-center justify-between px-2"><label className="label-strong">صورة الروشتة (اختياري)</label><Camera className="h-4 w-4 text-slate-300" /></div>
                      <div onClick={() => fileRef.current?.click()} className="w-full h-28 md:h-32 bg-white border-2 border-dashed border-slate-200 rounded-[1.5rem] md:rounded-[2rem] flex flex-col items-center justify-center cursor-pointer hover:border-sky-400 transition-all overflow-hidden relative">
                         {prescriptionPhoto ? <img src={prescriptionPhoto} className="w-full h-full object-cover" /> : <><Plus className="h-6 w-6 md:h-8 md:w-8 text-slate-300 mb-1" /><span className="text-[9px] md:text-[10px] font-black text-slate-400 uppercase">ارفق الصورة</span></>}
                         <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={handlePrescriptionUpload} />
                      </div>
                   </div>

                   <button onClick={handlePharmacyOrder} disabled={isSubmitting} className="w-full bg-sky-600 text-white py-6 md:py-8 rounded-[2rem] md:rounded-[3rem] font-black text-lg md:text-xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3 md:gap-4">
                      {isSubmitting ? <Loader2 className="animate-spin h-6 w-6" /> : <>إرسال طلب الصيدلية <FileText className="h-5 w-5 md:h-6 md:w-6" /></>}
                   </button>
                </div>
              ) : (
                <div className="space-y-6 md:space-y-8 animate-in slide-in-from-right">
                   {/* قسم نقطة الانطلاق */}
                   <div className="space-y-3">
                     <VillageInput label="نقطة الانطلاق" helper="موقع استلامك" icon={<MapPin className="h-5 w-5 md:h-6 md:w-6" />} iconBg="bg-emerald-500" selectedVillage={pickupVillage} onSelect={setPickupVillage} />
                     <div className="bg-white border-2 border-slate-100 rounded-3xl p-4 flex items-start gap-3 shadow-sm focus-within:border-emerald-200 transition-all">
                        <Info className="h-5 w-5 text-emerald-500 mt-1 shrink-0" />
                        <input 
                           value={pickupNotes} 
                           onChange={e => setPickupNotes(e.target.value)} 
                           placeholder="تفاصيل موقع الاستلام (مثلاً: بجوار صيدلية كذا)" 
                           className="w-full bg-transparent text-sm font-bold outline-none text-right placeholder:text-slate-300" 
                           dir="rtl" 
                        />
                     </div>
                   </div>

                   {/* قسم وجهة الوصول */}
                   <div className="space-y-3">
                     <VillageInput label="وجهة الوصول" helper="الوجهة النهائية" icon={<Check className="h-5 w-5 md:h-6 md:w-6" />} iconBg="bg-rose-500" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} />
                     <div className="bg-white border-2 border-slate-100 rounded-3xl p-4 flex items-start gap-3 shadow-sm focus-within:border-rose-200 transition-all">
                        <Info className="h-5 w-5 text-rose-500 mt-1 shrink-0" />
                        <input 
                           value={dropoffNotes} 
                           onChange={e => setDropoffNotes(e.target.value)} 
                           placeholder="تفاصيل وجهة الوصول (مثلاً: رقم الشقة أو المحل)" 
                           className="w-full bg-transparent text-sm font-bold outline-none text-right placeholder:text-slate-300" 
                           dir="rtl" 
                        />
                     </div>
                   </div>

                   <button onClick={async () => {
                     if(!pickupVillage || !dropoffVillage) return alert('يرجى اختيار نقطة الانطلاق والوصول');
                     setIsSubmitting(true);
                     try {
                        const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
                        const price = Math.max(Math.round(DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)), DEFAULT_PRICING.minPrice);
                        await addDoc(collection(db, "orders"), {
                           customerId: user.id, customerPhone: user.phone, category: 'TAXI',
                           pickup: { address: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng, villageName: pickupVillage.name },
                           dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
                           pickupNotes: pickupNotes.trim(),
                           dropoffNotes: dropoffNotes.trim(),
                           status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'TOKTOK',
                           price, distance: dist, operatorId: 'op_main', zoneId: 'zone_main', paymentMethod: 'CASH'
                        });
                        setPickupNotes('');
                        setDropoffNotes('');
                     } catch(e) { alert('خطأ'); } finally { setIsSubmitting(false); }
                   }} disabled={!pickupVillage || !dropoffVillage || isSubmitting} className="w-full bg-slate-950 text-white py-6 md:py-8 rounded-[2rem] md:rounded-[3rem] font-black text-xl md:text-2xl shadow-2xl active:scale-95 transition-all">
                      {isSubmitting ? <Loader2 className="animate-spin h-8 w-8" /> : 'اطلب الآن'}
                   </button>
                </div>
              )}
            </>
          ) : (
            <div className="space-y-8 md:space-y-12">
               {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
