           {id: 'PROFILE', icon: <UserIcon className="h-6 w-6 md:h-7 md:w-7" />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-1.5 md:gap-2 transition-all ${activeView === tab.id ? 'text-emerald-600 scale-110 md:scale-125' : 'text-slate-300'}`}>
              <div className={`p-2.5 md:p-3.5 rounded-xl md:rounded-2xl ${activeView === tab.id ? 'bg-emerald-50 shadow-inner' : ''}`}>{tab.icon}</div>
              <span className="text-[8px] md:text-[10px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

