const FullMenuModal: React.FC<{ urls: string[], onClose: () => void }> = ({ urls, onClose }) => {
  const [index, setIndex] = useState(0);

  useEffect(() => {
    window.history.pushState({ modal: 'full-menu' }, '');
    const handlePopState = () => onClose();
    window.addEventListener('popstate', handlePopState);
    return () => {
      window.removeEventListener('popstate', handlePopState);
      if (window.history.state?.modal === 'full-menu') window.history.back();
    };
  }, [onClose]);

  return (
    <div className="fixed inset-0 z-[3000] bg-black/98 backdrop-blur-3xl flex flex-col animate-in fade-in duration-300">
      <div className="p-4 md:p-8 flex justify-between items-center text-white border-b border-white/5 bg-black/20">
        <div className="flex items-center gap-3 md:gap-4">
           <button onClick={() => {
             const link = document.createElement('a');
             link.href = urls[index];
             link.download = `menu_page_${index + 1}.png`;
             link.click();
           }} className="p-3 md:p-4 bg-emerald-600 rounded-xl md:rounded-2xl flex items-center gap-2 font-black text-[10px] md:text-xs shadow-lg active:scale-90">
             <Download className="h-4 w-4 md:h-5 md:w-5" /> حفظ
           </button>
           <span className="text-[10px] md:text-xs font-black bg-white/10 px-3 md:px-4 py-1.5 md:py-2 rounded-full border border-white/10 uppercase tracking-widest">
             {index + 1} / {urls.length}
           </span>
        </div>
        <button onClick={onClose} className="p-3 md:p-4 bg-white/5 rounded-xl md:rounded-2xl flex items-center gap-2 font-black text-[10px] md:text-xs active:scale-90 border border-white/10">
          إغلاق <X className="h-4 w-4 md:h-5 md:w-5" />
        </button>
      </div>

      <div className="flex-1 relative flex items-center justify-center overflow-hidden">
         {urls.length > 1 && (
           <>
              <button 
                onClick={() => setIndex(prev => (prev > 0 ? prev - 1 : urls.length - 1))}
                className="absolute left-4 md:left-6 z-10 p-4 md:p-5 bg-white/10 hover:bg-white/20 text-white rounded-full backdrop-blur-xl border border-white/10 active:scale-75 transition-all"
              >
                <ChevronLeft className="h-6 w-6 md:h-8 md:w-8" />
              </button>
              <button 
                onClick={() => setIndex(prev => (prev < urls.length - 1 ? prev + 1 : 0))}
                className="absolute right-4 md:right-6 z-10 p-4 md:p-5 bg-white/10 hover:bg-white/20 text-white rounded-full backdrop-blur-xl border border-white/10 active:scale-75 transition-all"
              >
                <ChevronRight className="h-6 w-6 md:h-8 md:w-8" />
              </button>
           </>
         )}
         <div className="w-full h-full p-2 md:p-4 flex items-center justify-center">
            <img 
              key={index}
              src={urls[index]} 
              className="max-w-full max-h-full object-contain rounded-lg md:rounded-xl shadow-2xl animate-in zoom-in slide-in-from-right duration-500" 
              alt={`Menu page ${index + 1}`} 
            />
         </div>
      </div>

      <div className="p-4 md:p-8 flex justify-center gap-2 md:gap-3 bg-black/20">
         {urls.map((_, i) => (
           <div 
             key={i} 
             onClick={() => setIndex(i)}
             className={`h-1 md:h-1.5 rounded-full transition-all duration-300 cursor-pointer ${i === index ? 'w-8 md:w-12 bg-emerald-500' : 'w-2 md:w-4 bg-white/20'}`}
           />
         ))}
      </div>
    </div>
  );
};

const RestaurantMenu: React.FC<{ 
  restaurant: Restaurant, 
  onClose: () => void, 
  onCheckout: (cart: CartItem[]) => void 
}> = ({ restaurant, onClose, onCheckout }) => {
  const [cart, setCart] = useState<CartItem[]>([]);
  const [showFullMenu, setShowFullMenu] = useState(false);

  const allMenuImages = Array.from(new Set([
    ...(restaurant.menuImageURLs || []),
    ...(restaurant.menuImageURL ? [restaurant.menuImageURL] : [])
  ])).filter(Boolean);

  useEffect(() => {
    window.history.pushState({ modal: 'restaurant-menu' }, '');
    const handlePopState = () => onClose();
    window.addEventListener('popstate', handlePopState);
    return () => {
      window.removeEventListener('popstate', handlePopState);
      if (window.history.state?.modal === 'restaurant-menu') window.history.back();
    };
  }, [onClose]);

  const addToCart = (item: MenuItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { id: item.id, name: item.name, price: item.price, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.map(i => i.id === id ? { ...i, quantity: Math.max(0, i.quantity - 1) } : i).filter(i => i.quantity > 0));
  };

  const total = cart.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);

  return (
    <div className="fixed inset-0 bg-white z-[1100] flex flex-col animate-in slide-in-from-left duration-300">
       {showFullMenu && allMenuImages.length > 0 && <FullMenuModal urls={allMenuImages} onClose={() => setShowFullMenu(false)} />}

       <div className="bg-slate-900 p-6 md:p-8 pt-10 md:pt-14 text-white flex justify-between items-center shadow-xl shrink-0">
          <button onClick={onClose} className="p-3 bg-white/10 rounded-2xl active:scale-90"><ArrowRight className="h-5 w-5 md:h-6 md:w-6" /></button>
          <div className="text-right">
             <h3 className="text-xl md:text-2xl font-black">{restaurant.name}</h3>
             <p className="text-[10px] md:text-xs font-bold text-emerald-400">{restaurant.category}</p>
          </div>
       </div>

       <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-4 md:space-y-6 no-scrollbar bg-slate-50">
          {allMenuImages.length > 0 && (
            <button onClick={() => setShowFullMenu(true)} className="w-full bg-emerald-600 p-5 md:p-6 rounded-[2rem] md:rounded-[2.5rem] text-white flex justify-between items-center shadow-xl active:scale-95 border-none group">
               <div className="bg-white/20 p-3 md:p-4 rounded-xl md:rounded-2xl group-hover:rotate-12 transition-transform"><ZoomIn className="h-5 w-5 md:h-6 md:w-6" /></div>
               <div className="text-right">
                  <h4 className="font-black text-md md:text-lg">تصفح المنيو الورقي</h4>
                  <p className="text-[9px] md:text-[10px] opacity-80 uppercase font-black tracking-widest mt-1">
                    {allMenuImages.length === 1 ? 'عرض المنيو كاملاً' : `عرض ${allMenuImages.length} صفحات`}
                  </p>
               </div>
            </button>
          )}

          <div className="space-y-3 md:space-y-4">
             {restaurant.menu?.map(item => (
               <div key={item.id} className="bg-white p-4 md:p-5 rounded-[2rem] md:rounded-[2.5rem] shadow-sm border border-slate-100 flex justify-between items-center">
                  <div className="flex items-center gap-3 md:gap-4">
                     <div className="flex items-center gap-1.5 md:gap-2 bg-slate-50 p-1.5 md:p-2 rounded-xl md:rounded-2xl">
                        <button onClick={() => addToCart(item)} className="p-1.5 md:p-2 bg-emerald-500 text-white rounded-lg md:rounded-xl active:scale-75 transition-all"><Plus className="h-3.5 w-3.5 md:h-4 md:w-4" /></button>
                        <span className="font-black text-md md:text-lg w-5 md:w-6 text-center">{cart.find(i => i.id === item.id)?.quantity || 0}</span>
                        <button onClick={() => removeFromCart(item.id)} className="p-1.5 md:p-2 bg-rose-50 text-rose-500 rounded-lg md:rounded-xl active:scale-75 transition-all"><Trash className="h-3.5 w-3.5 md:h-4 md:w-4" /></button>
                     </div>
                     <div className="text-left"><p className="font-black text-emerald-600 text-sm md:text-base">{item.price} <span className="text-[10px] font-bold">ج.م</span></p></div>
                  </div>
                  <div className="text-right flex items-center gap-3 md:gap-4 flex-row-reverse text-right">
                     <div className="w-12 h-12 md:w-16 md:h-16 bg-slate-100 rounded-xl md:rounded-2xl overflow-hidden shrink-0 shadow-inner">
                        {item.photoURL ? <img src={item.photoURL} className="w-full h-full object-cover" /> : <UtensilsCrossed className="p-3 md:p-4 text-slate-200" />}
                     </div>
                     <div><p className="font-black text-slate-800 text-sm md:text-lg leading-tight">{item.name}</p></div>
                  </div>
               </div>
             ))}
          </div>
       </div>

       {cart.length > 0 && (
         <div className="p-6 md:p-8 bg-white border-t border-slate-100 pb-10 md:pb-12 shadow-2xl shrink-0">
            <div className="flex justify-between items-center mb-4 md:mb-6 px-2">
               <p className="text-xl md:text-2xl font-black text-slate-900">{total} <span className="text-[10px] opacity-40 uppercase">ج.م</span></p>
               <p className="text-[10px] md:text-xs font-black text-slate-400 uppercase tracking-widest">إجمالي الطلبات</p>
            </div>
            <button onClick={() => onCheckout(cart)} className="w-full bg-[#10b981] text-white py-5 md:py-7 rounded-[1.8rem] md:rounded-[2.5rem] font-black text-md md:text-lg shadow-2xl flex items-center justify-center gap-3 md:gap-4 active:scale-95 transition-all">
               <ShoppingBag className="h-5 w-5 md:h-6 md:w-6" /> تأكيد طلب الطعام
            </button>
         </div>
       )}
    </div>
  );
};

