                        </div>
                      </div>

                      <div className="space-y-3">
                        <VillageInput label="وجهة الوصول" helper="الوجهة النهائية" icon={<Check className="h-5 w-5 md:h-6 md:w-6" />} iconBg="bg-rose-500" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} />
                        <div className="bg-white border-2 border-slate-100 rounded-3xl p-4 flex items-start gap-3 shadow-sm focus-within:border-rose-200 transition-all">
                           <Info className="h-5 w-5 text-rose-500 mt-1 shrink-0" />
                           <input value={dropoffNotes} onChange={e => setDropoffNotes(e.target.value)} placeholder="تفاصيل وجهة الوصول (مثلاً: رقم الشقة أو المحل)" className="w-full bg-transparent text-sm font-bold outline-none text-right" dir="rtl" />
                        </div>
                      </div>
                   </div>

                   {/* تفضيلات الرحلة */}
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      {/* اختيار نوع المركبة */}
                      <div className="space-y-4">
                         <div className="flex items-center justify-between px-2">
                           <label className="label-strong">نوع المركبة</label>
                           <Zap className="h-4 w-4 text-amber-500" />
                         </div>
                         <div className="grid grid-cols-3 gap-2">
                            {[
                              {id: 'TOKTOK', label: 'توكتوك', icon: <Zap className="h-5 w-5" />},
                              {id: 'MOTORCYCLE', label: 'موتوسيكل', icon: <Bike className="h-5 w-5" />},
                              {id: 'CAR', label: 'سيارة', icon: <Car className="h-5 w-5" />}
                            ].map(v => (
                              <button key={v.id} onClick={() => setRideVehicleType(v.id as VehicleType)} className={`py-4 rounded-2xl flex flex-col items-center gap-1.5 transition-all border-2 ${rideVehicleType === v.id ? 'bg-emerald-50 border-emerald-500 text-emerald-600 shadow-md' : 'bg-white border-slate-100 text-slate-400'}`}>
                                 {v.icon}
                                 <span className="text-[9px] font-black uppercase tracking-widest">{v.label}</span>
                              </button>
                            ))}
                         </div>
                      </div>

                      {/* اختيار عدد الأفراد */}
                      <div className="space-y-4">
                         <div className="flex items-center justify-between px-2">
                           <label className="label-strong">عدد الأفراد</label>
                           <UsersIcon className="h-4 w-4 text-blue-500" />
                         </div>
                         <div className="bg-white border-2 border-slate-100 rounded-[1.8rem] p-4 flex items-center justify-between shadow-sm">
                            <button onClick={() => setPassengerCount(Math.min(4, passengerCount + 1))} className="p-3 bg-slate-50 rounded-xl hover:bg-emerald-50 text-slate-600 hover:text-emerald-600 transition-all"><Plus className="h-5 w-5" /></button>
                            <div className="flex flex-col items-center">
                               <span className="text-xl font-black text-slate-800">{passengerCount}</span>
                               <span className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">فرد</span>
                            </div>
                            <button onClick={() => setPassengerCount(Math.max(1, passengerCount - 1))} className="p-3 bg-slate-50 rounded-xl hover:bg-rose-50 text-slate-600 hover:text-rose-600 transition-all"><Minus className="h-5 w-5" /></button>
