                      <div onClick={() => { setActiveRestId(rest.id); itemFileRef.current?.click(); }} className="w-16 h-16 bg-white rounded-2xl border-2 border-dashed border-emerald-200 flex items-center justify-center cursor-pointer shrink-0 overflow-hidden">{activeRestId === rest.id && newItem.photoURL ? <img src={newItem.photoURL} className="w-full h-full object-cover" /> : <Camera className="h-6 w-6 text-emerald-300" />}</div>
                      <div className="flex-1 space-y-2"><input value={activeRestId === rest.id ? newItem.name : ''} onChange={e => { setActiveRestId(rest.id); setNewItem({...newItem, name: e.target.value}); }} placeholder="اسم الوجبة..." className="w-full bg-white p-3 rounded-xl text-xs font-bold outline-none text-right" dir="rtl" /><div className="flex gap-2"><input type="number" value={activeRestId === rest.id ? (newItem.price || '') : ''} onChange={e => { setActiveRestId(rest.id); setNewItem({...newItem, price: Number(e.target.value)}); }} placeholder="السعر" className="flex-1 bg-white p-3 rounded-xl text-xs font-bold outline-none text-right" dir="rtl" /><button onClick={() => addMenuItem(rest.id)} className="bg-emerald-600 text-white px-6 py-2 rounded-xl font-black text-[10px]">إضافة</button></div></div>
                      <input type="file" ref={itemFileRef} className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'ITEM')} />
                   </div>
                </div>
             </div>
           ))}
        </div>
      </div>
    </div>
  );
};

/**
 * طلبات المدفوعات
 */
const PaymentRequests: React.FC = () => {
  const [requests, setRequests] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  useEffect(() => {
    const q = query(collection(db, "payment_requests"), where("status", "==", "PENDING"));
    return onSnapshot(q, (snap) => setRequests(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })).sort((a, b) => b.createdAt - a.createdAt)));
  }, []);
  const handleApprove = async (req: any) => {
    if (!confirm('تم تحويل المبلغ؟')) return;
    setLoading(true);
    try {
      const batch = writeBatch(db);
      batch.update(doc(db, "payment_requests", req.id), { status: 'APPROVED', approvedAt: Date.now() });
      const userRef = doc(db, "users", req.userId);
      const userSnap = await getDoc(userRef);
      if (userSnap.exists()) {
        const cur = userSnap.data().wallet;
        batch.update(userRef, { "wallet.balance": cur.balance - req.amount, "wallet.withdrawn": cur.withdrawn + req.amount });
      }
      await batch.commit();
      alert('تمت الموافقة');
    } catch (e) { alert('خطأ'); } finally { setLoading(false); }
  };
  return (
    <div className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-xl space-y-8 animate-reveal text-right" dir="rtl">
       <div className="flex justify-between items-center mb-4 px-4"><h3 className="text-2xl font-black text-slate-900 flex items-center gap-4"><Banknote className="text-amber-500" /> طلبات السحب المعلقة</h3><span className="bg-amber-100 text-amber-700 px-6 py-2 rounded-full font-black text-[10px]">{requests.length} طلب جديد</span></div>
       <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {requests.map(req => (
            <div key={req.id} className="p-8 bg-slate-50 rounded-[3rem] border border-slate-100 flex flex-col gap-6 hover:border-emerald-500 transition-all">
               <div className="flex justify-between items-start"><div className="text-left"><p className="text-3xl font-black text-slate-950">{req.amount} <span className="text-xs opacity-30 font-bold">ج.م</span></p></div><div className="text-right"><p className="font-black text-lg text-slate-800">{req.userName}</p><p className="text-xs font-bold text-slate-400" dir="ltr">{req.userPhone}</p></div></div>
               <div className="flex gap-3"><button onClick={() => handleApprove(req)} disabled={loading} className="flex-[2] bg-emerald-600 text-white py-5 rounded-2xl font-black text-sm shadow-lg active:scale-95 flex items-center justify-center gap-3">{loading ? <Loader2 className="animate-spin" /> : <><Check className="h-5 w-5" /> موافقة وصرف</>}</button><button onClick={async () => { if(confirm('رفض الطلب؟')) await updateDoc(doc(db, "payment_requests", req.id), { status: 'REJECTED' }); }} className="flex-1 bg-rose-50 text-rose-500 py-5 rounded-2xl font-black text-sm">رفض</button></div>
            </div>
          ))}
          {requests.length === 0 && <div className="col-span-full py-20 text-center text-slate-300 font-bold bg-white border-4 border-dashed border-slate-50 rounded-[3rem]">لا توجد طلبات سحب حالياً</div>}
       </div>
    </div>
  );
};

/**
 * إجراءات جماعية
 */
const MassActions: React.FC<{ users: User[] }> = ({ users }) => {
  const pendingDrivers = users.filter(u => u.role === 'DRIVER' && u.status === 'PENDING_APPROVAL');
  const approveAll = async () => {
    if (pendingDrivers.length === 0) return;
    if (!confirm(`تفعيل ${pendingDrivers.length} كابتن دفعة واحدة؟`)) return;
    const batch = writeBatch(db);
    pendingDrivers.forEach(u => batch.update(doc(db, "users", u.id), { status: 'APPROVED' }));
    try { await batch.commit(); alert('تم التفعيل بنجاح'); } catch (e) { alert('فشل العملية'); }
  };
  return (
    <div className="bg-white p-8 rounded-[3.5rem] border border-slate-100 shadow-sm flex flex-col md:flex-row-reverse justify-between items-center gap-6">
       <div className="text-right">
          <h4 className="text-lg font-black text-slate-800">إجراءات سريعة</h4>
          <p className="text-xs font-bold text-slate-400">إدارة المحافظة دفعة واحدة</p>
       </div>
       <button onClick={approveAll} disabled={pendingDrivers.length === 0} className="bg-emerald-600 text-white px-10 py-5 rounded-[1.8rem] font-black text-xs shadow-xl active:scale-95 disabled:opacity-20 flex items-center gap-3">
         <CheckCircle className="h-4 w-4" /> تفعيل كافة الكباتن المعلقين ({pendingDrivers.length})
       </button>
    </div>
  );
};

