  // States for Ride
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [pickupNotes, setPickupNotes] = useState('');
  const [dropoffNotes, setDropoffNotes] = useState('');
  const [rideVehicleType, setRideVehicleType] = useState<VehicleType>('TOKTOK');

  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [showCustomFood, setShowCustomFood] = useState(false);
  const [customRestName, setCustomRestName] = useState('');
  const [customFoodNotes, setCustomFoodNotes] = useState('');

  const [pharmacyNotes, setPharmacyNotes] = useState('');
  const [prescriptionPhoto, setPrescriptionPhoto] = useState<string | null>(null);
  const fileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });
    return onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder]);

  const approxRidePrice = useMemo(() => {
    if (!pickupVillage || !dropoffVillage) return 0;
    const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
    const multiplier = DEFAULT_PRICING.multipliers[rideVehicleType] || 1;
    if (pickupVillage.id === dropoffVillage.id) return DEFAULT_PRICING.sameVillagePrice;
    return Math.max(Math.round((DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)) * multiplier), DEFAULT_PRICING.minPrice);
  }, [pickupVillage, dropoffVillage, rideVehicleType]);

  const handleCheckoutFood = async (cart: CartItem[], notes: string) => {
    if (!viewingRestaurant || !dropoffVillage) return alert('يرجى اختيار مكان التوصيل');
    setIsSubmitting(true);
    try {
      const dist = calculateDistance(viewingRestaurant.lat, viewingRestaurant.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const deliveryPrice = Math.max(Math.round(DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)), DEFAULT_PRICING.minPrice);
      const foodTotal = cart.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);

      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: 'FOOD',
        pickup: { address: viewingRestaurant.name, lat: viewingRestaurant.lat, lng: viewingRestaurant.lng, villageName: viewingRestaurant.address },
        dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'MOTORCYCLE',
        price: deliveryPrice + foodTotal, distance: dist, operatorId: 'op_main', zoneId: 'zone_main',
        paymentMethod: 'CASH', foodItems: cart, restaurantId: viewingRestaurant.id, restaurantName: viewingRestaurant.name,
        notes: notes.trim()
      });
      setViewingRestaurant(null);
    } catch(e) { alert('خطأ فني'); } finally { setIsSubmitting(false); }
  };

  const handleCustomFoodOrder = async () => {
    if (!dropoffVillage) return alert('يرجى اختيار مكان التوصيل');
    if (!customRestName.trim() || !customFoodNotes.trim()) return alert('يرجى إدخال اسم المطعم وطلبك');
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: 'FOOD',
        pickup: { address: customRestName, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: 'طلب يدوي' },
        dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'MOTORCYCLE',
        price: 0, distance: 0, operatorId: 'op_main', zoneId: 'zone_main', paymentMethod: 'CASH',
        notes: `مطعم: ${customRestName} - طلب: ${customFoodNotes}`, isCustomRequest: true
      });
      setCustomRestName(''); setCustomFoodNotes(''); setShowCustomFood(false);
      alert('تم إرسال طلبك! سيحدد الكابتن السعر في العرض.');
    } catch(e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  const handlePharmacyOrder = async () => {
    if (!dropoffVillage) return alert('يرجى اختيار مكان التوصيل');
    if (!pharmacyNotes.trim() && !prescriptionPhoto) return alert('يرجى كتابة الطلبات أو إرفاق صورة الروشتة');
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: 'PHARMACY',
        pickup: { address: 'أقرب صيدلية', lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: 'منطقة الصيدلية' },
        dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'MOTORCYCLE',
        price: DEFAULT_PRICING.minPrice + 10, distance: 1, operatorId: 'op_main', zoneId: 'zone_main',
        paymentMethod: 'CASH', notes: pharmacyNotes, prescriptionImage: prescriptionPhoto 
      });
      setPharmacyNotes(''); setPrescriptionPhoto(null);
    } catch(e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  const handlePrescriptionUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => setPrescriptionPhoto(event.target?.result as string);
    reader.readAsDataURL(file);
  };

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone,
        status: OrderStatus.ACCEPTED, acceptedAt: Date.now()
      });
    } catch (e) { alert('فشل قبول العرض'); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />
      {viewingRestaurant && <RestaurantMenu restaurant={viewingRestaurant} onClose={() => setViewingRestaurant(null)} onCheckout={handleCheckoutFood} />}

      <div className="rh-ui-panel no-scrollbar z-[100] translate-y-0 bg-slate-50">
        <div className="bottom-sheet-grabber lg:hidden"></div>
        <div className="p-6 md:p-12 space-y-8 md:space-y-10 pb-32 max-w-2xl mx-auto h-full overflow-y-auto no-scrollbar text-right">
          {!activeOrder ? (
            <>
              <div className="flex items-center justify-between">
                 <div><h2 className="text-3xl md:text-4xl font-black text-slate-950 tracking-tighter">وصـــلــهــا</h2><p className="text-slate-400 font-bold text-[10px] md:text-xs mt-1">توصيل المنوفية الذكي</p></div>
                 <button onClick={() => setAiOpen(true)} className="p-3.5 md:p-4 bg-emerald-50 text-emerald-600 rounded-2xl md:rounded-3xl shadow-sm"><Bot className="h-6 w-6 md:h-8 md:w-8" /></button>
              </div>
              <div className="grid grid-cols-3 gap-3 md:gap-4">
                  {[
                    { id: 'TAXI', label: 'مشوار', icon: <Bike className="h-6 w-6" /> },
                    { id: 'FOOD', label: 'أكل', icon: <UtensilsCrossed className="h-6 w-6" /> },
                    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill className="h-6 w-6" /> }
                  ].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`py-6 md:py-8 rounded-[1.5rem] md:rounded-[2.5rem] flex flex-col items-center gap-2 border-4 transition-all ${selectedCategory === cat.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-2xl scale-105' : 'bg-white border-transparent text-slate-400 opacity-60'}`}>
                       {cat.icon} <span className="text-[9px] md:text-[11px] font-black uppercase tracking-widest">{cat.label}</span>
                    </button>
                  ))}
              </div>

              {selectedCategory === 'FOOD' ? (
                <div className="space-y-6 md:space-y-8 animate-in zoom-in">
                   <VillageInput label="التوصيل إلى" helper="أين ستستلم طلبك؟" icon={<MapPin className="h-5 w-5" />} iconBg="bg-rose-500" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} />
                   {!showCustomFood ? (
                     <div className="grid grid-cols-1 gap-4 md:gap-6">
                        {restaurants.map(rest => (
                          <div key={rest.id} onClick={() => setViewingRestaurant(rest)} className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm flex flex-row-reverse justify-between items-center hover:border-emerald-500 transition-all cursor-pointer group active:scale-[0.98]">
                             <div className="flex items-center gap-3 flex-row-reverse text-right">
                                <div className="w-12 h-12 bg-slate-900 rounded-[1.2rem] flex items-center justify-center overflow-hidden shadow-lg">
                                   {rest.photoURL ? <img src={rest.photoURL} className="w-full h-full object-cover" /> : <UtensilsCrossed className="h-6 w-6 text-emerald-400" />}
                                </div>
                                <div><h4 className="text-lg font-black text-slate-800 leading-tight">{rest.name}</h4><p className="text-[9px] font-bold text-slate-400">{rest.category}</p></div>
                             </div>
                             <ChevronRight className="h-5 w-5 text-slate-300 rotate-180 group-hover:text-emerald-500 transition-colors" />
                          </div>
                        ))}
                        <button onClick={() => setShowCustomFood(true)} className="bg-white p-6 rounded-[2rem] border-2 border-dashed border-slate-200 shadow-sm flex flex-row-reverse items-center gap-4 hover:border-emerald-400 active:scale-95 transition-all">
                           <div className="bg-emerald-50 p-4 rounded-2xl text-emerald-600"><Store className="h-6 w-6" /></div>
                           <div className="text-right"><h4 className="font-black text-slate-800">مطعمك مش موجود؟</h4><p className="text-[10px] font-bold text-slate-400">اطلب من أي مطعم آخر يدوياً</p></div>
                        </button>
                     </div>
                   ) : (
                     <div className="space-y-6 animate-in slide-in-from-bottom">
                        <div className="bg-emerald-50 p-6 rounded-[2rem] border border-emerald-100 flex items-center justify-between">
                           <button onClick={() => setShowCustomFood(false)} className="text-emerald-600 font-black text-xs">إلغاء</button>
                           <h4 className="font-black text-emerald-900 text-sm">طلب مطعم خاص</h4>
                        </div>
                        <input value={customRestName} onChange={e => setCustomRestName(e.target.value)} placeholder="اسم المطعم" className="w-full bg-white border-2 border-slate-100 rounded-2xl p-5 font-bold outline-none text-right shadow-sm focus:border-emerald-500 transition-all" dir="rtl" />
                        <textarea value={customFoodNotes} onChange={e => setCustomFoodNotes(e.target.value)} placeholder="اكتب طلباتك هنا..." className="w-full bg-white border-2 border-slate-100 rounded-2xl p-5 font-bold outline-none text-right shadow-sm focus:border-emerald-500 transition-all min-h-[120px]" dir="rtl" />
                        <button onClick={handleCustomFoodOrder} disabled={isSubmitting} className="w-full bg-slate-950 text-white py-6 rounded-3xl font-black shadow-xl active:scale-95 transition-all">{isSubmitting ? <Loader2 className="h-6 w-6 animate-spin mx-auto" /> : 'إرسال الطلب'}</button>
                     </div>
                   )}
                </div>
              ) : selectedCategory === 'PHARMACY' ? (
                <div className="space-y-6 md:space-y-8 animate-in zoom-in">
                   <div className="bg-sky-50 border-2 border-sky-100 p-6 rounded-[2rem] text-center space-y-2">
                      <Pill className="h-10 w-10 text-sky-600 mx-auto" />
                      <h3 className="text-lg font-black text-sky-900">طلب أدوية</h3>
                   </div>
                   <VillageInput label="مكان التوصيل" helper="أين ستستلم الدواء؟" icon={<MapPin className="h-5 w-5" />} iconBg="bg-sky-600" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} />
                   <textarea value={pharmacyNotes} onChange={e => setPharmacyNotes(e.target.value)} placeholder="اكتب أسماء الأدوية..." dir="rtl" className="w-full bg-white border-2 border-slate-100 rounded-[1.5rem] p-5 text-sm font-bold outline-none focus:border-sky-500 min-h-[100px] shadow-sm" />
                   <div onClick={() => fileRef.current?.click()} className="w-full h-28 bg-white border-2 border-dashed border-slate-200 rounded-[1.5rem] flex flex-col items-center justify-center cursor-pointer overflow-hidden relative">
                      {prescriptionPhoto ? <img src={prescriptionPhoto} className="w-full h-full object-cover" /> : <><Plus className="h-6 w-6 text-slate-300 mb-1" /><span className="text-[9px] font-black text-slate-400">ارفق صورة الروشتة</span></>}
                      <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={handlePrescriptionUpload} />
                   </div>
                   <button onClick={handlePharmacyOrder} disabled={isSubmitting} className="w-full bg-sky-600 text-white py-6 rounded-[2rem] font-black shadow-2xl active:scale-95 flex items-center justify-center gap-3">
                      {isSubmitting ? <Loader2 className="animate-spin h-6 w-6" /> : <>إرسال طلب الصيدلية <FileText className="h-5 w-5" /></>}
                   </button>
                </div>
              ) : (
                <div className="space-y-6 md:space-y-10 animate-in slide-in-from-right">
                   <div className="space-y-6">
                      <VillageInput label="نقطة الانطلاق" helper="موقع استلامك" icon={<MapPin className="h-5 w-5" />} iconBg="bg-emerald-500" selectedVillage={pickupVillage} onSelect={setPickupVillage} />
                      <input value={pickupNotes} onChange={e => setPickupNotes(e.target.value)} placeholder="تفاصيل موقع الاستلام (مثلاً: بجوار صيدلية كذا)" className="w-full bg-white border-2 border-slate-100 rounded-3xl p-4 text-sm font-bold outline-none text-right shadow-sm" dir="rtl" />
                      <VillageInput label="وجهة الوصول" helper="الوجهة النهائية" icon={<Check className="h-5 w-5" />} iconBg="bg-rose-500" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} />
                      <input value={dropoffNotes} onChange={e => setDropoffNotes(e.target.value)} placeholder="تفاصيل وجهة الوصول (رقم الشقة أو اسم المحل)" className="w-full bg-white border-2 border-slate-100 rounded-3xl p-4 text-sm font-bold outline-none text-right shadow-sm" dir="rtl" />
                   </div>
                   <div className="grid grid-cols-3 gap-2">
                      {[
                        {id: 'TOKTOK', label: 'توكتوك', icon: <Zap className="h-5 w-5" />},
                        {id: 'MOTORCYCLE', label: 'موتوسيكل', icon: <Bike className="h-5 w-5" />},
                        {id: 'CAR', label: 'سيارة', icon: <Car className="h-5 w-5" />}
                      ].map(v => (
                        <button key={v.id} onClick={() => setRideVehicleType(v.id as VehicleType)} className={`py-4 rounded-2xl flex flex-col items-center gap-1.5 transition-all border-2 ${rideVehicleType === v.id ? 'bg-emerald-50 border-emerald-500 text-emerald-600 shadow-md' : 'bg-white border-slate-100 text-slate-400'}`}>
                           {v.icon}<span className="text-[9px] font-black">{v.label}</span>
                        </button>
                      ))}
                   </div>
                   {approxRidePrice > 0 && (
                     <div className="bg-emerald-50 p-6 rounded-[2rem] border-2 border-emerald-100 flex justify-between items-center animate-in fade-in">
                        <p className="text-2xl font-black text-emerald-700">{approxRidePrice} <span className="text-xs">ج.م</span></p>
                        <p className="text-[9px] font-black text-emerald-600 uppercase">السعر التقريبي للمشوار</p>
                     </div>
                   )}
                   <button onClick={async () => {
                     if(!pickupVillage || !dropoffVillage) return alert('يرجى اختيار النقطتين');
                     setIsSubmitting(true);
                     try {
                        const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
                        await addDoc(collection(db, "orders"), {
                           customerId: user.id, customerPhone: user.phone, category: 'TAXI',
                           pickup: { address: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng, villageName: pickupVillage.name },
                           dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
                           pickupNotes: pickupNotes.trim(), dropoffNotes: dropoffNotes.trim(),
                           status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), 
                           requestedVehicleType: rideVehicleType, price: approxRidePrice, distance: dist,
                           operatorId: 'op_main', zoneId: 'zone_main', paymentMethod: 'CASH'
                        });
                        setPickupNotes(''); setDropoffNotes('');
                     } catch(e) { alert('خطأ'); } finally { setIsSubmitting(false); }
                   }} disabled={!pickupVillage || !dropoffVillage || isSubmitting} className="w-full bg-slate-950 text-white py-6 md:py-8 rounded-[2rem] font-black text-xl shadow-2xl active:scale-95 transition-all">
                      {isSubmitting ? <Loader2 className="animate-spin h-8 w-8" /> : 'اطلب الآن'}
                   </button>
                </div>
              )}
            </>
          ) : (
            <div className="space-y-8">
               {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                 <div className="animate-in zoom-in space-y-10 text-center">
                    <Navigation2 className="h-16 w-16 text-emerald-600 animate-pulse mx-auto" />
                    <h2 className="text-2xl font-black">جاري جلب كباتن متاحين...</h2>
                    <div className="space-y-4">
                       {incomingOffers.map(offer => (
                         <div key={offer.id} className="bg-white p-6 rounded-[2.5rem] border-4 border-slate-50 shadow-xl flex justify-between items-center">
                            <div className="text-center">
                               <p className="text-2xl font-black text-emerald-700">{offer.price} ج.م</p>
                               <button onClick={() => handleAcceptOffer(offer)} className="bg-emerald-600 text-white px-6 py-2 rounded-xl font-black text-xs">قبول</button>
                            </div>
                            <div className="flex items-center gap-3 flex-row-reverse text-right">
                               <div className="w-12 h-12 bg-slate-900 text-emerald-400 rounded-xl flex items-center justify-center font-black">{(offer.driverName || 'ك')[0]}</div>
                               <div><p className="font-black text-slate-900">{offer.driverName}</p><div className="flex items-center gap-1.5 text-amber-500 font-black text-xs">{offer.driverRating} <Star className="h-3 w-3 fill-amber-400" /></div></div>
                            </div>
                         </div>
                       ))}
                    </div>
                    <button onClick={() => updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED })} className="text-rose-500 font-black text-xs uppercase hover:underline">إلغاء الطلب</button>
                 </div>
               ) : (
                 <div className="animate-in zoom-in space-y-8 text-center">
                    <div className="bg-emerald-600 p-6 rounded-[2.5rem] text-white flex justify-between items-center shadow-2xl">
                       <div className="text-right"><p className="text-[10px] font-black opacity-60 uppercase mb-1">تتبع الطلب</p><h3 className="text-xl font-black">الكابتن في طريقه إليك</h3></div>
                       <Navigation2 className="h-6 w-6 animate-bounce" />
                    </div>
                    <div className="w-24 h-24 bg-slate-100 rounded-[2.5rem] mx-auto flex items-center justify-center border-4 border-white shadow-2xl font-black text-3xl text-slate-300">{(activeOrder.driverName || 'ك')[0]}</div>
                    <h4 className="text-2xl font-black">{activeOrder.driverName}</h4>
                    <div className="grid grid-cols-2 gap-3">
                       <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-900 text-white py-6 rounded-3xl font-black text-md flex items-center justify-center gap-3 shadow-2xl active:scale-95"><PhoneCall className="h-6 w-6" /> اتصال</a>
                       <button onClick={() => setShowChat(true)} className="bg-white border-4 border-slate-100 text-slate-900 py-6 rounded-3xl font-black text-md flex items-center justify-center gap-3 relative"><MessageCircle className="h-6 w-6" /> محادثة</button>
                    </div>
                 </div>
               )}
            </div>
          )}
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-2xl border-t border-slate-100 px-6 py-4 flex justify-around items-center z-[150] shadow-2xl flex-row-reverse">
         {[
           {id: 'NEW', icon: <Plus className="h-6 w-6" />, label: 'طلب'},
           {id: 'ACTIVITY', icon: <History className="h-6 w-6" />, label: 'نشاطي'},
           {id: 'PROFILE', icon: <UserIcon className="h-6 w-6" />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-1.5 transition-all ${activeView === tab.id ? 'text-emerald-600 scale-110' : 'text-slate-300'}`}>
              <div className={`p-2.5 rounded-xl ${activeView === tab.id ? 'bg-emerald-50' : ''}`}>{tab.icon}</div>
              <span className="text-[8px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;

import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order, Restaurant, MenuItem, UserRole, UserStatus, VehicleType, Zone, Village, District } from '../types';
import { OrderStatus } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Services
import { db } from '../services/firebase';
import { 
  collection, query, doc, onSnapshot, orderBy, 
  setDoc, updateDoc, deleteDoc, limit, where, writeBatch, getDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Icons
import { 
  LayoutDashboard, Users2, UtensilsCrossed, MapPin, 
  TrendingUp, Bike, Search, X, Camera, Building2, 
  Trash2, CheckCircle, Smartphone, Loader2, DollarSign, 
  Zap, Settings2, Save, AlertTriangle, Globe, ChevronDown, 
  Building, Landmark, Navigation, ShieldCheck, User as UserIcon,
  Car, ShieldAlert, Banknote, PlusCircle, MoreVertical,
  PhoneCall, MessageCircle, Clock, Eye, Filter, ArrowLeft,
  UserCheck, UserX, Package, Map as MapIcon, Info
} from 'lucide-react';

/**
 * مكون التعديل الكامل لبيانات المستخدم
 */
const UserFullEditor: React.FC<{ user: User, onClose: () => void }> = ({ user, onClose }) => {
  const [name, setName] = useState(user.name || '');
  const [phone, setPhone] = useState(user.phone || '');
  const [status, setStatus] = useState<UserStatus>(user.status);
  const [role, setRole] = useState<UserRole>(user.role);
  const [vehicleType, setVehicleType] = useState<VehicleType>(user.vehicleType || 'TOKTOK');
  const [loading, setLoading] = useState(false);

  const handleSave = async () => {
    if (!name.trim() || !phone.trim()) {
      alert('يرجى ملء كافة البيانات الأساسية');
      return;
    }
    setLoading(true);
    try {
      const updates: any = {
        name: name.trim(),
        phone: phone.trim(),
        status,
        role,
        vehicleType: role === 'DRIVER' ? vehicleType : null
      };
      await updateDoc(doc(db, "users", user.id), updates);
      alert('تم تحديث بيانات المستخدم بنجاح');
      onClose();
    } catch (e) { 
      alert('فشل التحديث'); 
    } finally { 
      setLoading(false); 
    }
  };

  return (
    <div className="fixed inset-0 z-[10000] bg-slate-950/70 backdrop-blur-md flex items-center justify-center p-4 animate-in fade-in">
      <div className="bg-white w-full max-w-xl rounded-[3.5rem] p-10 flex flex-col max-h-[90vh] shadow-2xl overflow-y-auto no-scrollbar border border-white/20 text-right" dir="rtl">
        <div className="flex justify-between items-center mb-8 px-2">
           <div className="flex items-center gap-4">
              <div className="bg-slate-900 text-emerald-400 p-4 rounded-2xl shadow-xl"><Settings2 className="h-6 w-6" /></div>
              <div>
                 <h3 className="text-2xl font-black text-slate-800 tracking-tight">إدارة حساب المستخدم</h3>
                 <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">تعديل كافة الصلاحيات والبيانات</p>
              </div>
           </div>
           <button onClick={onClose} className="p-4 bg-slate-50 text-slate-400 rounded-2xl hover:bg-rose-50 hover:text-rose-500 transition-all"><X className="h-6 w-6" /></button>
        </div>

        <div className="space-y-8 pb-10">
           <div className="flex justify-center">
              <div className="w-24 h-24 bg-slate-50 rounded-[2.5rem] border-4 border-white shadow-xl flex items-center justify-center overflow-hidden">
                {user.photoURL ? <img src={user.photoURL} className="w-full h-full object-cover" /> : <UserIcon className="h-10 w-10 text-slate-200" />}
              </div>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">الاسم الرباعي</label>
                 <div className="relative">
                    <UserIcon className="absolute right-5 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-300" />
                    <input value={name} onChange={e => setName(e.target.value)} className="w-full bg-slate-50 rounded-2xl p-5 pr-14 font-black text-sm outline-none border-2 border-transparent focus:border-emerald-500 transition-all" />
                 </div>
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">رقم الموبايل</label>
                 <div className="relative">
                    <Smartphone className="absolute right-5 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-300" />
                    <input value={phone} onChange={e => setPhone(e.target.value)} className="w-full bg-slate-50 rounded-2xl p-5 pr-14 font-black text-sm outline-none border-2 border-transparent focus:border-emerald-500 transition-all text-left" dir="ltr" />
                 </div>
              </div>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">نوع الحساب (الدور)</label>
                 <div className="relative">
                    <ShieldCheck className="absolute right-5 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-300" />
                    <select value={role} onChange={(e) => setRole(e.target.value as UserRole)} className="w-full bg-slate-50 rounded-2xl p-5 pr-14 font-black text-sm outline-none border-2 border-transparent focus:border-emerald-500 transition-all appearance-none cursor-pointer">
                      <option value="CUSTOMER">عميل (Customer)</option>
                      <option value="DRIVER">كابتن (Driver)</option>
                      <option value="OPERATOR">مشغل مركزي (Operator)</option>
                      <option value="ADMIN">مدير نظام (Admin)</option>
                    </select>
                    <ChevronDown className="absolute left-5 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-300 pointer-events-none" />
                 </div>
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">الحالة الحالية</label>
                 <div className="relative">
                    <ShieldAlert className="absolute right-5 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-300" />
                    <select value={status} onChange={(e) => setStatus(e.target.value as UserStatus)} className="w-full bg-slate-50 rounded-2xl p-5 pr-14 font-black text-sm outline-none border-2 border-transparent focus:border-rose-500 transition-all appearance-none cursor-pointer">
                      <option value="APPROVED">مفعل (Approved)</option>
                      <option value="PENDING_APPROVAL">قيد المراجعة (Pending)</option>
                      <option value="SUSPENDED">محظور نهائياً (Suspended)</option>
                    </select>
                    <ChevronDown className="absolute left-5 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-300 pointer-events-none" />
                 </div>
              </div>
           </div>

           {role === 'DRIVER' && (
              <div className="space-y-2 animate-in zoom-in">
                 <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">نوع المركبة المعتمد</label>
                 <div className="grid grid-cols-3 gap-3">
                    {[
                      { id: 'TOKTOK', label: 'توكتوك', icon: <Zap className="h-4 w-4" /> },
                      { id: 'MOTORCYCLE', label: 'موتوسيكل', icon: <Bike className="h-4 w-4" /> },
                      { id: 'CAR', label: 'سيارة', icon: <Car className="h-4 w-4" /> }
                    ].map(v => (
                      <button 
                        key={v.id}
                        type="button"
                        onClick={() => setVehicleType(v.id as VehicleType)}
                        className={`p-5 rounded-2xl flex flex-col items-center gap-2 border-2 transition-all ${vehicleType === v.id ? 'bg-emerald-50 border-emerald-500 text-emerald-600 shadow-lg' : 'bg-slate-50 border-transparent text-slate-400'}`}
                      >
                         {v.icon}
                         <span className="text-[10px] font-black">{v.label}</span>
                      </button>
                    ))}
                 </div>
              </div>
           )}
        </div>

        <div className="flex gap-4 sticky bottom-0 bg-white pt-4 border-t border-slate-100">
           <button onClick={onClose} className="flex-1 py-6 rounded-3xl font-black text-sm text-slate-400 hover:bg-slate-50 transition-all">إلغاء</button>
           <button onClick={handleSave} disabled={loading} className="flex-[2] bg-slate-950 text-white py-6 rounded-3xl font-black text-sm shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3">
             {loading ? <Loader2 className="animate-spin h-6 w-6" /> : <><Save className="h-5 w-5" /> حفظ التعديلات</>}
           </button>
        </div>
      </div>
    </div>
  );
};

/**
 * مركز مراقبة الطلبات والمشاوير للسوبر أدمن
 */
const OrdersMonitor: React.FC<{ orders: Order[] }> = ({ orders }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filter, setFilter] = useState<'ALL' | 'ACTIVE' | 'DONE' | 'CANCELLED'>('ALL');

  const filtered = orders.filter(o => {
    const matchesSearch = 
      o.customerPhone.includes(searchTerm) || 
      (o.driverName || '').includes(searchTerm) ||
      o.id.includes(searchTerm);

    const isLive = ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status);
    const isDone = [OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED].includes(o.status);
    const isCancelled = o.status === OrderStatus.CANCELLED;

    if (filter === 'ACTIVE') return matchesSearch && isLive;
    if (filter === 'DONE') return matchesSearch && isDone;
    if (filter === 'CANCELLED') return matchesSearch && isCancelled;
    return matchesSearch;
  });

  const getStatusColor = (status: OrderStatus) => {
    switch(status) {
      case OrderStatus.DELIVERED:
      case OrderStatus.DELIVERED_RATED: return 'bg-emerald-100 text-emerald-600';
      case OrderStatus.CANCELLED: return 'bg-rose-100 text-rose-600';
      case OrderStatus.WAITING_FOR_OFFERS: return 'bg-amber-100 text-amber-600 animate-pulse';
      default: return 'bg-blue-100 text-blue-600';
    }
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-bottom duration-700 text-right" dir="rtl">
       <div className="bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
          <div className="flex items-center gap-5">
             <div className="bg-slate-900 p-5 rounded-[2.2rem] text-emerald-400 shadow-2xl shadow-slate-200">
                <Package className="h-10 w-10 animate-float" />
             </div>
             <div>
                <h3 className="text-3xl font-black text-slate-900 tracking-tighter leading-none">مركز مراقبة العمليات</h3>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-2">متابعة لحظية لكافة مشاوير وطلبات المنوفية</p>
             </div>
          </div>
          <div className="flex gap-2 bg-slate-50 p-2 rounded-[2rem] shadow-inner overflow-x-auto no-scrollbar">
             {[
               { id: 'ALL', label: 'الكل', icon: <LayoutDashboard className="h-4 w-4" /> },
               { id: 'ACTIVE', label: 'نشط الآن', icon: <Zap className="h-4 w-4" /> },
               { id: 'DONE', label: 'مكتمل', icon: <CheckCircle className="h-4 w-4" /> },
               { id: 'CANCELLED', label: 'ملغي', icon: <XCircle className="h-4 w-4" /> }
             ].map(t => (
               <button key={t.id} onClick={() => setFilter(t.id as any)} className={`px-8 py-3.5 rounded-[1.5rem] text-[11px] font-black transition-all flex items-center gap-2 whitespace-nowrap ${filter === t.id ? 'bg-slate-900 text-white shadow-xl' : 'text-slate-400 hover:text-slate-600'}`}>
                 {t.icon} {t.label}
               </button>
             ))}
          </div>
       </div>

       <div className="relative group max-w-2xl mx-auto">
          <Search className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5" />
          <input 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)}
            placeholder="بحث برقم الموبايل، اسم الكابتن، أو كود الطلب..." 
            className="w-full bg-white border-2 border-slate-50 rounded-[2.5rem] py-6 pr-14 pl-8 font-black text-sm outline-none focus:border-emerald-500 shadow-sm transition-all" 
          />
       </div>

       <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          {filtered.map((order, idx) => (
            <div key={order.id} className="bg-white rounded-[4rem] border border-slate-50 shadow-2xl overflow-hidden group hover:border-emerald-500 transition-all animate-reveal" style={{animationDelay: `${idx * 0.05}s`}}>
               <div className="bg-slate-50 p-8 flex justify-between items-center group-hover:bg-slate-950 group-hover:text-white transition-all">
                  <div className="text-right">
                    <p className="text-[10px] font-black opacity-40 uppercase tracking-tighter mb-1">كود العملية: #{order.id.slice(-6)}</p>
                    <p className="text-3xl font-black">{order.price} <span className="text-xs opacity-40 font-bold">ج.م</span></p>
                  </div>
                  <div className={`px-5 py-2 rounded-full text-[9px] font-black uppercase tracking-widest ${getStatusColor(order.status)}`}>
                     {order.status}
                  </div>
               </div>

               <div className="p-10 space-y-10">
                  {/* مسار الرحلة */}
                  <div className="space-y-6">
                     <div className="flex gap-6 items-start flex-row-reverse">
                        <div className="bg-emerald-50 p-4 rounded-2xl text-emerald-600 shadow-sm shrink-0"><MapPin className="h-6 w-6" /></div>
                        <div className="flex-1">
                           <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">المسار والمواقع</p>
                           <p className="text-lg font-black text-slate-800 leading-tight">
                              {order.pickup?.villageName} <span className="text-emerald-500 mx-2">←</span> {order.dropoff?.villageName}
                           </p>
                        </div>
                     </div>
                  </div>

                  {/* بيانات الأطراف */}
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-6 border-t border-slate-100">
                     <div className="bg-slate-50 p-6 rounded-[2.5rem] space-y-4">
                        <p className="text-[9px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2 flex-row-reverse">العميل <UserIcon className="h-3 w-3" /></p>
                        <div>
                           <p className="font-black text-slate-800 text-sm">{order.customerPhone}</p>
                           <div className="flex gap-2 mt-4">
                              <a href={`tel:${order.customerPhone}`} className="bg-white p-3 rounded-xl text-slate-400 hover:text-emerald-600 shadow-sm transition-all"><PhoneCall className="h-4 w-4" /></a>
                              <a href={`https://wa.me/2${order.customerPhone}`} target="_blank" className="bg-white p-3 rounded-xl text-slate-400 hover:text-emerald-600 shadow-sm transition-all"><MessageCircle className="h-4 w-4" /></a>
                           </div>
                        </div>
                     </div>

                     <div className="bg-slate-50 p-6 rounded-[2.5rem] space-y-4 border-2 border-transparent hover:border-emerald-200 transition-all">
                        <p className="text-[9px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2 flex-row-reverse">الكابتن <Bike className="h-3 w-3" /></p>
                        {order.driverId ? (
                           <div>
                              <p className="font-black text-slate-800 text-sm leading-none mb-1">{order.driverName}</p>
                              <p className="text-[10px] font-bold text-slate-400" dir="ltr">{order.driverPhone}</p>
                              <div className="flex gap-2 mt-4">
                                 <a href={`tel:${order.driverPhone}`} className="bg-white p-3 rounded-xl text-slate-400 hover:text-emerald-600 shadow-sm transition-all"><PhoneCall className="h-4 w-4" /></a>
                                 <a href={`https://wa.me/2${order.driverPhone}`} target="_blank" className="bg-white p-3 rounded-xl text-slate-400 hover:text-emerald-600 shadow-sm transition-all"><MessageCircle className="h-4 w-4" /></a>
                              </div>
                           </div>
                        ) : (
                           <div className="flex items-center gap-2 text-amber-500">
                              <AlertTriangle className="h-4 w-4" />
                              <span className="text-[10px] font-black">بانتظار قبول كابتن</span>
                           </div>
                        )}
                     </div>
                  </div>

                  {/* ملاحظات إضافية */}
                  {(order.pickupNotes || order.notes) && (
                    <div className="bg-amber-50 p-6 rounded-[2rem] border border-amber-100 flex gap-4 items-start flex-row-reverse">
                       <Info className="h-5 w-5 text-amber-500 shrink-0 mt-1" />
                       <div className="text-right">
                          <p className="text-[9px] font-black text-amber-600 uppercase mb-1">ملاحظات العميل</p>
                          <p className="text-xs font-bold text-amber-900 leading-relaxed">{order.pickupNotes || order.notes}</p>
                       </div>
                    </div>
                  )}

                  <div className="flex justify-between items-center pt-4">
                     <p className="text-[9px] font-black text-slate-300 uppercase tracking-[0.3em]">{new Date(order.createdAt).toLocaleString('ar-EG')}</p>
                     <div className="flex gap-3">
                        <button onClick={() => { if(confirm('هل تريد إلغاء هذا الطلب من النظام؟')) updateDoc(doc(db, "orders", order.id), { status: OrderStatus.CANCELLED }); }} className="text-rose-500 hover:bg-rose-50 px-4 py-2 rounded-xl text-[10px] font-black transition-all">إلغاء الطلب</button>
                     </div>
                  </div>
               </div>
            </div>
          ))}

          {filtered.length === 0 && (
            <div className="col-span-full py-40 text-center bg-white rounded-[4rem] border-4 border-dashed border-slate-50 space-y-6">
               <div className="bg-slate-50 w-24 h-24 rounded-full flex items-center justify-center mx-auto animate-pulse">
                  <Search className="h-10 w-10 text-slate-200" />
               </div>
               <p className="text-slate-300 font-black text-xl tracking-tight">لا يوجد نتائج للبحث الحالي في المنوفية</p>
            </div>
          )}
       </div>
    </div>
  );
};

const SuperAdminDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'STATS' | 'USERS' | 'ORDERS' | 'RESTAURANTS' | 'PAYMENTS' | 'ZONES'>('STATS');
  const [users, setUsers] = useState<User[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingUser, setEditingUser] = useState<User | null>(null);

  useEffect(() => {
    const unsubUsers = onSnapshot(collection(db, "users"), (snap) => setUsers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as User[]));
    const unsubOrders = onSnapshot(query(collection(db, "orders"), orderBy("createdAt", "desc"), limit(200)), (snap) => setOrders(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[]));
    return () => { unsubUsers(); unsubOrders(); };
  }, []);

  const filteredUsers = users.filter(u => u.name?.toLowerCase().includes(searchTerm.toLowerCase()) || u.phone?.includes(searchTerm));

  return (
    <div className="max-w-7xl mx-auto space-y-10 pb-40 p-6 animate-in fade-in duration-700">
      {editingUser && <UserFullEditor user={editingUser} onClose={() => setEditingUser(null)} />}

      <div className="bg-white/80 p-4 rounded-[2.5rem] shadow-xl border border-white flex gap-2 overflow-x-auto no-scrollbar sticky top-4 z-[500] backdrop-blur-2xl">
        {[
          { id: 'STATS', label: 'الرئيسية', icon: <LayoutDashboard className="h-4 w-4" /> },
          { id: 'USERS', label: 'الأعضاء', icon: <Users2 className="h-4 w-4" /> },
          { id: 'ORDERS', label: 'الطلبات', icon: <Package className="h-4 w-4" /> },
          { id: 'RESTAURANTS', label: 'المطاعم', icon: <UtensilsCrossed className="h-4 w-4" /> },
          { id: 'PAYMENTS', label: 'المدفوعات', icon: <Banknote className="h-4 w-4" /> },
          { id: 'ZONES', label: 'إدارة المنوفية', icon: <Globe className="h-4 w-4" /> },
        ].map(tab => (
          <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex items-center gap-3 px-10 py-5 rounded-[1.8rem] text-[11px] font-black transition-all whitespace-nowrap active:scale-95 ${activeTab === tab.id ? 'bg-slate-950 text-white shadow-2xl' : 'text-slate-400 hover:text-slate-950'}`}>
            {tab.icon} {tab.label}
          </button>
        ))}
      </div>

      {activeTab === 'STATS' && (
        <div className="space-y-10 text-right" dir="rtl">
           <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              <div className="bg-emerald-600 p-10 rounded-[3.5rem] text-white shadow-2xl relative overflow-hidden group animate-reveal"><TrendingUp className="absolute -bottom-4 -left-4 h-32 w-32 opacity-10" /><p className="text-[10px] font-black opacity-60 uppercase mb-3">سيولة المنظومة</p><h3 className="text-5xl font-black">{users.reduce((acc, curr) => acc + (curr.wallet?.balance || 0), 0).toLocaleString()} <span className="text-sm opacity-40 font-bold">ج.م</span></h3></div>
              <div className="bg-slate-900 p-10 rounded-[3.5rem] text-white shadow-2xl animate-reveal" style={{animationDelay: '0.1s'}}><p className="text-[10px] font-black opacity-40 uppercase mb-3">إجمالي الرحلات</p><h3 className="text-5xl font-black">{orders.length}</h3></div>
              <div className="bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-xl animate-reveal" style={{animationDelay: '0.2s'}}><p className="text-[10px] font-black text-slate-400 uppercase mb-3">كباتن المنوفية</p><h3 className="text-5xl font-black text-emerald-600">{users.filter(u => u.role === 'DRIVER').length}</h3></div>
              <div className="bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-xl animate-reveal" style={{animationDelay: '0.3s'}}><p className="text-[10px] font-black text-slate-400 uppercase mb-3">إجمالي العملاء</p><h3 className="text-5xl font-black text-slate-900">{users.filter(u => u.role === 'CUSTOMER').length}</h3></div>
           </div>
        </div>
      )}

      {activeTab === 'ORDERS' && <OrdersMonitor orders={orders} />}

      {activeTab === 'USERS' && (
        <div className="bg-white p-12 rounded-[4rem] border border-slate-100 shadow-2xl space-y-10 animate-reveal text-right" dir="rtl">
           <div className="relative group"><Search className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-300" /><input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="بحث باسم المستخدم أو رقم الموبايل..." className="w-full bg-slate-50 border-none rounded-[2rem] py-6 pr-14 pl-8 font-black text-sm outline-none text-right shadow-inner" dir="rtl" /></div>
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredUsers.map((u, index) => (
                <div key={u.id} style={{animationDelay: `${index * 0.05}s`}} className="p-8 bg-slate-50 rounded-[3rem] border-2 border-transparent hover:border-emerald-500 hover:bg-white hover:shadow-2xl transition-all group flex flex-col items-center text-center relative overflow-hidden animate-reveal">
