const RestaurantEditor: React.FC = () => {
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [loading, setLoading] = useState(false);
  const [restData, setRestData] = useState({ name: '', category: 'مشويات', photoURL: '', menuImageURL: '' });
  const [newItem, setNewItem] = useState({ name: '', price: 0, photoURL: '' });
  const [activeRestId, setActiveRestId] = useState<string | null>(null);
  const itemFileRef = useRef<HTMLInputElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    return onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });
  }, []);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, target: 'PHOTO' | 'ITEM') => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64 = reader.result as string;
      if (target === 'PHOTO') setRestData(prev => ({ ...prev, photoURL: base64 }));
      if (target === 'ITEM') setNewItem(prev => ({ ...prev, photoURL: base64 }));
    };
    reader.readAsDataURL(file);
  };

  const saveRestaurant = async () => {
    if (!restData.name) return;
    setLoading(true);
    try {
      const id = `rest_${Date.now()}`;
      await setDoc(doc(db, "restaurants", id), {
        ...restData, id, menu: [], isOpen: true, address: 'المنوفية', lat: 30.5, lng: 31.0
      });
      setIsAdding(false);
      setRestData({ name: '', category: 'مشويات', photoURL: '', menuImageURL: '' });
    } catch (e) { alert('خطأ'); } finally { setLoading(false); }
  };

  const addMenuItem = async (rid: string) => {
    if (!newItem.name || newItem.price <= 0) return;
    const rest = restaurants.find(r => r.id === rid);
    if (!rest) return;
    const menu = [...(rest.menu || []), { ...newItem, id: `item_${Date.now()}` }];
    await updateDoc(doc(db, "restaurants", rid), { menu });
    setNewItem({ name: '', price: 0, photoURL: '' });
  };

  return (
    <div className="space-y-8 animate-reveal text-right" dir="rtl">
      <div className="bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-xl">
        <div className="flex justify-between items-center mb-10 px-4">
           <h3 className="text-2xl font-black text-slate-900 flex items-center gap-4"><UtensilsCrossed className="text-emerald-500" /> إدارة المطاعم</h3>
           <button onClick={() => setIsAdding(!isAdding)} className="bg-slate-900 text-white px-8 py-4 rounded-2xl font-black text-xs flex items-center gap-3 active:scale-95 transition-all">
              {isAdding ? <X className="h-5 w-5" /> : <PlusCircle className="h-5 w-5" />}
              {isAdding ? 'إلغاء' : 'إضافة مطعم جديد'}
           </button>
        </div>
        {isAdding && (
          <div className="bg-slate-50 p-10 rounded-[3rem] mb-12 border-2 border-emerald-500/10 space-y-8 animate-in zoom-in">
             <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-4">
                   <label className="text-[10px] font-black text-slate-400 uppercase mr-4">صورة الغلاف</label>
                   <div onClick={() => fileRef.current?.click()} className="w-full h-48 bg-white rounded-3xl border-4 border-dashed border-slate-200 flex items-center justify-center cursor-pointer overflow-hidden relative group">
                      {restData.photoURL ? <img src={restData.photoURL} className="w-full h-full object-cover" /> : <Camera className="h-10 w-10 text-slate-300" />}
                   </div>
                   <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'PHOTO')} />
                </div>
                <div className="space-y-6">
                   <input value={restData.name} onChange={e => setRestData({...restData, name: e.target.value})} className="w-full bg-white rounded-2xl p-5 font-black outline-none shadow-sm" placeholder="اسم المطعم" />
                   <input value={restData.category} onChange={e => setRestData({...restData, category: e.target.value})} className="w-full bg-white rounded-2xl p-5 font-black outline-none shadow-sm" placeholder="مشويات، بيتزا، إلخ" />
                   <button onClick={saveRestaurant} disabled={loading} className="w-full bg-emerald-600 text-white py-6 rounded-3xl font-black shadow-2xl active:scale-95 transition-all">حفظ</button>
                </div>
             </div>
          </div>
        )}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
           {restaurants.map(rest => (
             <div key={rest.id} className="bg-slate-50 p-8 rounded-[3rem] border border-slate-100 space-y-8">
                <div className="flex justify-between items-start">
                   <div className="flex items-center gap-6">
                      <div className="w-20 h-20 bg-white rounded-[1.8rem] overflow-hidden shadow-lg border-4 border-white">{rest.photoURL ? <img src={rest.photoURL} className="w-full h-full object-cover" /> : <Building2 className="p-5 text-slate-200" />}</div>
                      <div><h4 className="font-black text-2xl text-slate-900">{rest.name}</h4><p className="text-sm font-bold text-emerald-600">{rest.category}</p></div>
                   </div>
                   <button onClick={async () => { if(confirm('حذف المطعم؟')) await deleteDoc(doc(db, "restaurants", rest.id)); }} className="p-4 bg-rose-50 text-rose-500 rounded-2xl"><Trash2 className="h-5 w-5" /></button>
                </div>
                <div className="space-y-4">
                   {rest.menu?.map(item => (
                     <div key={item.id} className="bg-white p-4 rounded-2xl flex justify-between items-center group shadow-sm">
                        <div className="flex items-center gap-4 text-right">
                           <div><p className="font-black text-sm text-slate-800">{item.name}</p><p className="text-xs font-bold text-emerald-600">{item.price} ج.م</p></div>
                        </div>
                     </div>
                   ))}
                   <div className="bg-emerald-50 p-6 rounded-[2rem] border border-emerald-100 flex gap-4">
                      <div className="flex-1 space-y-2"><input value={activeRestId === rest.id ? newItem.name : ''} onChange={e => { setActiveRestId(rest.id); setNewItem({...newItem, name: e.target.value}); }} placeholder="اسم الوجبة..." className="w-full bg-white p-3 rounded-xl text-xs font-bold outline-none text-right" dir="rtl" /><div className="flex gap-2"><input type="number" value={activeRestId === rest.id ? (newItem.price || '') : ''} onChange={e => { setActiveRestId(rest.id); setNewItem({...newItem, price: Number(e.target.value)}); }} placeholder="السعر" className="flex-1 bg-white p-3 rounded-xl text-xs font-bold outline-none text-right" dir="rtl" /><button onClick={() => addMenuItem(rest.id)} className="bg-emerald-600 text-white px-6 py-2 rounded-xl font-black text-[10px]">إضافة</button></div></div>
                   </div>
                </div>
             </div>
           ))}
        </div>
      </div>
    </div>
  );
};

