 */
const MonofiaZonesManager: React.FC = () => {
  const [zones, setZones] = useState<Zone[]>([]);
  const [activeZoneId, setActiveZoneId] = useState<string | null>(null);
  const [newVillageName, setNewVillageName] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    return onSnapshot(collection(db, "zones"), (snap) => {
      setZones(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Zone[]);
    });
  }, []);

  const createZone = async (name: string) => {
    setLoading(true);
    try {
      const id = `zone_${Date.now()}`;
      await setDoc(doc(db, "zones", id), {
        id, name, villages: [], 
        pricing: { basePrice: 15, pricePerKm: 8, minPrice: 20, sameVillagePrice: 15, multipliers: { TOKTOK: 1.0, MOTORCYCLE: 0.8, CAR: 2.2 } }
      });
    } catch (e) { alert('خطأ'); } finally { setLoading(false); }
  };

  const updateZonePricing = async (zoneId: string, pricing: any) => {
    try {
      await updateDoc(doc(db, "zones", zoneId), { pricing });
      alert('تم تحديث التسعيرة للمنطقة');
    } catch (e) { alert('خطأ'); }
  };

  const addVillage = async (zoneId: string) => {
    if (!newVillageName.trim()) return;
    const zone = zones.find(z => z.id === zoneId);
    if (!zone) return;
    const villages = [...(zone.villages || []), { id: `v_${Date.now()}`, name: newVillageName, center: { lat: 30.5, lng: 31.0 } }];
    await updateDoc(doc(db, "zones", zoneId), { villages });
    setNewVillageName('');
  };

  return (
    <div className="space-y-10 animate-reveal text-right" dir="rtl">
       <div className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-xl flex flex-col md:flex-row justify-between items-center gap-8">
