                             <span className="font-black text-slate-800">{v.name}</span>
                             <button onClick={async () => {
                               const zone = zones.find(z => z.id === activeZoneId);
                               if(zone) await updateDoc(doc(db, "zones", activeZoneId), { villages: zone.villages?.filter(vil => vil.id !== v.id) });
                             }} className="text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all"><Trash2 className="h-5 w-5" /></button>
                          </div>
                        ))}
                     </div>
                  </div>
               </div>
             ) : (
               <div className="h-full flex flex-col items-center justify-center py-40 text-slate-300 bg-white rounded-[4rem] border-4 border-dashed border-slate-50">
                  <MapIcon className="h-20 w-20 mb-6 animate-pulse" />
                  <p className="font-black text-xl tracking-tight">اختر مركزاً من القائمة الجانبية لإدارة إعداداته</p>
               </div>
             )}
          </div>
       </div>
    </div>
  );
};

/**
 * طلبات المدفوعات (سحب الأرباح)
 */
const PaymentRequests: React.FC = () => {
  const [requests, setRequests] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const q = query(collection(db, "payment_requests"), where("status", "==", "PENDING"), orderBy("createdAt", "desc"));
    return onSnapshot(q, (snap) => {
      setRequests(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })));
    });
  }, []);

  const handleApprove = async (req: any) => {
    if (!confirm(`تأكيد صرف ${req.amount} ج.م للكابتن ${req.userName}؟`)) return;
    setLoading(true);
    try {
      const batch = writeBatch(db);
      // 1. تحديث حالة الطلب
      batch.update(doc(db, "payment_requests", req.id), { status: 'APPROVED', approvedAt: Date.now() });
      // 2. تحديث المحفظة
      const userRef = doc(db, "users", req.userId);
      const userSnap = await getDoc(userRef);
      if (userSnap.exists()) {
        const userData = userSnap.data();
        const currentBalance = userData.wallet?.balance || 0;
        const currentWithdrawn = userData.wallet?.withdrawn || 0;
        batch.update(userRef, { 
          "wallet.balance": currentBalance - req.amount,
          "wallet.withdrawn": currentWithdrawn + req.amount
        });
      }
      // 3. إرسال تنبيه
      await addDoc(collection(db, "notifications"), {
        userId: req.userId, title: 'تم صرف أرباحك 💰', body: `تمت الموافقة على طلب سحب ${req.amount} ج.م وإضافتها لسجل مسحوباتك.`, type: 'SUCCESS', createdAt: Date.now(), read: false
      });
      await batch.commit();
      alert('تمت العملية بنجاح وتحديث المحافظ');
    } catch (e) { alert('خطأ فني'); } finally { setLoading(false); }
  };

  return (
    <div className="bg-white p-12 rounded-[4rem] border border-slate-100 shadow-2xl space-y-10 animate-reveal text-right" dir="rtl">
       <div className="flex justify-between items-center px-4">
          <h3 className="text-2xl font-black text-slate-900 flex items-center gap-4"><Banknote className="text-emerald-500" /> طلبات صرف الأرباح المعلقة</h3>
          <span className="bg-emerald-100 text-emerald-700 px-6 py-2 rounded-full font-black text-[10px] uppercase tracking-widest">{requests.length} طلب جديد</span>
       </div>
       <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {requests.map(req => (
            <div key={req.id} className="p-8 bg-slate-50 rounded-[3rem] border-2 border-transparent hover:border-emerald-500 hover:bg-white transition-all shadow-sm">
               <div className="flex justify-between items-start mb-6">
                  <div className="text-right">
                     <p className="font-black text-lg text-slate-900 leading-none mb-1">{req.userName}</p>
                     <p className="text-xs font-bold text-slate-400" dir="ltr">{req.userPhone}</p>
                  </div>
                  <div className="bg-slate-950 text-emerald-400 px-4 py-2 rounded-xl font-black text-lg">{req.amount} <span className="text-[10px] opacity-40">ج.م</span></div>
               </div>
               <div className="flex gap-2">
                  <button onClick={() => handleApprove(req)} disabled={loading} className="flex-1 bg-emerald-600 text-white py-4 rounded-2xl font-black text-xs shadow-lg active:scale-95 transition-all flex items-center justify-center gap-2">
                    {loading ? <Loader2 className="animate-spin h-4 w-4" /> : <><CheckCircle className="h-4 w-4" /> موافقة وصرف</>}
                  </button>
                  <button onClick={async () => { if(confirm('رفض الطلب؟')) await updateDoc(doc(db, "payment_requests", req.id), { status: 'REJECTED' }); }} className="bg-rose-50 text-rose-500 px-6 py-4 rounded-2xl font-black text-xs active:scale-95 transition-all">رفض</button>
               </div>
            </div>
          ))}
          {requests.length === 0 && (
            <div className="col-span-full py-20 text-center text-slate-300 font-black border-4 border-dashed border-slate-50 rounded-[3rem]">لا توجد طلبات سحب حالياً</div>
          )}
       </div>
    </div>
  );
};

