 */
const OrdersMonitor: React.FC<{ orders: Order[] }> = ({ orders }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filter, setFilter] = useState<'ALL' | 'ACTIVE' | 'DONE' | 'CANCELLED'>('ALL');

  const filtered = orders.filter(o => {
    const matchesSearch = o.customerPhone.includes(searchTerm) || (o.driverName || '').includes(searchTerm);
    const isLive = ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status);
    if (filter === 'ACTIVE') return matchesSearch && isLive;
    if (filter === 'DONE') return matchesSearch && [OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED].includes(o.status);
    if (filter === 'CANCELLED') return matchesSearch && o.status === OrderStatus.CANCELLED;
    return matchesSearch;
  });

  return (
    <div className="space-y-8 animate-reveal text-right" dir="rtl">
       <div className="flex flex-col md:flex-row justify-between items-center gap-6">
          <div className="relative flex-1 w-full max-w-lg group">
             <Search className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5 group-focus-within:text-emerald-500 transition-colors" />
             <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="بحث برقم الهاتف أو اسم الكابتن..." className="w-full bg-white border-2 border-slate-50 rounded-[2.5rem] py-6 pr-14 pl-8 font-black text-sm outline-none focus:border-emerald-500 shadow-sm" />
          </div>
          <div className="flex gap-2 bg-white p-2 rounded-[2rem] shadow-sm border border-slate-50">
             {['ALL', 'ACTIVE', 'DONE', 'CANCELLED'].map(f => (
               <button key={f} onClick={() => setFilter(f as any)} className={`px-8 py-3.5 rounded-[1.5rem] text-[11px] font-black transition-all ${filter === f ? 'bg-slate-900 text-white shadow-xl' : 'text-slate-400 hover:text-slate-600'}`}>{f === 'ALL' ? 'الكل' : f === 'ACTIVE' ? 'نشط' : f === 'DONE' ? 'منفذ' : 'ملغي'}</button>
             ))}
          </div>
       </div>

       <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {filtered.map(order => (
            <div key={order.id} className="bg-white rounded-[3.5rem] border border-slate-50 shadow-xl overflow-hidden hover:border-emerald-500 transition-all group">
               <div className="bg-slate-50 p-6 flex justify-between items-center group-hover:bg-slate-900 group-hover:text-white transition-all">
                  <div className="text-right">
                    <p className="text-[10px] font-black opacity-40 uppercase tracking-widest mb-1">طلب #{order.id.slice(-5)}</p>
                    <p className="text-2xl font-black">{order.price} <span className="text-xs opacity-40">ج.م</span></p>
                  </div>
                  <span className={`px-5 py-2 rounded-full text-[9px] font-black uppercase tracking-widest ${order.status === 'DELIVERED' ? 'bg-emerald-100 text-emerald-600' : 'bg-blue-100 text-blue-600'}`}>{order.status}</span>
               </div>
               <div className="p-8 space-y-6">
                  <div className="flex gap-5 items-start">
                     <div className="bg-emerald-50 p-3 rounded-xl text-emerald-600 shrink-0"><MapPin className="h-5 w-5" /></div>
                     <div className="flex-1 text-right">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">المسار</p>
                        <p className="text-sm font-black text-slate-800 leading-tight">{order.pickup?.villageName} ← {order.dropoff?.villageName}</p>
                     </div>
                  </div>
                  <div className="grid grid-cols-2 gap-4 border-t border-slate-50 pt-6">
                     <div>
                        <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2">العميل</p>
