                        <div className="flex gap-2 mt-3">
                           <a href={`tel:${order.customerPhone}`} className="bg-slate-100 p-2.5 rounded-xl text-slate-500 hover:text-emerald-600"><PhoneCall className="h-4 w-4" /></a>
                           <a href={`https://wa.me/2${order.customerPhone}`} target="_blank" className="bg-slate-100 p-2.5 rounded-xl text-slate-500 hover:text-emerald-600"><MessageCircle className="h-4 w-4" /></a>
                        </div>
                     </div>
                     <div className="text-left">
                        <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2">الكابتن</p>
                        {order.driverId ? (
                          <>
