/**
 * وظيفة لتطهير البيانات القادمة من Firestore من أي مراجع دائرية أو كائنات داخلية
 * تضمن هذه الوظيفة إمكانية تحويل الكائن إلى JSON بدون أخطاء
 */
export const stripFirestore = (data: any, seen = new WeakSet()): any => {
  if (data === null || data === undefined) return data;

  // التعامل مع القيم البدائية (string, number, boolean)
  if (typeof data !== 'object') return data;

  // منع التكرار الدائري باستخدام WeakSet
  if (seen.has(data)) return undefined;

  // التحقق من كونه كائناً داخلياً لـ Firebase عبر أسماء الـ Constructor المصغرة
  if (data.constructor && data.constructor.name && (data.constructor.name.length < 4 || data.constructor.name.includes('Firestore'))) {
     if (data.toMillis && typeof data.toMillis === 'function') return data.toMillis();
     if (data.path && typeof data.path === 'string') return data.path;
     // إذا كان كائناً داخلياً غير معروف، لا نقوم بمعالجته ككائن بسيط لتجنب الدوائر
     if (data.constructor.name !== 'Object' && data.constructor.name !== 'Array') return undefined;
  }

  // التعامل مع كائنات Timestamp الخاصة بـ Firebase
  if (data.toMillis && typeof data.toMillis === 'function') {
    return data.toMillis();
  }

  // التعامل مع مراجع المستندات (DocumentReference) - نأخذ المسار فقط
  if (data.path && typeof data.path === 'string') {
    return data.path;
  }

  // التعامل مع التواريخ
  if (data instanceof Date) {
    return data.getTime();
  }

  // التعامل مع المصفوفات
  if (Array.isArray(data)) {
    seen.add(data);
    return data.map(item => stripFirestore(item, seen)).filter(i => i !== undefined);
  }

  // التحقق مما إذا كان كائناً بسيطاً (Plain Object)
  const proto = Object.getPrototypeOf(data);
  // نوسع الفحص ليشمل الكائنات التي ليس لها نموذج أولي (null) أو النموذج الأساسي
  if (proto === null || proto === Object.prototype) {
    seen.add(data);
    const stripped: any = {};
    for (const key in data) {
      if (Object.prototype.hasOwnProperty.call(data, key)) {
        // تخطي الخصائص الداخلية لـ Firebase التي تبدأ بـ _ أو $ أو تحتوي على مسميات مشفرة (مثل Q$1)
        if (key.startsWith('_') || key.startsWith('$') || key.includes('$')) continue;

        const val = stripFirestore(data[key], seen);
        // نتأكد من عدم إضافة وظائف أو مراجع معقدة لم يتم تطهيرها
        if (val !== undefined && typeof val !== 'function') {
          stripped[key] = val;
        }
      }
    }
    return stripped;
  }

  // لأي كائن معقد آخر (مثل Snapshots أو Classes)، نرجعه كـ undefined لمنع المراجع الدائرية
  return undefined;
};

/**
 * حساب المسافة بين نقطتين جغرافيتين بالكيلومتر (صيغة هافرسين)
 */
export const calculateDistance = (lat1: number, lon1: number, lat2: number, lon2: number): number => {
  const R = 6371; // نصف قطر الأرض بالكيلومتر
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) + 
            Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * 
            Math.sin(dLon / 2) * Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return parseFloat((R * c).toFixed(1));
};

