const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [connectionError, setConnectionError] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [showSupport, setShowSupport] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);
  const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);

  useEffect(() => {
    const unsubscribeAuth = onAuthStateChanged(auth, async (fbUser) => {
      try {
        if (fbUser) {
          await fetchUserData(fbUser.uid);
        } else {
          setUser(null);
          setLoading(false);
        }
      } catch (error) {
        console.error("Auth error:", error);
        setLoading(false);
      }
    });
    return () => unsubscribeAuth();
  }, []);

  const fetchUserData = async (uid: string) => {
    // نستخدم onSnapshot بدلاً من getDoc لضمان استقرار العمل في وضع الأوفلاين
    const userRef = doc(db, "users", uid);

    const unsubscribe = onSnapshot(userRef, { includeMetadataChanges: true }, (docSnap) => {
      if (docSnap.exists()) {
        const data = stripFirestore(docSnap.data()) as User;
        setUser(data);
        setLoading(false);
        setConnectionError(false);

        // مراقبة الإشعارات
        const q = query(collection(db, "notifications"), where("userId", "in", [data.id, "ALL", data.role]));
        onSnapshot(q, (snap) => {
          const unread = snap.docs.filter(d => !d.data().read).length;
          setUnreadCount(unread);
        });
      } else {
        setUser(null);
        setLoading(false);
      }
    }, (error) => {
      console.error("Error watching user data:", error);
      if (!navigator.onLine) {
        setConnectionError(true);
      }
      setLoading(false);
    });

    return unsubscribe;
  };

  const handleLogout = () => {
    signOut(auth);
    setIsLogoutModalOpen(false);
  };

  if (loading) return (
    <div className="min-h-screen bg-[#10b981] flex flex-col items-center justify-center p-6 text-center">
      <div className="bg-white/20 p-8 md:p-12 rounded-[4rem] md:rounded-[5rem] backdrop-blur-3xl mb-8 md:mb-12 border border-white/30 shadow-2xl animate-pulse">
         <img src={APP_LOGO_ICON} alt="Loading..." className="h-20 w-20 md:h-32 md:w-32 object-contain" />
      </div>
      <h2 className="text-white font-black text-4xl md:text-5xl tracking-tighter mb-4">وصـــلــهــا</h2>
      <div className="flex items-center gap-3 bg-black/10 px-6 py-2.5 rounded-full backdrop-blur-md border border-white/10">
        <Loader2 className="h-4 w-4 text-white animate-spin" />
        <p className="text-white/80 font-bold text-[9px] uppercase tracking-widest">جاري التحميل...</p>
      </div>
    </div>
  );

  if (connectionError) return (
    <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-10 text-center">
       <WifiOff className="h-16 w-16 text-rose-500 mb-6" />
       <h2 className="text-xl font-black text-slate-800 mb-4">لا يوجد اتصال بالإنترنت</h2>
       <button onClick={() => window.location.reload()} className="bg-[#10b981] text-white px-8 py-4 rounded-[1.8rem] font-black shadow-xl flex items-center gap-3 active:scale-95"><RefreshCcw className="h-4 w-4" /> تحديث</button>
    </div>
  );

  if (!user) return <Login onLogin={(u) => setUser(stripFirestore(u))} />;

  const getDashboard = () => {
    if (showNotifications) return <NotificationsView user={user} onBack={() => setShowNotifications(false)} />;
    if (showSupport) return <SupportView user={user} onBack={() => setShowSupport(false)} />;

    switch (user.role) {
      case 'ADMIN': return <SuperAdminDashboard user={user} />;
      case 'OPERATOR': return <OperatorDashboard user={user} />;
      case 'DRIVER': return <CourierDashboard user={user} />;
      case 'CUSTOMER': return <CustomerDashboard user={user} />;
      default: return <div className="p-20 text-center font-black">الحساب غير مفعل</div>;
    }
  };

  return (
    <HashRouter>
      <LogoutModal 
        isOpen={isLogoutModalOpen} 
        onConfirm={handleLogout} 
        onCancel={() => setIsLogoutModalOpen(false)} 
      />
      <div className="app-container">
        <header className="bg-white/95 backdrop-blur-md border-b border-slate-100 sticky top-0 z-[110] px-4 md:px-6 h-[70px] md:h-[90px] flex items-center shadow-sm">
          <div className="max-w-7xl mx-auto w-full flex items-center justify-between">
            <Link to="/" onClick={() => { setShowNotifications(false); setShowSupport(false); }} className="flex items-center gap-3 md:gap-5">
              <div className="bg-[#10b981] p-2 md:p-3 rounded-2xl md:rounded-[1.8rem] shadow-lg border-2 md:border-4 border-emerald-50">
                <img src={APP_LOGO_ICON} alt="Logo" className="h-6 w-6 md:h-9 md:w-9" />
              </div>
              <div className="flex flex-col">
                <h1 className="font-black text-lg md:text-2xl text-slate-800 tracking-tighter leading-none mb-0.5 md:mb-1">وصـــلــهــا</h1>
                <span className="text-[7px] md:text-[9px] font-black text-slate-300 uppercase tracking-widest">المنوفية</span>
              </div>
            </Link>
            <div className="flex items-center gap-1.5 md:gap-4">
              <button onClick={() => setShowSupport(true)} className="p-3 md:p-4 bg-slate-50 text-slate-400 rounded-xl md:rounded-2xl border border-slate-100 transition-all active:scale-90 hover:text-emerald-600">
                <MessageCircle className="h-5 w-5 md:h-6 md:w-6" />
              </button>
              <button onClick={() => setShowNotifications(true)} className={`p-3 md:p-4 bg-slate-50 text-slate-400 rounded-xl md:rounded-2xl relative border border-slate-100 transition-all active:scale-90 hover:text-emerald-600`}>
                <Bell className="h-5 w-5 md:h-6 md:w-6" />
                {unreadCount > 0 && (
                  <span className="absolute -top-1 -right-1 bg-rose-500 text-white w-5 h-5 md:w-6 md:h-6 rounded-full text-[8px] md:text-[10px] flex items-center justify-center border-2 border-white font-black">{unreadCount}</span>
                )}
              </button>
              <button onClick={() => setIsLogoutModalOpen(true)} className="p-3 md:p-4 bg-rose-50 text-rose-500 rounded-xl md:rounded-2xl border border-rose-100 transition-all active:scale-90 hover:bg-rose-100">
                <LogOut className="h-5 w-5 md:h-6 md:w-6 rotate-180" />
              </button>
            </div>
          </div>
        </header>
        <main className="main-content">
          <Routes>
            <Route path="/" element={getDashboard()} />
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </main>
      </div>
    </HashRouter>
  );
};

export default App;

@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;900&display=swap');

:root {
  --brand-primary: #FF6B35;   /* برتقالي دافئ */
  --brand-secondary: #2C3E50; /* أزرق داكن */
  --brand-accent: #F7B801;    /* أصفر ذهبي */
  --brand-emerald: #10b981;   /* أخضر وصلها */
  --bg-light: #F8F9FA;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: 'Cairo', sans-serif;
  direction: rtl;
  background-color: var(--bg-light);
  color: var(--brand-secondary);
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

/* --- Animations --- */

@keyframes motorcycle-entrance {
  0% { transform: translateX(120%) scale(0.8); opacity: 0; }
  60% { transform: translateX(-10%) rotate(-5deg); }
  80% { transform: translateX(5%) rotate(2deg); }
  100% { transform: translateX(0) rotate(0); opacity: 1; }
}

@keyframes wheel-spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@keyframes logo-glow {
  0%, 100% { filter: drop-shadow(0 0 5px rgba(255, 107, 53, 0.2)); }
  50% { filter: drop-shadow(0 0 20px rgba(255, 107, 53, 0.6)); }
}

@keyframes fade-up {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-5px); }
  75% { transform: translateX(5px); }
}

.animate-motorcycle { animation: motorcycle-entrance 1.2s cubic-bezier(0.23, 1, 0.32, 1) forwards; }
.animate-wheel { animation: wheel-spin 0.8s linear infinite; transform-origin: center; }
.animate-glow { animation: logo-glow 3s ease-in-out infinite; }
.stagger-fade-in > * { opacity: 0; animation: fade-up 0.6s ease forwards; }
.stagger-fade-in > *:nth-child(1) { animation-delay: 0.1s; }
.stagger-fade-in > *:nth-child(2) { animation-delay: 0.2s; }
.stagger-fade-in > *:nth-child(3) { animation-delay: 0.3s; }
.stagger-fade-in > *:nth-child(4) { animation-delay: 0.4s; }
.stagger-fade-in > *:nth-child(5) { animation-delay: 0.5s; }

/* --- UI Utilities --- */

.input-field {
  width: 100%;
  padding: 1.25rem 1.5rem;
  border-radius: 1.25rem;
  border: 2px solid #e2e8f0;
  background: white;
  font-weight: 700;
  font-family: 'Cairo';
  transition: all 0.3s ease;
  outline: none;
}

.input-field:focus {
  border-color: var(--brand-primary);
  box-shadow: 0 0 0 4px rgba(255, 107, 53, 0.1);
  transform: translateY(-2px);
}

.input-error {
  border-color: #ef4444 !important;
  animation: shake 0.4s ease;
}

.input-success {
  border-color: #10b981 !important;
}

.btn-primary {
  background: var(--brand-primary);
  color: white;
  padding: 1.25rem;
  border-radius: 1.25rem;
  font-weight: 900;
  width: 100%;
  border: none;
  cursor: pointer;
  box-shadow: 0 10px 20px -5px rgba(255, 107, 53, 0.4);
  transition: all 0.3s ease;
}

.btn-primary:hover:not(:disabled) {
  transform: translateY(-3px) scale(1.02);
  box-shadow: 0 15px 30px -5px rgba(255, 107, 53, 0.5);
}

.btn-primary:active { transform: translateY(0) scale(0.98); }
.btn-primary:disabled { opacity: 0.5; cursor: not-allowed; }

.no-scrollbar::-webkit-scrollbar { display: none; }
.no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }

import React, { useState, useEffect, useMemo } from 'react';

// Types
import type { User, VehicleType, UserRole } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Services
import { auth, db } from '../services/firebase';
import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword 
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { doc, getDoc, setDoc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Icons
import { 
  Bike, Eye, EyeOff, User as UserIcon, 
  Smartphone, Lock, MapPin, Building, 
  ChevronDown, CheckCircle2, AlertCircle,
  Loader2, ArrowLeft, ArrowRight, Car,
  Zap, Info, Smartphone as PhoneIcon
} from 'lucide-react';

const MotorcycleLogo = () => (
  <div className="relative w-32 h-32 mx-auto mb-8 animate-motorcycle animate-glow">
    <svg viewBox="0 0 100 100" className="w-full h-full text-[#FF6B35]">
      {/* جسم الموتوسيكل */}
      <path d="M20 70 L35 55 L65 55 L80 70" fill="none" stroke="currentColor" strokeWidth="4" />
      <path d="M40 55 L50 30 L65 30 L60 55" fill="none" stroke="currentColor" strokeWidth="4" />
      {/* العجلات مع أنيميشن */}
      <g className="animate-wheel">
        <circle cx="25" cy="75" r="10" fill="none" stroke="currentColor" strokeWidth="4" strokeDasharray="4 2" />
        <circle cx="25" cy="75" r="3" fill="currentColor" />
      </g>
      <g className="animate-wheel" style={{ animationDelay: '0.1s' }}>
        <circle cx="75" cy="75" r="10" fill="none" stroke="currentColor" strokeWidth="4" strokeDasharray="4 2" />
        <circle cx="75" cy="75" r="3" fill="currentColor" />
      </g>
      {/* مقود */}
      <path d="M65 30 L75 25" fill="none" stroke="currentColor" strokeWidth="4" />
    </svg>
  </div>
);

const PasswordStrength = ({ password }: { password: string }) => {
  const strength = useMemo(() => {
    if (!password) return 0;
    let s = 0;
    if (password.length >= 8) s++;
    if (/[a-zA-Z]/.test(password)) s++;
    if (/[0-9]/.test(password)) s++;
    return s;
  }, [password]);

  const colors = ['bg-gray-200', 'bg-rose-500', 'bg-amber-500', 'bg-emerald-500'];
  const labels = ['', 'ضعيفة', 'متوسطة', 'قوية'];

  return (
    <div className="mt-2 flex items-center gap-2">
      <div className="flex-1 flex gap-1 h-1">
        {[1, 2, 3].map(i => (
          <div key={i} className={`flex-1 rounded-full transition-all duration-500 ${i <= strength ? colors[strength] : 'bg-gray-100'}`} />
        ))}
      </div>
      <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{labels[strength]}</span>
    </div>
  );
};

const Login: React.FC<{ onLogin: (user: User) => void }> = ({ onLogin }) => {
  const [isSignUp, setIsSignUp] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Form State
  const [formData, setFormData] = useState({
    name: '', phone: '', email: '', password: '', 
    confirmPassword: '', governorate: 'المنوفية', 
    district: '', village: '', 
    role: 'CUSTOMER' as UserRole, vehicle: 'MOTORCYCLE' as VehicleType,
    rememberMe: false
  });

  // Database of locations
  const locations = {
    'المنوفية': ['أشمون', 'شبين الكوم', 'قويسنا', 'بركة السبع', 'منوف'],
    'القاهرة': ['المعادي', 'مدينة نصر', 'التجمع الخامس', 'حلوان'],
    'الجيزة': ['الدقي', 'المهندسين', '6 أكتوبر']
  };

  const validate = (field?: string) => {
    let newErrors: Record<string, string> = { ...errors };

    if (!field || field === 'name') {
      const parts = formData.name.trim().split(/\s+/);
      if (parts.length < 4) newErrors.name = "برجاء إدخال الاسم رباعي";
      else delete newErrors.name;
    }

    if (!field || field === 'phone') {
      const phoneRegex = /^(010|011|012|015)[0-9]{8}$/;
      if (!phoneRegex.test(formData.phone)) newErrors.phone = "رقم الهاتف يجب أن يبدأ بـ 010 أو 011 أو 012 أو 015";
      else delete newErrors.phone;
    }

    if (!field || field === 'password') {
      const passRegex = /^(?=.*[A-Za-z])(?=.*\d)[A-Za-z\d]{8,}$/;
      if (!passRegex.test(formData.password)) newErrors.password = "كلمة المرور يجب ألا تقل عن 8 أحرف وتحتوي على حرف ورقم";
      else delete newErrors.password;
    }

    if (!field || field === 'confirmPassword') {
      if (formData.confirmPassword !== formData.password) newErrors.confirmPassword = "كلمة المرور غير متطابقة";
      else delete newErrors.confirmPassword;
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) return;

    setLoading(true);
    try {
      if (isSignUp) {
        // إنشاء حساب برمجياً ببريد وهمي يعتمد على الهاتف لسهولة الدخول
        const fakeEmail = `${formData.phone}@wasalha.com`;
        const userCredential = await createUserWithEmailAndPassword(auth, fakeEmail, formData.password);
        const userData: User = {
          id: userCredential.user.uid,
          email: fakeEmail,
          phone: formData.phone,
          name: formData.name,
          role: formData.role,
          status: formData.role === 'DRIVER' ? 'PENDING_APPROVAL' : 'APPROVED',
          vehicleType: formData.role === 'DRIVER' ? formData.vehicle : undefined,
          wallet: { balance: 0, totalEarnings: 0, withdrawn: 0 }
        };
        await setDoc(doc(db, "users", userCredential.user.uid), userData);

        // إرسال تنبيه واتساب للإدارة (محاكاة لما في النسخة السابقة)
        if (formData.role === 'DRIVER') {
          const msg = `طلب انضمام كابتن جديد:\nالاسم: ${formData.name}\nالموبايل: ${formData.phone}\nالمنطقة: ${formData.governorate} - ${formData.district}`;
          window.open(`https://wa.me/201065019364?text=${encodeURIComponent(msg)}`, '_blank');
        }

        onLogin(userData);
      } else {
        const fakeEmail = `${formData.phone}@wasalha.com`;
        const userCredential = await signInWithEmailAndPassword(auth, fakeEmail, formData.password);
        const userSnap = await getDoc(doc(db, "users", userCredential.user.uid));
        if (userSnap.exists()) {
          onLogin(stripFirestore(userSnap.data()) as User);
        }
      }
    } catch (err: any) {
      setErrors({ auth: "خطأ في البيانات، تأكد من رقم الهاتف وكلمة المرور." });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4 md:p-8 overflow-y-auto no-scrollbar">
      <div className="w-full max-w-xl bg-white rounded-[3rem] shadow-2xl overflow-hidden animate-reveal border border-slate-100">

        {/* Header / Logo Section */}
        <div className="bg-[#2C3E50] p-12 text-center relative overflow-hidden">
          <div className="absolute inset-0 bg-[#FF6B35] opacity-5 transform -skew-y-12 translate-y-20 scale-150"></div>
          <MotorcycleLogo />
          <h1 className="text-4xl font-black text-white tracking-tighter">وصـــلــهــا</h1>
          <p className="text-emerald-400 font-bold text-[10px] uppercase tracking-[0.4em] mt-2">نظام التوصيل الذكي بالمنوفية</p>
        </div>

        <div className="p-8 md:p-12">
          {errors.auth && (
            <div className="mb-6 p-5 bg-rose-50 border-r-4 border-rose-500 rounded-2xl flex items-center gap-4 text-rose-600 animate-in slide-in-from-top">
              <AlertCircle className="shrink-0" />
              <p className="text-xs font-black">{errors.auth}</p>
            </div>
          )}

          <form onSubmit={handleAuth} className="space-y-6 stagger-fade-in">
            {isSignUp ? (
              /* --- SIGN UP FIELDS --- */
              <>
                <div className="space-y-1">
                  <div className="relative">
                    <UserIcon className={`absolute right-5 top-1/2 -translate-y-1/2 h-5 w-5 transition-colors ${errors.name ? 'text-rose-500' : 'text-slate-300'}`} />
                    <input 
                      autoFocus
                      placeholder="الاسم الرباعي (أحمد محمد علي حسن)"
                      className={`input-field pr-14 ${errors.name ? 'input-error' : formData.name.split(' ').length >= 4 ? 'input-success' : ''}`}
                      value={formData.name}
                      onChange={e => setFormData({...formData, name: e.target.value})}
                      onBlur={() => validate('name')}
                    />
                  </div>
                  {errors.name && <span className="text-[9px] font-black text-rose-500 px-4">{errors.name}</span>}
                </div>

                <div className="space-y-1">
                  <div className="relative">
                    <Smartphone className={`absolute right-5 top-1/2 -translate-y-1/2 h-5 w-5 transition-colors ${errors.phone ? 'text-rose-500' : 'text-slate-300'}`} />
                    <input 
                      type="tel"
                      placeholder="رقم الهاتف (01xxxxxxxxx)"
                      className={`input-field pr-14 text-left font-mono ${errors.phone ? 'input-error' : ''}`}
                      value={formData.phone}
                      dir="ltr"
                      onChange={e => setFormData({...formData, phone: e.target.value})}
                      onBlur={() => validate('phone')}
                    />
                  </div>
                  {errors.phone && <span className="text-[9px] font-black text-rose-500 px-4">{errors.phone}</span>}
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="relative">
                    <Lock className={`absolute right-5 top-1/2 -translate-y-1/2 h-5 w-5 ${errors.password ? 'text-rose-500' : 'text-slate-300'}`} />
                    <input 
                      type={showPassword ? "text" : "password"}
                      placeholder="كلمة المرور"
                      className={`input-field pr-14 ${errors.password ? 'input-error' : ''}`}
                      value={formData.password}
                      onChange={e => setFormData({...formData, password: e.target.value})}
                    />
                    <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300">
                      {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
                    </button>
                    <PasswordStrength password={formData.password} />
                  </div>

                  <div className="relative">
                    <Lock className={`absolute right-5 top-1/2 -translate-y-1/2 h-5 w-5 ${errors.confirmPassword ? 'text-rose-500' : 'text-slate-300'}`} />
                    <input 
                      type={showPassword ? "text" : "password"}
                      placeholder="تأكيد كلمة المرور"
                      className={`input-field pr-14 ${errors.confirmPassword ? 'input-error' : ''}`}
                      value={formData.confirmPassword}
                      onChange={e => setFormData({...formData, confirmPassword: e.target.value})}
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="relative">
                    <Building className="absolute right-5 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-300 pointer-events-none" />
                    <select 
                      className="input-field pr-14 appearance-none"
                      value={formData.governorate}
                      onChange={e => setFormData({...formData, governorate: e.target.value, district: ''})}
                    >
                      {Object.keys(locations).map(gov => <option key={gov} value={gov}>{gov}</option>)}
                    </select>
                    <ChevronDown className="absolute left-5 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-300 pointer-events-none" />
                  </div>
                  <div className="relative">
                    <MapPin className="absolute right-5 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-300 pointer-events-none" />
                    <select 
                      className="input-field pr-14 appearance-none"
                      value={formData.district}
                      onChange={e => setFormData({...formData, district: e.target.value})}
                    >
                      <option value="">اختر المركز</option>
                      {locations[formData.governorate as keyof typeof locations].map(dist => <option key={dist} value={dist}>{dist}</option>)}
                    </select>
                    <ChevronDown className="absolute left-5 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-300 pointer-events-none" />
                  </div>
                </div>

                <div className="relative">
                   <MapPin className="absolute right-5 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-300" />
                   <input 
                     placeholder="اسم القرية أو المنطقة بالتفصيل"
                     className="input-field pr-14"
                     value={formData.village}
                     onChange={e => setFormData({...formData, village: e.target.value})}
                   />
                </div>

                <div className="flex bg-slate-100 p-2 rounded-2xl">
                  <button type="button" onClick={() => setFormData({...formData, role: 'CUSTOMER'})} className={`flex-1 py-4 rounded-xl font-black text-xs transition-all ${formData.role === 'CUSTOMER' ? 'bg-white text-[#FF6B35] shadow-lg' : 'text-slate-400'}`}>عميل (Customer)</button>
                  <button type="button" onClick={() => setFormData({...formData, role: 'DRIVER'})} className={`flex-1 py-4 rounded-xl font-black text-xs transition-all ${formData.role === 'DRIVER' ? 'bg-white text-[#FF6B35] shadow-lg' : 'text-slate-400'}`}>كابتن (Captain)</button>
                </div>

                {formData.role === 'DRIVER' && (
                  <div className="relative animate-in zoom-in duration-300">
                    <label className="text-[10px] font-black text-slate-400 block px-4 mb-2 uppercase tracking-widest">نوع المركبة</label>
                    <div className="grid grid-cols-3 gap-3">
                      {[
                        { id: 'MOTORCYCLE', icon: <Bike />, label: 'موتوسيكل' },
                        { id: 'CAR', icon: <Car />, label: 'سيارة' },
                        { id: 'TOKTOK', icon: <Zap />, label: 'دراجة/أخرى' }
                      ].map(v => (
                        <button 
                          key={v.id} 
                          type="button" 
                          onClick={() => setFormData({...formData, vehicle: v.id as VehicleType})} 
                          className={`p-4 rounded-2xl flex flex-col items-center gap-2 border-2 transition-all ${formData.vehicle === v.id ? 'border-[#FF6B35] bg-orange-50 text-[#FF6B35]' : 'border-slate-100 bg-slate-50 text-slate-300'}`}
                        >
                          {v.icon}
                          <span className="text-[9px] font-black">{v.label}</span>
                        </button>
                      ))}
                    </div>
                  </div>
                )}
              </>
            ) : (
              /* --- LOGIN FIELDS --- */
              <>
                <div className="space-y-1">
                  <div className="relative">
                    <Smartphone className="absolute right-5 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-300" />
                    <input 
